window.NAHWOO25={"manifest":{"title":"NAHWOO Level 25 — Buku Saku Membaca Kitab Gundul","edition":"R1 — untuk ACC editorial & layout","original_baseline_sha":"00cb13d18ad9dcdf8eb5b2de4a441db4e1162581","format":"special reference level; 10 sublevels, no scored evaluation until pedagogical approval","reference_book":{"title":"Panduan Praktis Membaca dan Menerjemah Kitab Arab","author":"Muhammad Abdul Fatah","use":"inspiration for detection charts, practical tips, workflow; content authored anew; not transcription"},"total_source_levels":24,"total_source_sublevels":240,"total_special_sublevels":11,"total_rule_cards":139,"github_uploaded":false},"sublevels":[{"id":"L25-S01","index":1,"title":"Peta Baca Kitab: Jangan Mulai dari Harakat","hook":"Kalau kita bertemu satu kalimat gundul, godaan terbesarnya adalah memasang dhammah dan fathah sambil berharap cocok. Padahal harakat akhir itu hasil analisis, bukan titik berangkatnya. Kita baca peta kecil ini dulu.","mission":"Mendapat urutan kerja yang bisa diulang setiap kali berjumpa kalimat baru.","intro":"Cara paling aman: lihat yang tampak, susun hubungannya, baru putuskan bunyi akhir dan terjemahnya.","cards":[{"id":"R01","term":"1. Potong klausa","ciri":"Cari batas kata dan penghubung seperti وَ، ثُمَّ، فَـ.","harakat":"Belum menentukan harakat akhir.","arti":"Pisahkan peristiwa dan keterangan sebelum menerjemahkan.","arab":"كَتَبَ الطَّالِبُ ثُمَّ خَرَجَ","terjemah":"Pelajar itu menulis, lalu keluar.","rujukan":["L12-S02","L17-S01","L17-S07"]},{"id":"R02","term":"2. Kenali tiga keluarga","ciri":"Nama/sifat: isim; kejadian: fi‘il; kata penghubung: huruf.","harakat":"Jangan menyamakan harakat isim dan fi‘il.","arti":"Temukan siapa/apa, melakukan apa, dan hubungan ke mana.","arab":"كَتَبَ الطَّالِبُ فِي الْفَصْلِ","terjemah":"Pelajar itu menulis di kelas.","rujukan":["L01-S03","L12-S03","L12-S05"]},{"id":"R03","term":"3. Cari ‘amil","ciri":"Temukan huruf jar, إِنَّ, كَانَ, atau unsur pengubah fi‘il.","harakat":"‘Amil dapat menentukan status i‘rab kata lain.","arti":"Terjemahkan hubungan yang dibentuknya, bukan tiap kata terpisah.","arab":"إِنَّ الْعِلْمَ نُورٌ","terjemah":"Sesungguhnya ilmu itu cahaya.","rujukan":["L14-S01","L14-S02","L14-S09"]},{"id":"R04","term":"4. Temukan peran","ciri":"Tandai mubtada’, khabar, fa‘il, objek, sifat, atau mudhaf ilaih.","harakat":"Peran menentukan rafa‘, nashab, jar, atau jazm bila berlaku.","arti":"Susun pelaku, tindakan, objek, dan keterangan.","arab":"قَرَأَ الْوَلَدُ الْكِتَابَ","terjemah":"Anak itu membaca buku.","rujukan":["L03-S02","L03-S03","L04-S03","L04-S05"]},{"id":"R05","term":"5. Cek bentuk kata","ciri":"Mufrad, mutsanna, jamak salim, jamak taksir, atau kata mabni?","harakat":"Tanda i‘rab bisa huruf pengganti, bukan selalu vokal.","arti":"Jumlah orang/barang jangan hilang dalam terjemahan.","arab":"جَاءَ الْمُعَلِّمَانِ","terjemah":"Dua guru itu datang.","rujukan":["L02-S06","L02-S07","L08-S07"]},{"id":"R06","term":"6. Pasang harakat berdasarkan bukti","ciri":"Setelah fungsi dan bentuk diketahui, baru pilih tanda akhirnya.","harakat":"Contoh dasar: fa‘il marfu‘, maf‘ul manshub, sesudah jar majrur.","arti":"Bunyi akhir mendukung penentuan peran.","arab":"ذَهَبَ الطَّالِبُ إِلَى الْمَسْجِدِ","terjemah":"Pelajar itu pergi ke masjid.","rujukan":["L08-S09","L12-S08","L24-S06"]},{"id":"R07","term":"7. Cari akar untuk kosakata","ciri":"Kalau kata asing, pisahkan huruf asal dan tambahan seperlunya.","harakat":"Jangan memaksa semua kata mengikuti satu wazan.","arti":"Gunakan makna yang pas dengan konteks bidang kitab.","arab":"يَسْتَغْفِرُ الْعَبْدُ","terjemah":"Hamba itu memohon ampun.","rujukan":["L09-S01","L09-S02","L09-S09","L23-S05"]},{"id":"R08","term":"8. Terjemahkan kalimat, bukan antrean kata","ciri":"Lihat predikat, ruang lingkup negasi, syarat, dan rujukan dhamir.","harakat":"Tanda akhir bukan satu-satunya penentu makna.","arti":"Susunan Indonesia boleh diubah agar wajar tanpa menghilangkan unsur.","arab":"فِي الْبَيْتِ رَجُلٌ","terjemah":"Di rumah ada seorang laki-laki.","rujukan":["L12-S09","L22-S01","L22-S08"]},{"id":"R09","term":"9. Uji bacaan lain","ciri":"Jika tulisan gundul membuka dua kemungkinan, uji dengan sintaks dan konteks.","harakat":"Harakat tidak boleh diputuskan hanya dari tebakan arti.","arti":"Pilih makna paling didukung; catat yang masih terbuka.","arab":"عَلِمَ الطَّالِبُ الدَّرْسَ","terjemah":"Pelajar itu memahami pelajaran.","rujukan":["L21-S01","L21-S08","L21-S09"]},{"id":"R10","term":"10. Berani menunda keputusan","ciri":"Ketika dalil susunan belum cukup, berhenti pada analisis yang pasti.","harakat":"Tidak semua akhir harus dapat ditebak dari potongan yang terpisah.","arti":"Baca utuh paragrafnya, lalu periksa kamus atau guru.","arab":"فِي كِتَابٍ قَدِيمٍ","terjemah":"Di dalam sebuah kitab lama.","rujukan":["L01-S09","L23-S04","L24-S08"]}],"conclusion":"Urutan kerja membaca kitab: **pecah teks → kenali isim/fi‘il/huruf → cari pasangan dan ‘amil → tentukan jabatan kata → pilih tanda i‘rab yang sesuai bentuknya → cek kosakata → terjemahkan maknanya secara utuh**. Kalau satu bukti belum cukup, jangan mengarang harakat; tandai sebagai kemungkinan dan cocokkan dengan konteks."},{"id":"L25-S02","index":2,"title":"Kenali Jenis Kata dalam Sekejap","hook":"Satu baris Arab bisa berisi kata yang menamai, kata yang bergerak, dan kata yang menghubungkan. Ketiganya kelihatan sama-sama “kata”, tapi pekerjaannya beda. Jangan suruh semuanya memakai aturan harakat yang sama.","mission":"Membedakan isim, fi‘il, dan huruf dengan tanda nyata dan batas pengecualiannya.","intro":"Bila ragu, tanyakan: kata ini menyebut sesuatu, menyatakan kejadian, atau membangun hubungan?","cards":[{"id":"R01","term":"Isim (اسم)","ciri":"Nama orang, barang, tempat, sifat, atau konsep; mungkin menerima الـ, tanwin, atau jar.","harakat":"I‘rab mengikuti peran; bisa marfu‘, manshub, majrur, atau mabni.","arti":"Biasanya menjadi nama benda, subjek, objek, atau sifat.","arab":"الطَّالِبُ مُجْتَهِدٌ","terjemah":"Pelajar itu rajin.","rujukan":["L01-S03","L01-S04","L02-S01"]},{"id":"R02","term":"Fi‘il (فعل)","ciri":"Mengandung kejadian/waktu: madhi, mudhari‘, atau amar.","harakat":"Madhi/amar sering mabni; mudhari‘ dapat marfu‘, manshub, majzum.","arti":"Pilih “telah”, “sedang/akan”, atau perintah sesuai konteks.","arab":"كَتَبَ الطَّالِبُ","terjemah":"Pelajar itu telah menulis.","rujukan":["L01-S05","L04-S01","L10-S01","L10-S02"]},{"id":"R03","term":"Huruf ma‘ani","ciri":"Kata tugas seperti مِنْ، فِي، إِلَى; bukan huruf alfabet.","harakat":"Umumnya mabni; dapat memengaruhi kata setelahnya.","arti":"Baca relasinya: dari, di, menuju, dan sebagainya.","arab":"مِنَ الْبَيْتِ إِلَى الْمَسْجِدِ","terjemah":"Dari rumah menuju masjid.","rujukan":["L01-S06","L05-S01","L05-S08"]},{"id":"R04","term":"الـ (alif-lam)","ciri":"Muncul di awal banyak isim ma‘rifah; tidak berdiri sebagai kata tersendiri.","harakat":"Tidak otomatis menetapkan dhammah; akhir tetap ikut i‘rab.","arti":"Sering memberi nuansa “yang / itu / tersebut”.","arab":"الْكِتَابُ مُفِيدٌ","terjemah":"Buku itu bermanfaat.","rujukan":["L02-S01","L02-S03"]},{"id":"R05","term":"Tanwin (ـٌ / ـً / ـٍ)","ciri":"Sering muncul pada isim nakirah yang menerima tanwin.","harakat":"Bisa rafa‘, nashab, atau jar, bukan satu bunyi saja.","arti":"Umumnya “seorang/sebuah”, atau tak perlu diterjemahkan khusus.","arab":"جَاءَ رَجُلٌ","terjemah":"Seorang laki-laki datang.","rujukan":["L02-S02","L08-S02"]},{"id":"R06","term":"Sesudah huruf jar","ciri":"Kata setelah فِي، مِنْ، إِلَى, dll. biasanya isim atau frasa isim.","harakat":"Isim berikutnya majrur; kasrah pada mufrad biasa.","arti":"Hubungan tempat, asal, tujuan, alat, atau sebab.","arab":"فِي الْمَسْجِدِ","terjemah":"Di dalam masjid.","rujukan":["L05-S01","L05-S02"]},{"id":"R07","term":"قَدْ + fi‘il","ciri":"Dapat mendahului madhi atau mudhari‘, bukan isim biasa.","harakat":"Harakat fi‘il tetap menurut bentuk dan ‘amilnya.","arti":"Dengan madhi kerap “sungguh/telah”; mudhari‘ berbeda menurut konteks.","arab":"قَدْ نَجَحَ الطَّالِبُ","terjemah":"Pelajar itu benar-benar telah berhasil.","rujukan":["L10-S01","L10-S02","L14-S01"]},{"id":"R08","term":"سَـ / سَوْفَ + mudhari‘","ciri":"Penanda masa depan pada fi‘il mudhari‘.","harakat":"Keduanya sendiri tidak menashabkan fi‘il.","arti":"Terjemahkan “akan” tanpa menambah peristiwa baru.","arab":"سَيَكْتُبُ الْوَلَدُ","terjemah":"Anak itu akan menulis.","rujukan":["L10-S02","L10-S05"]},{"id":"R09","term":"تاء الفاعل pada madhi","ciri":"تُ، تَ، تِ pada ujung madhi dapat menandai pelaku.","harakat":"Madhi dengan ta’ fa‘il dibangun atas sukun.","arti":"Subjek “saya/kamu” sering sudah terkandung dalam kata kerja.","arab":"كَتَبْتُ الدَّرْسَ","terjemah":"Saya menulis pelajaran.","rujukan":["L10-S04","L10-S05","L10-S06"]},{"id":"R10","term":"Huruf bukan alfabet","ciri":"Dalam nahwu, مِنْ adalah satu kata tugas walau ditulis dua huruf.","harakat":"Biasanya tetap bentuk akhirnya (mabni).","arti":"Periksa maknanya dalam frasa, jangan menghitung hurufnya.","arab":"عَلَى الْمَكْتَبِ","terjemah":"Di atas meja.","rujukan":["L01-S03","L01-S06"]},{"id":"R11","term":"Mubni vs mu‘rab (awal)","ciri":"Akhir kata tetap atau bisa berubah menurut i‘rab; jenis ini bukan semata isu tanwin.","harakat":"مَبْنِيّ stabil; مُعْرَب berubah atau i‘rabnya diperkirakan.","arti":"Lihat fungsi sintaks, jangan tebak dari ujung kata saja.","arab":"هَذَا كِتَابٌ","terjemah":"Ini sebuah buku.","rujukan":["L08-S01","L13-S05","L13-S09"]}],"conclusion":"**Isim** menamai orang, benda, sifat, tempat, atau makna; petunjuknya antara lain **الـ, tanwin, atau bisa menjadi majrur**. **Fi‘il** mengungkap kejadian yang terkait waktu dan bentuknya; petunjuknya antara lain **قَدْ, سَـ/سَوْفَ, تاء الفاعل** sesuai jenis fi‘il. **Huruf** seperti مِنْ dan فِي menghubungkan makna. Tanda-tanda ini alat deteksi, bukan syarat bahwa semuanya harus hadir sekaligus."},{"id":"L25-S03","index":3,"title":"Jenis Isim: Kenali Bentuk, Jumlah, dan Kejelasan","hook":"Sebelum memutuskan ujung katanya, cek dulu keluarga isimnya. Satu orang, dua orang, banyak orang; sudah jelas atau masih umum; bentuk biasa atau bentuk yang “bandel”. Ujung kata bisa memberi petunjuk, tapi tetap harus dibaca dalam kalimat.","mission":"Mengenali bentuk isim yang menentukan pilihan tanda i‘rab dan terjemah.","intro":"Nama bentuk dulu, baru status i‘rabnya. Ini dua pertanyaan berbeda.","cards":[{"id":"R01","term":"Nakirah","ciri":"Umumnya belum menunjuk individu tertentu; sering tanpa الـ dan bisa bertanwin.","harakat":"Pada isim munsharif biasa tanwin mengikuti rafa‘/nashab/jar.","arti":"“Seorang”, “sebuah”, atau nomina umum sesuai konteks.","arab":"كِتَابٌ جَدِيدٌ","terjemah":"Sebuah buku baru.","rujukan":["L02-S02","L02-S10"]},{"id":"R02","term":"Ma‘rifah","ciri":"Nama diri, dhamir, isim isyarah, atau isim ber-الـ dapat ma‘rifah.","harakat":"Akhirnya tetap ditentukan posisi sintaks.","arti":"Gunakan “itu/tersebut” bila membantu; nama diri tetap nama.","arab":"هَذَا الْكِتَابُ","terjemah":"Ini buku tersebut.","rujukan":["L02-S03","L13-S06","L13-S07"]},{"id":"R03","term":"Mudzakkar","ciri":"Jenis gramatikal laki-laki atau dianggap maskulin; tidak selalu bermakna manusia.","harakat":"Tidak menentukan rafa‘/nashab/jar sendirian.","arti":"Kesesuaian dengan sifat/penunjuk sering tampak.","arab":"الْوَلَدُ الصَّغِيرُ","terjemah":"Anak laki-laki yang kecil.","rujukan":["L02-S04","L07-S05"]},{"id":"R04","term":"Mu’annats","ciri":"Sering berakhir ة, tetapi tidak selalu; ada mu’annats tanpa ة.","harakat":"Fungsi kalimat tetap menentukan akhirnya.","arti":"Penunjuk dan sifat bisa membantu memastikan jenis.","arab":"هَذِهِ مَدْرَسَةٌ","terjemah":"Ini sebuah sekolah.","rujukan":["L02-S04","L07-S05"]},{"id":"R05","term":"Mufrad","ciri":"Makna satu; bukan bentuk mutsanna atau jamak.","harakat":"Jika mu‘rab biasa: rafa‘ ـُ, nashab ـَ, jar ـِ.","arti":"Terjemahkan tunggal bila konteks mendukung.","arab":"رَأَيْتُ طَالِبًا","terjemah":"Saya melihat seorang pelajar.","rujukan":["L02-S05","L08-S02","L08-S03"]},{"id":"R06","term":"Mutsanna","ciri":"Bentuk dua; tampak lewat ـانِ atau ـيْنِ pada bentuk lengkap.","harakat":"Rafa‘ **ـانِ**; nashab dan jar **ـيْنِ**.","arti":"Tambahkan “dua” jika penting dalam terjemahan.","arab":"جَاءَ الْمُعَلِّمَانِ","terjemah":"Dua guru itu datang.","rujukan":["L02-S06","L08-S07"]},{"id":"R07","term":"Jamak mudzakkar salim","ciri":"Kebanyakan mengacu jamak laki-laki berakal; tanda ـونَ/ـينَ.","harakat":"Rafa‘ **ـونَ**; nashab/jar **ـينَ**.","arti":"Ungkap “para” atau bentuk jamak yang wajar.","arab":"سَلَّمْتُ عَلَى الْمُعَلِّمِينَ","terjemah":"Saya memberi salam kepada para guru.","rujukan":["L02-S07","L08-S08"]},{"id":"R08","term":"Jamak mu’annats salim","ciri":"Biasanya bentuk dengan ـات, namun tidak semua ber-ات otomatis kategori ini.","harakat":"Rafa‘ **ـاتُ**; nashab/jar **ـاتِ**.","arti":"Terjemahkan jamak tanpa memaksakan “perempuan” bila bukan manusia.","arab":"رَأَيْتُ الطَّالِبَاتِ","terjemah":"Saya melihat para siswi.","rujukan":["L02-S08","L08-S03"]},{"id":"R09","term":"Jamak taksir","ciri":"Bentuk dalam kata berubah; tidak memiliki satu akhiran jamak tetap.","harakat":"Banyak yang mengikuti i‘rab mufrad; periksa ghairu munsharif.","arti":"Makna jamak dari perubahan pola atau kamus.","arab":"الْكُتُبُ مُفِيدَةٌ","terjemah":"Buku-buku itu bermanfaat.","rujukan":["L02-S09","L09-S03","L13-S04"]},{"id":"R10","term":"Isim jamid","ciri":"Bentuk asal yang tidak diperlakukan sebagai turunan dari bentuk lain dalam pembahasan ini.","harakat":"Jabatan kalimat menentukan i‘rab.","arti":"Biasanya langsung dicari maknanya.","arab":"حَجَرٌ كَبِيرٌ","terjemah":"Sebuah batu besar.","rujukan":["L09-S07","L09-S01"]},{"id":"R11","term":"Isim musytaq","ciri":"Bentuk turunan dari akar kata; contoh ism fa‘il, maf‘ul, tafdhil.","harakat":"I‘rab menurut fungsi sebagai isim, bukan otomatis seperti fi‘il.","arti":"Makna turunan bisa “pelaku”, “yang dikenai”, “lebih ...”.","arab":"الْكَاتِبُ مَشْهُورٌ","terjemah":"Penulis itu terkenal.","rujukan":["L09-S08","L11-S02","L11-S03"]},{"id":"R12","term":"Mu‘rab dan mabni","ciri":"Mu‘rab akhir katanya berubah/ditaksir menurut kedudukan; mabni cenderung tetap.","harakat":"Jangan paksa dhammah/kasrah pada isim isyarah atau dhamir.","arti":"Arti tetap diputuskan dari peran dan konteks.","arab":"هَذَا طَالِبٌ","terjemah":"Ini seorang pelajar.","rujukan":["L13-S05","L13-S09"]}],"conclusion":"Kenali isim dari **ma‘rifah/nakirah**, **mudzakkar/mu’annats**, dan **mufrad/mutsanna/jamak**. Ciri cepatnya: **ـة** sering mu’annats, **ـانِ/ـيْنِ** lazim mutsanna, **ـونَ/ـينَ** jamak mudzakkar salim, **ـات** jamak mu’annats salim, sedangkan **jamak taksir mengubah pola dalam kata**. Tanda akhiran harus tetap dicek terhadap i‘rab dan pengecualian."},{"id":"L25-S04","index":4,"title":"Tabel Harakat Akhir Isim: Rafa‘, Nashab, Jar","hook":"Kalau Gus ingin satu halaman yang paling sering dibuka ketika belajar kitab, kemungkinan besar ini dia. Kita pisahkan dua hal: jabatannya apa, lalu tanda akhir bentuk kata itu apa.","mission":"Menentukan tanda asal dan tanda pengganti pada bentuk isim yang umum.","intro":"Jangan pernah menyimpulkan “dhammah = subjek” secara mutlak. Itu baru benar jika bentuk kata dan jabatannya cocok.","cards":[{"id":"R01","term":"Rafa‘ / مرفوع","ciri":"Status umum subjek, khabar mufrad, fa‘il, na’ib fa‘il.","harakat":"Tanda asal **dhammah** pada isim mufrad mu‘rab.","arti":"Tidak perlu selalu menerjemahkan dhammah; tentukan fungsi.","arab":"جَاءَ الطَّالِبُ","terjemah":"Pelajar itu datang.","rujukan":["L08-S02","L03-S08","L04-S04"]},{"id":"R02","term":"Nashab / منصوب","ciri":"Status umum objek langsung, hal, dan pelengkap tertentu.","harakat":"Tanda asal **fathah** pada isim mufrad mu‘rab.","arti":"Sering menandai yang dikenai pekerjaan.","arab":"قَرَأْتُ الْكِتَابَ","terjemah":"Saya membaca buku itu.","rujukan":["L08-S03","L04-S05","L15-S05"]},{"id":"R03","term":"Jar / مجرور","ciri":"Setelah huruf jar atau sebagai mudhaf ilaih.","harakat":"Tanda asal **kasrah** pada isim mufrad mu‘rab.","arti":"Sering menjadi frasa tempat, asal, atau hubungan kepemilikan.","arab":"فِي الْبَيْتِ","terjemah":"Di rumah.","rujukan":["L08-S04","L05-S02","L06-S04"]},{"id":"R04","term":"Isim mufrad biasa","ciri":"Satu isim yang menerima perubahan i‘rab biasa.","harakat":"Rafa‘ **ـُ/ـٌ**; nashab **ـَ/ـً**; jar **ـِ/ـٍ**.","arti":"Arti tetap menurut makna dan kedudukannya.","arab":"كِتَابٌ / كِتَابًا / كِتَابٍ","terjemah":"Buku; bentuk akhir berubah mengikuti fungsi.","rujukan":["L02-S05","L08-S02","L08-S03","L08-S04"]},{"id":"R05","term":"Mutsanna","ciri":"Dua, dengan akhiran ـانِ atau ـيْنِ.","harakat":"Rafa‘ alif **ـانِ**; nashab/jar ya **ـيْنِ**.","arti":"Sebut “dua” bila perlu.","arab":"رَأَيْتُ طَالِبَيْنِ","terjemah":"Saya melihat dua pelajar.","rujukan":["L02-S06","L08-S07"]},{"id":"R06","term":"Jamak mudzakkar salim","ciri":"Jamak salim dengan akhiran ـونَ/ـينَ.","harakat":"Rafa‘ wawu **ـونَ**; nashab/jar ya **ـينَ**.","arti":"Makna jamak “para”.","arab":"حَضَرَ الْمُعَلِّمُونَ","terjemah":"Para guru hadir.","rujukan":["L02-S07","L08-S08"]},{"id":"R07","term":"Jamak mu’annats salim","ciri":"Bentuk salim ber-ات dan memenuhi syarat.","harakat":"Rafa‘ **ـاتُ**; nashab/jar **ـاتِ** (kasrah mengganti fathah nashab).","arti":"Jangan menafsirkan kasrah sebagai jar otomatis.","arab":"إِنَّ الْمُسْلِمَاتِ صَابِرَاتٌ","terjemah":"Sesungguhnya para muslimah itu sabar.","rujukan":["L02-S08","L08-S08","L14-S02"]},{"id":"R08","term":"Asma’ul khamsah","ciri":"Tambahan panduan Level 25: lima isim khusus dengan syarat i‘rab huruf terpenuhi; dasar i‘rabnya ada di rujukan.","harakat":"Rafa‘ **و**, nashab **ا**, jar **ي**; ada persyaratan bentuk/idafah.","arti":"Kenali sebagai anggota keluarga (ayah, saudara, dll.).","arab":"جَاءَ أَبُوكَ","terjemah":"Ayahmu datang.","rujukan":["L08-S07","L08-S09"]},{"id":"R09","term":"Ghairu munsharif","ciri":"Isim yang memenuhi sebab diptote; bukan semua kata tanpa tanwin.","harakat":"Pada kondisi umum tanpa ال dan idhafah, jar **fathah**, bukan kasrah.","arti":"Jangan anggap setiap fathah sebagai maf‘ul.","arab":"مَرَرْتُ بِأَحْمَدَ","terjemah":"Saya melewati Ahmad.","rujukan":["L13-S04","L08-S08"]},{"id":"R10","term":"Maqshur","ciri":"Isim berakhir alif lazim seperti الفَتَى.","harakat":"Harakat i‘rab rafa‘/nashab/jar **diperkirakan**, tidak tampak pada alif.","arti":"Makna ditentukan fungsi dan konteks.","arab":"جَاءَ الْفَتَى","terjemah":"Pemuda itu datang.","rujukan":["L13-S01","L13-S09"]},{"id":"R11","term":"Manqush","ciri":"Isim berakhir ya lazim didahului kasrah, seperti القَاضِي.","harakat":"Rafa‘/jar sering muqaddar; nashab tampak pada bentuk tertentu.","arti":"Jangan menghapus/menambah ya sembarangan.","arab":"رَأَيْتُ الْقَاضِيَ","terjemah":"Saya melihat hakim itu.","rujukan":["L13-S02","L13-S09"]},{"id":"R12","term":"Isim mabni","ciri":"Dhamir, banyak isim isyarah/maushul dan bentuk lain.","harakat":"Bentuk ujung tetap; jabatan sintaks disebut **في محل رفع/نصب/جر**.","arti":"Status bisa berubah walau bunyi tetap.","arab":"هَذَا كِتَابٌ","terjemah":"Ini sebuah buku.","rujukan":["L13-S05","L13-S06","L13-S07"]},{"id":"R13","term":"Tanwin dan mudhaf","ciri":"Isim mudhaf dalam idhafah sejati biasanya tak menerima tanwin; jamak salim/mutsanna kehilangan nun idhafah.","harakat":"I‘rab mudhaf tetap menurut jabatan, mudhaf ilaih selalu majrur.","arti":"Terjemahkan hubungan “buku guru”, “rumah murid”, dll.","arab":"كِتَابُ الطَّالِبِ","terjemah":"Buku milik pelajar.","rujukan":["L06-S03","L06-S04"]},{"id":"R14","term":"Jazm bukan untuk isim","ciri":"Jazm terjadi pada fi‘il mudhari‘, bukan isim.","harakat":"Sukun jazm mudhari‘ shahih akhir; bukan tabel jar isim.","arti":"Jika setelah لَمْ, cek kata kerjanya.","arab":"لَمْ يَكْتُبْ","terjemah":"Dia belum/tidak menulis.","rujukan":["L08-S05","L14-S06"]}],"conclusion":"Rumus cepat: **mubtada’, khabar mufrad, fa‘il, na’ib fa‘il → marfu‘**; **maf‘ul bih, hal, tamyiz tertentu → manshub**; **setelah huruf jar atau sebagai mudhaf ilaih → majrur**. Tanda asal isim mufrad biasa: **dhammah / fathah / kasrah**, tetapi mutsanna dan jamak salim memakai **alif, wawu, ya, atau kasrah pengganti**, sementara bentuk mabni dan i‘rab muqaddar tidak selalu menampakkan perubahan.","quick_table":{"title":"Tanda i‘rab isim — tabel satu layar","columns":["Bentuk isim","Rafa‘","Nashab","Jar"],"rows":[["Mufrad mu‘rab biasa","ـُ / ـٌ","ـَ / ـً","ـِ / ـٍ"],["Mutsanna","ـانِ","ـيْنِ","ـيْنِ"],["Jamak mudzakkar salim","ـونَ","ـينَ","ـينَ"],["Jamak mu’annats salim","ـاتُ","ـاتِ","ـاتِ"],["Asma’ul khamsah (syarat terpenuhi)","و","ا","ي"],["Ghairu munsharif (tanpa ال dan idhafah)","ـُ","ـَ","ـَ"]],"note":"Tabel menunjukkan pola dasar dengan syarat masing-masing. Untuk maqshur/manqush dan isim mabni, lihat kartu khusus; tanda dapat tidak tampak."}},{"id":"L25-S05","index":5,"title":"Kalimat Ismiyah: Siapa, Bagaimana, dan Pengubahnya","hook":"Dua isim berdampingan bisa menjadi sebuah berita, bisa juga hanya frasa. Kuncinya bukan menghitung jumlah katanya. Kita lihat: mana yang dibicarakan, dan kabar apa yang disampaikan tentang dia?","mission":"Membaca mubtada’–khabar dan perubahan akibat إِنَّ atau كَانَ.","intro":"Bedakan pasangan yang saling memberi berita dengan kata yang sekadar menerangkan nama.","cards":[{"id":"R01","term":"Jumlah ismiyah","ciri":"Kalimat yang bersandar pada mubtada’ dan khabar, tidak harus selalu diawali isim secara tampak.","harakat":"Mubtada’ dan khabar mufrad dasarnya marfu‘.","arti":"Terjemahkan sebagai pernyataan keadaan atau identitas.","arab":"الْعِلْمُ نُورٌ","terjemah":"Ilmu itu cahaya.","rujukan":["L03-S01","L03-S04"]},{"id":"R02","term":"Mubtada’","ciri":"Isim yang menjadi pokok pembicaraan.","harakat":"Marfu‘: biasanya dhammah pada isim mufrad biasa.","arti":"“Adapun ... / ... itu” tergantung kelancaran Indonesia.","arab":"الطَّالِبُ مُجْتَهِدٌ","terjemah":"Pelajar itu rajin.","rujukan":["L03-S02","L03-S05"]},{"id":"R03","term":"Khabar mufrad","ciri":"Bagian yang menyampaikan berita berupa satu kata, bukan berupa jumlah atau شبه جملة.","harakat":"Marfu‘: umumnya dhammah atau tanwin sesuai isim.","arti":"Kata sifat sering jadi predikat, bukan otomatis na‘at.","arab":"الطَّالِبُ نَشِيطٌ","terjemah":"Pelajar itu aktif.","rujukan":["L03-S03","L03-S08"]},{"id":"R04","term":"Khabar jar–majrur","ciri":"Informasi berupa rangkaian preposisi dan isim.","harakat":"Isim setelah jar majrur; jangan memaksa keseluruhan frasa menjadi dhammah.","arti":"“Ada di ...”, “berada di ...”.","arab":"الْكِتَابُ عَلَى الْمَكْتَبِ","terjemah":"Buku itu ada di atas meja.","rujukan":["L03-S06","L05-S02"]},{"id":"R05","term":"Khabar didahulukan","ciri":"Sering berupa tempat di depan, sementara mubtada’ muncul belakangan.","harakat":"Mubtada’ mu’akhkhar tetap marfu‘ dalam pola dasar.","arti":"Wajar menjadi “Di rumah ada ...”.","arab":"فِي الْبَيْتِ رَجُلٌ","terjemah":"Di rumah ada seorang laki-laki.","rujukan":["L03-S07","L03-S09"]},{"id":"R06","term":"Na‘at bukan khabar","ciri":"Dua isim yang cocok definisi/jenis/jumlah/i‘rab lebih mungkin sifat dalam frasa.","harakat":"Na‘at mengikuti man‘ut; tidak berdiri sebagai informasi terpisah pada frasa.","arti":"الطَّالِبُ الْمُجْتَهِدُ = “pelajar yang rajin”.","arab":"الطَّالِبُ الْمُجْتَهِدُ حَاضِرٌ","terjemah":"Pelajar yang rajin itu hadir.","rujukan":["L07-S07","L07-S04"]},{"id":"R07","term":"إِنَّ","ciri":"Huruf taukid dan nashab, masuk ke jumlah ismiyah.","harakat":"Isim إِنَّ **manshub**, khabarnya **marfu‘**.","arti":"“Sesungguhnya ...” bila relevan.","arab":"إِنَّ الطَّالِبَ مُجْتَهِدٌ","terjemah":"Sesungguhnya pelajar itu rajin.","rujukan":["L14-S02","L14-S09"]},{"id":"R08","term":"كَانَ","ciri":"Fi‘il naqish pada jumlah ismiyah.","harakat":"Isim كَانَ **marfu‘**, khabarnya **manshub**.","arti":"Dapat menunjukkan keadaan pada masa lalu.","arab":"كَانَ الطَّالِبُ مُجْتَهِدًا","terjemah":"Dahulu pelajar itu rajin.","rujukan":["L14-S03","L14-S09"]},{"id":"R09","term":"لا النافية للجنس","ciri":"Menafikan keberadaan seluruh jenis sesuai syarat susunan.","harakat":"Isim لا dapat mabni atas fathah pada bentuk mufrad tidak mudhaf; ada rincian lain.","arti":"“Tidak ada ... sama sekali” sesuai konteks.","arab":"لَا رَجُلَ فِي الْبَيْتِ","terjemah":"Tidak ada seorang laki-laki pun di rumah.","rujukan":["L14-S04"]},{"id":"R10","term":"Mubtada’ yang mabni","ciri":"Dhamir dan kata tunjuk dapat menjadi pokok kalimat.","harakat":"Status “di tempat rafa‘” meski ujungnya tidak berubah.","arti":"“Dia / ini / itu ...” sesuai referen.","arab":"هُوَ طَالِبٌ","terjemah":"Dia seorang pelajar.","rujukan":["L13-S05","L13-S06","L03-S02"]}],"conclusion":"Jumlah ismiyah dasar berisi **mubtada’** (yang dibicarakan) dan **khabar** (informasinya), keduanya marfu‘ bila berupa isim mu‘rab dalam pola dasar. Khabar bisa satu kata, frasa jar, atau zharaf; terkadang mendahului mubtada’. **إِنَّ** menashabkan isimnya dan merafa‘kan khabarnya, sedangkan **كَانَ** merafa‘kan isimnya dan menashabkan khabarnya. Cari ‘amil dan hubungan berita sebelum memberi harakat.","quick_table":{"title":"Jumlah ismiyah — siapa terkena perubahan?","columns":["Susunan","Isim pertama","Khabar"],"rows":[["Mubtada’–khabar","Rafa‘","Rafa‘"],["إِنَّ + isim + khabar","Nashab","Rafa‘"],["كَانَ + isim + khabar","Rafa‘","Nashab"]],"note":"Tabel untuk isim dan khabar mufrad yang mu‘rab; khabar berupa jumlah atau شبه جملة tidak diberi harakat akhir seperti khabar satu kata."}},{"id":"L25-S06","index":6,"title":"Kalimat Fi‘liyah: Pelaku, Objek, dan Pelengkap","hook":"Lihat kalimat كَتَبَ الطَّالِبُ الدَّرْسَ. Tiga kata saja, tetapi perubahan ujungnya menegaskan siapa yang bertindak dan apa yang dikenai tindakan. Sekarang kita bedah tanpa menebak-nebak.","mission":"Mengenali kata kerja, pelaku, objek, pasif, dan pelengkap yang paling sering muncul di kitab.","intro":"Cari peristiwa dahulu. Sesudah itu baru tanyakan “siapa melakukan apa kepada siapa?”.","cards":[{"id":"R01","term":"Jumlah fi‘liyah","ciri":"Kalimat yang memusat pada fi‘il sebagai peristiwa.","harakat":"Jangan samakan harakat fi‘il dengan fa‘il/objek.","arti":"Terjemahkan tindakan bersama pelaku dan sasaran.","arab":"كَتَبَ الْمُعَلِّمُ الدَّرْسَ","terjemah":"Guru itu menulis pelajaran.","rujukan":["L04-S01","L04-S10"]},{"id":"R02","term":"Fi‘il madhi","ciri":"Umumnya menyatakan peristiwa telah terjadi pada konteks biasa.","harakat":"Madhi mabni; bentuk sederhana كَتَبَ dibangun di atas fathah.","arti":"“Telah/sudah”, atau verba lampau yang wajar.","arab":"فَتَحَ الرَّجُلُ الْبَابَ","terjemah":"Laki-laki itu membuka pintu.","rujukan":["L04-S02","L10-S01"]},{"id":"R03","term":"Fa‘il","ciri":"Pelaku gramatikal fi‘il aktif; bisa isim tampak atau dhamir.","harakat":"Selalu marfu‘ dalam analisis dasar.","arti":"Yang melakukan pekerjaan.","arab":"قَرَأَ الطَّالِبُ الْكِتَابَ","terjemah":"Pelajar itu membaca buku.","rujukan":["L04-S03","L04-S04"]},{"id":"R04","term":"Maf‘ul bih","ciri":"Objek langsung yang dikenai tindakan muta‘addi.","harakat":"Manshub; mufrad biasa umumnya fathah.","arti":"“Membaca apa?”, “melihat siapa?” membantu.","arab":"رَأَيْتُ الْقَمَرَ","terjemah":"Saya melihat bulan.","rujukan":["L04-S05","L04-S06"]},{"id":"R05","term":"Fi‘il lazim","ciri":"Peristiwa yang tidak memerlukan objek langsung agar lengkap.","harakat":"Fa‘il tetap marfu‘; frasa jar dapat mengikutinya.","arti":"Jangan memaksa semua isim berikutnya menjadi objek.","arab":"جَلَسَ الطَّالِبُ فِي الْفَصْلِ","terjemah":"Pelajar itu duduk di kelas.","rujukan":["L04-S07"]},{"id":"R06","term":"Fi‘il muta‘addi","ciri":"Peristiwa yang dapat mengarah ke objek langsung.","harakat":"Pada pola aktif dasar: fa‘il rafa‘, maf‘ul nashab.","arti":"“Membaca buku”, “membuka pintu”.","arab":"فَتَحَ الْوَلَدُ الْبَابَ","terjemah":"Anak itu membuka pintu.","rujukan":["L04-S08","L04-S09"]},{"id":"R07","term":"Majhul","ciri":"Bentuk fi‘il pasif: pelaku asal tidak disebut sebagai fa‘il.","harakat":"Bentuk pasif mengubah pola internal fi‘il; na’ib fa‘il marfu‘.","arti":"“Ditulis”, “dibuka”, “dibacakan”.","arab":"كُتِبَ الدَّرْسُ","terjemah":"Pelajaran itu ditulis.","rujukan":["L10-S08","L21-S07"]},{"id":"R08","term":"Na’ib fa‘il","ciri":"Isim yang menempati posisi subjek gramatikal pada bentuk pasif.","harakat":"Marfu‘, seperti fa‘il pada kalimat aktif.","arti":"Benda yang mengalami tindakan jadi pokok pernyataan pasif.","arab":"فُتِحَ الْبَابُ","terjemah":"Pintu itu dibuka.","rujukan":["L10-S08","L04-S04"]},{"id":"R09","term":"Hal (حال)","ciri":"Keterangan keadaan ketika tindakan berlangsung.","harakat":"Sering manshub dan berbentuk nakirah; ada rincian lain.","arti":"“Dalam keadaan ... / sambil ...”.","arab":"جَاءَ الطَّالِبُ مُبْتَسِمًا","terjemah":"Pelajar itu datang sambil tersenyum.","rujukan":["L15-S05"]},{"id":"R10","term":"Tamyiz (تمييز)","ciri":"Memperjelas ukuran, jumlah, atau makna yang masih samar.","harakat":"Sering manshub, tetapi bentuk jar juga ada pada susunan tertentu.","arti":"“Sebanyak ...”, “dalam hal ...”, sesuai konteks.","arab":"اِشْتَرَيْتُ لِتْرًا لَبَنًا","terjemah":"Saya membeli satu liter susu.","rujukan":["L15-S06"]},{"id":"R11","term":"Zharaf (ظرف)","ciri":"Keterangan waktu atau tempat seperti صَبَاحًا dan أَمَامَ.","harakat":"Banyak zharaf mu‘rab manshub; ada yang mabni.","arti":"“Pagi hari”, “di depan”, “ketika”.","arab":"جَلَسَ أَمَامَ الْبَابِ","terjemah":"Dia duduk di depan pintu.","rujukan":["L15-S07","L12-S06"]},{"id":"R12","term":"Maf‘ul muthlaq","ciri":"Masdar seakar fi‘il untuk menegaskan, jenis, atau jumlah peristiwa.","harakat":"Umumnya manshub.","arti":"“Dengan sungguh-sungguh”, “sekali”, sesuai jenisnya.","arab":"فَرِحَ فَرَحًا شَدِيدًا","terjemah":"Dia sangat gembira.","rujukan":["L15-S08"]},{"id":"R13","term":"Maf‘ul li-ajlih","ciri":"Masdar yang menerangkan sebab tindakan dengan persyaratan tertentu.","harakat":"Dapat manshub ketika syarat terpenuhi, atau memakai huruf jar.","arti":"“Karena / demi ...”.","arab":"جِئْتُ طَلَبًا لِلْعِلْمِ","terjemah":"Saya datang untuk mencari ilmu.","rujukan":["L15-S09"]},{"id":"R14","term":"Maf‘ul ma‘ah","ciri":"Isim setelah waw kebersamaan pada susunan tertentu.","harakat":"Manshub sebagai maf‘ul ma‘ah; beda dari ‘athaf.","arti":"“Bersama ...” bukan selalu sekadar “dan”.","arab":"سِرْتُ وَالنَّهْرَ","terjemah":"Saya berjalan menyusuri tepian sungai.","rujukan":["L15-S09","L15-S02"]}],"conclusion":"Pada jumlah fi‘liyah aktif dasar, **fi‘il** menyatakan peristiwa, **fa‘il** adalah pelaku gramatikal dan **marfu‘**, sedangkan **maf‘ul bih** bila ada adalah objek langsung dan **manshub**. Fi‘il lazim tidak menuntut objek langsung; fi‘il muta‘addi dapat memilikinya. Dalam bentuk pasif **majhul**, yang menggantikan posisi fa‘il disebut **na’ib fa‘il** dan tetap marfu‘. Pelengkap seperti hal, tamyiz, zharaf, dan maf‘ul lainnya punya aturan sendiri."},{"id":"L25-S07","index":7,"title":"Kunci Frasa: Jar, Idhafah, Sifat, dan Pengikut","hook":"Sering kali satu kata sudah bisa dibaca, tetapi kalimat tetap belum terasa masuk akal. Penyebabnya bukan kurang hafal arti. Kita belum tahu kata mana yang saling berpasangan.","mission":"Mengelompokkan kata sebagai satu makna sebelum memberi harakat dan menerjemahkan.","intro":"Lihat hubungan yang rapat: di mana, milik siapa, yang bagaimana, dan siapa mengikuti siapa.","cards":[{"id":"R01","term":"Jar–majrur","ciri":"Huruf jar diikuti isim/frasa isim.","harakat":"Isim selepas jar majrur.","arti":"“Di, dari, ke, dengan, bagi” menurut huruf dan konteks.","arab":"فِي الْمَسْجِدِ","terjemah":"Di masjid.","rujukan":["L05-S01","L05-S02"]},{"id":"R02","term":"Idhafah","ciri":"Dua isim berkaitan erat tanpa kata penghubung terpisah.","harakat":"Mudhaf ilaih majrur; mudhaf umumnya tanpa tanwin.","arti":"“Buku pelajar”, “pintu rumah”, bisa milik atau bagian.","arab":"بَابُ الْبَيْتِ","terjemah":"Pintu rumah.","rujukan":["L06-S01","L06-S02","L06-S04"]},{"id":"R03","term":"Mudhaf","ciri":"Isim pertama dalam rangkaian idhafah.","harakat":"I‘rabnya mengikuti jabatan; biasanya tanpa tanwin dan tanpa الـ pada idhafah ma‘nawiyyah.","arti":"Terjemahkan bersama pasangannya.","arab":"كِتَابُ الْمُعَلِّمِ","terjemah":"Buku guru itu.","rujukan":["L06-S03","L06-S05"]},{"id":"R04","term":"Mudhaf ilaih","ciri":"Isim kedua atau unsur berikutnya yang melengkapi idhafah.","harakat":"**Selalu majrur**, dengan tanda mengikuti jenis isim.","arti":"Makna pemilik, isi, jenis, bagian, bukan selalu “milik”.","arab":"مِفْتَاحُ الْبَابِ","terjemah":"Kunci pintu.","rujukan":["L06-S04","L06-S06"]},{"id":"R05","term":"Idhafah bertingkat","ciri":"Rangkaian tiga isim atau lebih.","harakat":"Setiap mudhaf ilaih pada hubungannya majrur.","arti":"Urai dari hubungan terdekat.","arab":"بَابُ بَيْتِ الْمُعَلِّمِ","terjemah":"Pintu rumah guru itu.","rujukan":["L06-S07","L21-S06"]},{"id":"R06","term":"Na‘at","ciri":"Kata sifat yang menjelaskan man‘ut.","harakat":"Na‘at haqiqi mengikuti i‘rab, ma‘rifah, gender, jumlah man‘ut.","arti":"“Buku yang baru”, bukan “buku itu baru” bila masih frasa.","arab":"الْكِتَابُ الْجَدِيدُ","terjemah":"Buku yang baru itu.","rujukan":["L07-S01","L07-S03","L07-S04"]},{"id":"R07","term":"Man‘ut","ciri":"Isim yang dijelaskan oleh na‘at.","harakat":"I‘rabnya menurut jabatan dalam kalimat; na‘at mengikutinya.","arti":"Nama benda diikuti penjelas sifat.","arab":"جَاءَ الطَّالِبُ الْجَدِيدُ","terjemah":"Pelajar yang baru itu datang.","rujukan":["L07-S02","L07-S05","L07-S06"]},{"id":"R08","term":"Na‘at vs khabar","ciri":"Dua kata memiliki hubungan penjelas atau predikat?","harakat":"Na‘at mengikuti ma‘rifah; khabar tidak harus menyamai ma‘rifah.","arti":"“Buku baru” vs “buku itu baru”.","arab":"الْكِتَابُ جَدِيدٌ","terjemah":"Buku itu baru.","rujukan":["L07-S07","L21-S04"]},{"id":"R09","term":"Na‘at vs idhafah","ciri":"Na‘at lazimnya mengikut kesesuaian; idhafah hubungan dua isim.","harakat":"Dalam idhafah, unsur kedua majrur; dalam sifat, sifat sesuai man‘ut.","arti":"“Buku baru” beda dengan “buku guru”.","arab":"كِتَابُ الْمُعَلِّمِ جَدِيدٌ","terjemah":"Buku guru itu baru.","rujukan":["L06-S08","L07-S08"]},{"id":"R10","term":"‘Athaf (عطف)","ciri":"Penghubung antarkata/klausa seperti وَ، فَـ، ثُمَّ.","harakat":"Isim ma‘thuf lazimnya mengikuti i‘rab ma‘thuf ‘alaih.","arti":"“Dan, lalu, kemudian” sesuai huruf.","arab":"جَاءَ زَيْدٌ وَعَمْرٌو","terjemah":"Zaid dan Amr datang.","rujukan":["L15-S02","L17-S07"]},{"id":"R11","term":"Taukid (توكيد)","ciri":"Penegas seperti نَفْس dan كُلّ pada susunan tertentu.","harakat":"Taukid mengikuti i‘rab yang ditegaskan.","arti":"“Sendiri”, “seluruhnya”.","arab":"جَاءَ الْمُدِيرُ نَفْسُهُ","terjemah":"Kepala sekolah itu sendiri datang.","rujukan":["L15-S03"]},{"id":"R12","term":"Badal (بدل)","ciri":"Kata pengganti atau penjelas yang mengikuti kata sebelumnya.","harakat":"Badal lazim mengikuti i‘rab mubdal minhu.","arti":"Terjemahkan apposisi secara wajar.","arab":"جَاءَ أَخُوكَ خَالِدٌ","terjemah":"Saudaramu, Khalid, datang.","rujukan":["L15-S04"]},{"id":"R13","term":"Isim maushul dan shilah","ciri":"الَّذِي، الَّتِي, dsb. diikuti klausa penjelas.","harakat":"Isim maushul lazim mabni (kecuali bentuk tertentu); shilah punya analisis sendiri.","arti":"“Yang ...”, lalu cari rujukan dhamir.","arab":"جَاءَ الَّذِي نَجَحَ","terjemah":"Orang yang berhasil itu datang.","rujukan":["L13-S08","L17-S03"]},{"id":"R14","term":"Dhamir rujukan","ciri":"Kata ganti melekat atau terpisah.","harakat":"Sering mabni, tetapi fungsinya bisa rafa‘/nashab/jar.","arti":"Cari orang/benda yang dirujuk.","arab":"رَأَيْتُهُ","terjemah":"Saya melihatnya.","rujukan":["L13-S06","L17-S04","L21-S03"]}],"conclusion":"Kenali pasangan yang sering menentukan bacaan: **huruf jar + isim majrur**, **mudhaf + mudhaf ilaih** (anggota kedua majrur), **man‘ut + na‘at** (sifat mengikuti i‘rab, ma‘rifah, jenis, jumlah pada pola dasar), serta **‘athaf, taukid, dan badal** yang mengikuti i‘rab unsur yang diikutinya sesuai jenisnya. Terjemahkan satu kelompok dulu, lalu hubungkan dengan kalimat utama."},{"id":"L25-S08","index":8,"title":"Bentuk Fi‘il: Madhi, Mudhari‘, Amar, Wazan","hook":"Kadang kita hafal kata كَتَبَ, tapi begitu berubah jadi يَكْتُبُ atau مَكْتُوب, kita merasa itu orang lain. Padahal keluarga katanya masih satu. Kita kenali jejak akarnya dan perubahan pola.","mission":"Mendeteksi bentuk kata kerja serta isim turunan untuk menentukan arti awalnya.","intro":"Bentuk kata memberi calon makna; konteks menentukan pilihan akhirnya.","cards":[{"id":"R01","term":"Fi‘il madhi","ciri":"Bentuk kejadian lampau; bentuk aktif tsulatsi sederhana فَعَلَ sering tampak.","harakat":"Umumnya mabni atas fathah/sukun/dhammah sesuai sambungan.","arti":"“Telah ...”, atau bentuk lampau yang wajar.","arab":"كَتَبَ","terjemah":"Dia telah menulis.","rujukan":["L10-S01","L04-S02"]},{"id":"R02","term":"Fi‘il mudhari‘","ciri":"Sering diawali أ، ن، ي، ت (huruf mudhara‘ah), tetapi tidak cukup satu tanda saja.","harakat":"Marfu‘/manshub/majzum sesuai ‘amil dan bentuknya.","arti":"“Sedang/akan ...” ditentukan konteks.","arab":"يَكْتُبُ","terjemah":"Dia menulis / sedang menulis.","rujukan":["L10-S02","L14-S05"]},{"id":"R03","term":"Fi‘il amar","ciri":"Permintaan tindakan langsung kepada lawan bicara.","harakat":"Pada banyak bentuk amar mabni atas sukun/penghapusan huruf/nun sesuai pola.","arti":"“Tulislah”, “bacalah”.","arab":"اُكْتُبْ","terjemah":"Tulislah!","rujukan":["L10-S03","L14-S08"]},{"id":"R04","term":"Tashrif dan dhamir","ciri":"Akhiran/awalan fi‘il berubah menurut pelaku.","harakat":"Jangan keliru membedakan perubahan tasrif dari i‘rab.","arti":"“Saya menulis”, “mereka menulis”.","arab":"كَتَبْنَا","terjemah":"Kami telah menulis.","rujukan":["L10-S04","L10-S05","L10-S06"]},{"id":"R05","term":"Akar kata","ciri":"Huruf dasar yang menjelaskan rumpun makna.","harakat":"Bukan penentu harakat akhir kalimat.","arti":"Cari di kamus menurut akar, bukan selalu ejaan permukaan.","arab":"كَتَبَ / كِتَابٌ / مَكْتَبٌ","terjemah":"Menulis / buku / kantor atau meja (sesuai konteks).","rujukan":["L09-S01","L09-S05","L09-S09"]},{"id":"R06","term":"Wazan","ciri":"Pola perubahan huruf dan vokal yang memetakan bentuk kata.","harakat":"Pola tidak otomatis memastikan i‘rab ujung kata.","arti":"Bandingkan bentuk untuk memprediksi rumpun makna.","arab":"عَلِمَ / عَلَّمَ / تَعَلَّمَ","terjemah":"Mengetahui / mengajarkan / belajar.","rujukan":["L09-S03","L09-S04","L16-S03"]},{"id":"R07","term":"Mujarrad","ciri":"Fi‘il dasar tanpa huruf tambahan pada pola yang dibandingkan.","harakat":"Tasrif mengikuti bab dan jenis fi‘il.","arti":"Terjemahkan makna dasarnya.","arab":"فَتَحَ","terjemah":"Dia membuka.","rujukan":["L16-S01","L09-S02"]},{"id":"R08","term":"Mazid","ciri":"Fi‘il dengan huruf tambahan pada akar.","harakat":"Bentuk tambahan mengubah pola, sering juga nuansa makna.","arti":"Tidak semua tambahan punya satu terjemahan tetap.","arab":"اِسْتَغْفَرَ","terjemah":"Dia memohon ampun.","rujukan":["L16-S02","L16-S03"]},{"id":"R09","term":"Masdar","ciri":"Isim yang mengungkap peristiwa/tindakan tanpa waktu seperti fi‘il.","harakat":"I‘rab sebagai isim menurut jabatan.","arti":"“Penulisan”, “membaca”, “belajar”.","arab":"الْقِرَاءَةُ مُفِيدَةٌ","terjemah":"Membaca itu bermanfaat.","rujukan":["L11-S01"]},{"id":"R10","term":"Isim fa‘il","ciri":"Isim pelaku, sering فَاعِل untuk fi‘il tsulatsi mujarrad.","harakat":"Ujungnya ikut i‘rab isim.","arti":"“Penulis”, “pembaca”, “yang ...”.","arab":"كَاتِبٌ","terjemah":"Seorang penulis.","rujukan":["L11-S02"]},{"id":"R11","term":"Isim maf‘ul","ciri":"Isim yang dikenai tindakan, sering مَفْعُول pada tsulatsi mujarrad.","harakat":"Ujungnya ikut i‘rab isim.","arti":"“Yang ditulis”, “yang dibuka”.","arab":"مَكْتُوبٌ","terjemah":"Yang tertulis.","rujukan":["L11-S03"]},{"id":"R12","term":"Shighat mubalaghah","ciri":"Isim yang menekankan intensitas sifat/aksi dengan beberapa pola.","harakat":"I‘rab sebagai isim.","arti":"“Sangat ...”, “banyak ...”, menurut konteks.","arab":"غَفَّارٌ","terjemah":"Maha/Banyak mengampuni (menurut pemakaian).","rujukan":["L11-S04"]},{"id":"R13","term":"Isim tafdhil","ciri":"Pola perbandingan, sering أَفْعَل, dengan pengecualian bentuk.","harakat":"I‘rab sebagai isim sifat, sesuai susunan.","arti":"“Lebih / paling ...”.","arab":"أَكْبَرُ","terjemah":"Lebih besar / paling besar.","rujukan":["L11-S05"]},{"id":"R14","term":"Isim zaman dan makan","ciri":"Bentuk turunan penunjuk waktu atau tempat peristiwa.","harakat":"I‘rab sebagai isim.","arti":"“Tempat ...”, “waktu ...” bila makna mendukung.","arab":"مَجْلِسٌ","terjemah":"Tempat duduk / majelis.","rujukan":["L11-S06","L11-S07"]},{"id":"R15","term":"Isim alat","ciri":"Isim yang menunjukkan alat, dengan beberapa pola umum.","harakat":"I‘rab sebagai isim.","arti":"“Alat untuk ...”.","arab":"مِفْتَاحٌ","terjemah":"Kunci.","rujukan":["L11-S08"]}],"conclusion":"**Madhi** lazimnya menyatakan kejadian lampau dan mabni; **mudhari‘** dipakai untuk kejadian yang sedang/akan berlangsung menurut konteks dan berubah i‘rab; **amar** menyatakan perintah. Cari **akar kata**, bedakan **huruf asli/tambahan**, lalu cek **wazan** sebelum membuka kamus. Turunan seperti **masdar, isim fa‘il, isim maf‘ul, isim alat, zaman, dan makan** adalah isim; jangan diberi aturan akhir fi‘il hanya karena berasal dari akar kerja."},{"id":"L25-S09","index":9,"title":"‘Amil pada Mudhari‘ dan Fi‘il Tidak Biasa","hook":"Ada kata يَكْتُبُ, lalu datang لَنْ atau لَمْ. Tulisannya mirip, tetapi ujungnya berubah. Jangan memaksa aturan dhammah–fathah–sukun tanpa memeriksa bentuk katanya.","mission":"Menentukan rafa‘, nashab, jazm mudhari‘ dan mengenali pola mu‘tal.","intro":"Pertama cari alat yang bekerja, kemudian cek apakah ujung fi‘ilnya shahih, mu‘tal, atau bagian dari af‘al khamsah.","cards":[{"id":"R01","term":"Mudhari‘ marfu‘","ciri":"Tidak didahului nashib atau jazim yang mengubahnya.","harakat":"Shahih akhir biasanya dhammah.","arti":"“Menulis”, “sedang menulis”, “akan menulis”.","arab":"يَكْتُبُ","terjemah":"Dia menulis.","rujukan":["L08-S02","L10-S02","L14-S05"]},{"id":"R02","term":"Mudhari‘ manshub","ciri":"Didahului nashib seperti لَنْ، أَنْ، كَيْ pada konteks yang tepat.","harakat":"Shahih akhir biasanya fathah.","arti":"“Tidak akan ...”, “untuk/agar ...”.","arab":"لَنْ يَكْتُبَ","terjemah":"Dia tidak akan menulis.","rujukan":["L14-S05","L08-S03"]},{"id":"R03","term":"Mudhari‘ majzum","ciri":"Didahului jazim seperti لَمْ، لَا الناهية.","harakat":"Shahih akhir biasanya sukun.","arti":"“Belum/tidak ...”, atau larangan.","arab":"لَمْ يَكْتُبْ","terjemah":"Dia tidak/belum menulis.","rujukan":["L14-S06","L08-S05"]},{"id":"R04","term":"لَا الناهية","ciri":"Larangan “jangan ...” di depan mudhari‘.","harakat":"Menjazmkan mudhari‘.","arti":"Terjemah langsung “jangan ...”.","arab":"لَا تَكْتُبْ","terjemah":"Jangan menulis.","rujukan":["L14-S06","L14-S08"]},{"id":"R05","term":"لَا النافية","ciri":"Penolakan/negasi biasa, bukan larangan.","harakat":"Tidak otomatis menjazmkan mudhari‘.","arti":"“Tidak ...” tanpa nuansa larangan.","arab":"لَا يَكْتُبُ","terjemah":"Dia tidak menulis.","rujukan":["L14-S06","L20-S02"]},{"id":"R06","term":"Af‘al khamsah","ciri":"Pola mudhari‘: يفعلان، تفعلان، يفعلون، تفعلون، تفعلين.","harakat":"Rafa‘ tetap nun; nashab/jazm **hapus nun**.","arti":"Perhatikan pelaku ganda/jamak/lawan bicara.","arab":"لَنْ يَكْتُبُوا","terjemah":"Mereka tidak akan menulis.","rujukan":["L10-S04","L14-S05","L14-S06"]},{"id":"R07","term":"Fi‘il shahih","ciri":"Akar tak memiliki huruf ‘illat و، ا، ي pada posisinya dalam klasifikasi.","harakat":"Aturan perubahan akhir lebih langsung, tetapi hamzah/tasydid punya rincian.","arti":"Makna dari akar dan pola.","arab":"يَفْتَحُ","terjemah":"Dia membuka.","rujukan":["L16-S04"]},{"id":"R08","term":"Fi‘il mu‘tal","ciri":"Akar memuat huruf ‘illat pada posisi tertentu.","harakat":"Tanda i‘rab bisa muqaddar atau huruf ‘illat dibuang saat jazm.","arti":"Jangan paksa sukun terlihat pada setiap mu‘tal.","arab":"يَدْعُو / لَمْ يَدْعُ","terjemah":"Dia berdoa / dia tidak berdoa.","rujukan":["L16-S05","L16-S09"]},{"id":"R09","term":"Mitsal","ciri":"Huruf ‘illat pada awal akar.","harakat":"Perubahan bisa muncul pada beberapa tasrif.","arti":"Periksa bentuk tanpa menyimpulkan akar dari bunyi saja.","arab":"وَعَدَ / يَعِدُ","terjemah":"Dia berjanji / dia berjanji (mudhari‘).","rujukan":["L16-S06"]},{"id":"R10","term":"Ajwaf","ciri":"Huruf ‘illat di tengah akar.","harakat":"Sering berubah/menyusut pada sebagian tasrif.","arti":"Perhatikan pasangan madhi–mudhari‘.","arab":"قَالَ / يَقُولُ","terjemah":"Dia berkata / dia berkata (mudhari‘).","rujukan":["L16-S07"]},{"id":"R11","term":"Naqish","ciri":"Huruf ‘illat di akhir akar.","harakat":"Akhiran dapat dihapus pada jazm dan berubah pada amar.","arti":"Akhir yang hilang belum tentu salah tulis.","arab":"رَمَى / لَمْ يَرْمِ","terjemah":"Dia melempar / dia tidak melempar.","rujukan":["L16-S08","L16-S09"]},{"id":"R12","term":"Fi‘il ma‘lum dan majhul","ciri":"Aktif menyebut pelaku; pasif mengubah pola dan menaikkan unsur pengganti.","harakat":"Na’ib fa‘il marfu‘, jangan dijadikan maf‘ul manshub.","arti":"“Menulis” vs “ditulis”.","arab":"كَتَبَ الْوَلَدُ / كُتِبَ الدَّرْسُ","terjemah":"Anak menulis / pelajaran ditulis.","rujukan":["L10-S07","L10-S08","L21-S07"]},{"id":"R13","term":"Syarat dan jawab","ciri":"أَدَاةُ شَرْطٍ menghubungkan kondisi dengan akibat.","harakat":"Jazim seperti إِنْ dapat menjazmkan dua mudhari‘ sesuai susunan.","arti":"“Jika ... maka ...”.","arab":"إِنْ تَجْتَهِدْ تَنْجَحْ","terjemah":"Jika kamu bersungguh-sungguh, kamu berhasil.","rujukan":["L14-S07","L17-S05"]}],"conclusion":"**Mudhari‘ shahih akhir** pada keadaan biasa **marfu‘ dengan dhammah**; setelah nashib seperti **لَنْ/أَنْ** menjadi **manshub dengan fathah**, setelah jazim seperti **لَمْ/لَا الناهية** menjadi **majzum dengan sukun**. Tetapi **af‘al khamsah** memakai **tetap/hapus nun**, sedangkan fi‘il **mu‘tal** dapat menampakkan tanda perkiraan atau penghapusan huruf ‘illat. Bedakan ‘amil dengan pola bentuknya sebelum memberi harakat.","quick_table":{"title":"Fi‘il mudhari‘ — tiga akhir yang harus dibedakan","columns":["Bentuk","Rafa‘","Nashab","Jazm"],"rows":[["Shahih akhir","يَكْتُبُ","لَنْ يَكْتُبَ","لَمْ يَكْتُبْ"],["Af‘al khamsah (contoh jamak)","يَكْتُبُونَ","لَنْ يَكْتُبُوا","لَمْ يَكْتُبُوا"],["Mu‘tal akhir (contoh دعَا)","يَدْعُو","لَنْ يَدْعُوَ","لَمْ يَدْعُ"]],"note":"Rafa‘, nashab, dan jazm ditentukan ‘amil dan kelompok fi‘il. Perubahan mu‘tal bisa beragam menurut bentuk akarnya."}},{"id":"L25-S10","index":10,"title":"Isim Khusus yang Sering Mengecoh","hook":"Ada kata yang di halaman terlihat aneh: akhir alif tidak menunjukkan dhammah, atau sebuah nama justru majrur dengan fathah. Ini bukan nahwu yang berubah pikiran. Kita sedang berjumpa pengecualian.","mission":"Mengenali kata yang tidak dapat diputuskan hanya dari harakat akhirnya.","intro":"Jika ujungnya tampak “menyimpang”, identifikasi jenis isim khususnya sebelum memperbaiki bacaan.","cards":[{"id":"R01","term":"Maqshur","ciri":"Ujung alif lazim seperti فَتَى.","harakat":"I‘rab rafa‘/nashab/jar muqaddar.","arti":"Arti nomina biasa; lihat fungsinya.","arab":"جَاءَ الْفَتَى","terjemah":"Pemuda itu datang.","rujukan":["L13-S01"]},{"id":"R02","term":"Manqush","ciri":"Ujung ya lazim didahului kasrah seperti الْقَاضِي.","harakat":"Rafa‘/jar muqaddar pada kondisi biasa; nashab dapat jelas.","arti":"Pakai arti “hakim”, bukan terjebak tulisan akhirnya.","arab":"جَاءَ الْقَاضِي","terjemah":"Hakim itu datang.","rujukan":["L13-S02"]},{"id":"R03","term":"Mamdud","ciri":"Ujung hamzah setelah alif tambahan seperti صَحْرَاء.","harakat":"Perilaku i‘rab bergantung asal/jenis hamzah dan kategori isim.","arti":"Terjemahkan nomina sesuai kamus.","arab":"هَذِهِ صَحْرَاءُ","terjemah":"Ini padang pasir.","rujukan":["L13-S03"]},{"id":"R04","term":"Ghairu munsharif","ciri":"Tidak menerima tanwin dalam kondisi tertentu dan punya larangan sharf.","harakat":"Umumnya majrur fathah ketika tanpa الـ/idafah; pengecualian diperiksa.","arti":"Jangan sebut fathah sebagai objek tanpa bukti.","arab":"مَرَرْتُ بِأَحْمَدَ","terjemah":"Saya melewati Ahmad.","rujukan":["L13-S04"]},{"id":"R05","term":"Isim mabni","ciri":"Bentuk akhir tidak berubah sesuai fungsi sintaks.","harakat":"I‘rab pada posisi: فِي مَحَلِّ رَفْعٍ/نَصْبٍ/جَرٍّ.","arti":"Makna ikut jabatan dan acuan.","arab":"جَاءَ هَذَا","terjemah":"Yang ini datang.","rujukan":["L13-S05","L13-S09"]},{"id":"R06","term":"Dhamir","ciri":"Kata ganti: هو، هي، هم; atau -ه، -هم dan bentuk lain.","harakat":"Mabni; sambungan bisa menjadi objek, fa‘il, atau mudhaf ilaih.","arti":"Cari “dia/mereka/-nya” yang tepat referennya.","arab":"قَرَأْتُهُ","terjemah":"Saya membacanya.","rujukan":["L13-S06","L17-S04"]},{"id":"R07","term":"Isim isyarah","ciri":"Penunjuk ini/itu seperti هَذَا، هَذِهِ، ذَلِكَ.","harakat":"Mayoritas mabni; terdapat bentuk mutsanna dengan rincian i‘rab.","arti":"Jangan menambah “ini” dua kali.","arab":"هَذِهِ مَدْرَسَةٌ","terjemah":"Ini sebuah sekolah.","rujukan":["L13-S07","L13-S05"]},{"id":"R08","term":"Isim maushul","ciri":"Penghubung “yang” مثل الَّذِي، الَّتِي.","harakat":"Banyak mabni, dengan pengecualian bentuk mutsanna.","arti":"Hubungkan frasa penerang ke isim yang tepat.","arab":"الطَّالِبُ الَّذِي نَجَحَ","terjemah":"Pelajar yang berhasil.","rujukan":["L13-S08","L17-S03"]},{"id":"R09","term":"Isim syarat","ciri":"مَنْ، مَا dan sejenisnya dapat membuka kalimat bersyarat.","harakat":"Banyak bentuk mabni, memengaruhi analisis fi‘il berikutnya.","arti":"“Barang siapa / apa pun ...” sesuai konteks.","arab":"مَنْ يَجْتَهِدْ يَنْجَحْ","terjemah":"Siapa yang bersungguh-sungguh akan berhasil.","rujukan":["L14-S07","L17-S05"]},{"id":"R10","term":"Dhamir rujukan jauh","ciri":"Satu -ه mungkin merujuk subjek beberapa klausa sebelumnya.","harakat":"Ujung tetap tidak cukup untuk menentukan referen.","arti":"Pilih acuan berdasarkan jenis, jumlah, kedekatan, dan wacana.","arab":"رَآهُ الْمُعَلِّمُ","terjemah":"Guru itu melihatnya.","rujukan":["L17-S04","L20-S07","L21-S03"]},{"id":"R11","term":"Ambiguitas ma‘lum–majhul","ciri":"Tulisan gundul kadang membuka bacaan aktif atau pasif.","harakat":"Konteks dan posisi na’ib fa‘il menentukan pilihan.","arti":"“Menulis” berbeda dari “ditulis”.","arab":"كُتِبَ الْخَبَرُ","terjemah":"Berita itu ditulis.","rujukan":["L21-S07","L21-S08"]}],"conclusion":"Jangan menerapkan rumus isim mufrad biasa pada semua kata. **Maqshur** memiliki i‘rab yang diperkirakan pada alif akhir; **manqush** punya kondisi khusus pada ya akhir; **ghairu munsharif** dapat majrur dengan fathah; **isim mabni, dhamir, isim isyarah, dan banyak isim maushul** tidak berubah ujungnya seperti isim mu‘rab. **Nama khusus, pola derivasi, serta makna rujukan** tetap ditentukan bersama konteks kalimat."},{"id":"L25-S11","index":11,"title":"Terjemahan Cepat: Partikel, Konteks, dan Baca Kitab","hook":"Kitab nggak bisa selalu diterjemahkan dari kiri ke kanan atau dari satu kata ke kata berikutnya. Ada مِنْ yang berarti “dari”, ada yang lebih dekat ke “sebagian”. Ada وَ yang berarti “dan”, tapi juga bisa mengikat dua peristiwa. Kita cari maksud kalimatnya tanpa mengkhianati susunan Arab.","mission":"Menggabungkan deteksi bentuk, perubahan harakat, hubungan kalimat, dan terjemahan yang alami.","intro":"Bukan hafalan padanan kata, melainkan penentuan makna berdasarkan susunan dan konteks bidang kitab.","cards":[{"id":"R01","term":"مِنْ","ciri":"Huruf jar; maknanya bergantung susunan.","harakat":"Kata setelahnya majrur.","arti":"Dari, sebagian, atau hubungan lain sesuai konteks.","arab":"خَرَجَ مِنَ الْبَيْتِ","terjemah":"Dia keluar dari rumah.","rujukan":["L05-S03","L22-S02"]},{"id":"R02","term":"إِلَى","ciri":"Huruf jar yang sering menandai tujuan.","harakat":"Sesudahnya majrur.","arti":"Ke, menuju, sampai pada.","arab":"ذَهَبَ إِلَى الْمَسْجِدِ","terjemah":"Dia pergi ke masjid.","rujukan":["L05-S04","L22-S02"]},{"id":"R03","term":"فِي / عَلَى","ciri":"Huruf jar, bisa bermakna literal atau figuratif.","harakat":"Sesudahnya majrur.","arti":"Di/dalam; di atas/atas tanggungan, dll.","arab":"فِي الْكِتَابِ حِكْمَةٌ","terjemah":"Dalam kitab itu ada hikmah.","rujukan":["L05-S05","L05-S06","L05-S08"]},{"id":"R04","term":"بِـ / لِـ","ciri":"Huruf jar melekat pada kata berikutnya.","harakat":"Isim sesudahnya majrur.","arti":"Dengan/karena/melalui; untuk/milik/kepada.","arab":"كَتَبَ بِالْقَلَمِ","terjemah":"Dia menulis dengan pena.","rujukan":["L05-S07","L22-S02"]},{"id":"R05","term":"وَ / فَـ / ثُمَّ","ciri":"Penghubung kata atau klausa dengan nuansa berbeda.","harakat":"Tidak sendiri mengubah semua ujung kata.","arti":"Dan / lalu / kemudian, menurut urutan dan akibat.","arab":"دَخَلَ ثُمَّ جَلَسَ","terjemah":"Dia masuk, lalu duduk.","rujukan":["L15-S02","L17-S07"]},{"id":"R06","term":"إِنَّ vs إِنْ","ciri":"Yang pertama penegas-nashib; yang kedua dapat menjadi syarat atau bentuk lain.","harakat":"إِنَّ menashabkan isimnya; إِنْ syarat bisa menjazmkan mudhari‘.","arti":"Sesungguhnya vs jika, lihat susunan.","arab":"إِنَّ الْحَقَّ وَاضِحٌ","terjemah":"Sesungguhnya kebenaran itu jelas.","rujukan":["L14-S02","L14-S07","L21-S01"]},{"id":"R07","term":"مَا","ciri":"Bisa negasi, tanya, maushul, syarat, dan fungsi lain.","harakat":"Pengaruh harakat berbeda menurut jenis مَا.","arti":"“Apa”, “yang”, atau “tidak”, bukan satu arti tetap.","arab":"مَا هَذَا؟","terjemah":"Apa ini?","rujukan":["L13-S08","L14-S07","L21-S02"]},{"id":"R08","term":"لَا","ciri":"Bisa negasi biasa, larangan, atau nafi lil jins.","harakat":"Tanda sesudahnya berbeda menurut fungsi.","arti":"“Tidak”, “jangan”, atau “tidak ada ...”.","arab":"لَا تَكْذِبْ","terjemah":"Jangan berbohong.","rujukan":["L14-S04","L14-S06","L20-S02"]},{"id":"R09","term":"Waqaf dan washal","ciri":"Jeda/batas baca dapat mengubah pasangan makna.","harakat":"Jangan menyimpulkan i‘rab hanya dari jeda suara.","arti":"Pertimbangkan apakah frasa menerangkan sebelum atau sesudah jeda.","arab":"قَالَ الْمُعَلِّمُ إِنَّ الْعِلْمَ نُورٌ","terjemah":"Guru itu berkata bahwa ilmu adalah cahaya.","rujukan":["L22-S03","L22-S04"]},{"id":"R10","term":"Taqdim–ta’khir","ciri":"Bagian penting bisa didahulukan demi makna/penekanan.","harakat":"I‘rab tetap menurut jabatan, bukan urutan mekanis.","arti":"Susun ulang Indonesia agar enak dibaca.","arab":"إِيَّاكَ نَعْبُدُ","terjemah":"Hanya kepada-Mu kami menyembah.","rujukan":["L22-S06","L21-S08"]},{"id":"R11","term":"Taqdir (tersirat)","ciri":"Ada unsur yang dipahami dari tata bahasa dan konteks.","harakat":"Jangan menambahkan unsur tanpa alasan sintaks.","arti":"Ungkap dalam terjemahan bila perlu untuk kelancaran.","arab":"فِي الْبَيْتِ مَنْ؟","terjemah":"Siapa yang ada di rumah?","rujukan":["L22-S05","L17-S02"]},{"id":"R12","term":"Bahasa fikih","ciri":"Cari syarat, rukun, hukum, pembagian, dan pengecualian.","harakat":"Bentuk syarat dan pengubah status dibaca sebagai susunan.","arti":"Jaga ketepatan istilah hukum.","arab":"إِذَا دَخَلَ الْوَقْتُ وَجَبَتِ الصَّلَاةُ","terjemah":"Apabila waktunya tiba, salat menjadi wajib.","rujukan":["L18-S03","L18-S05","L18-S08"]},{"id":"R13","term":"Bahasa hadis","ciri":"Pisahkan periwayat, sabda, dan penjelasan pensyarah.","harakat":"Fi‘il riwayat dan dhamir memandu subjek pembicaraan.","arti":"Jangan lebur matan dan komentar menjadi satu suara.","arab":"قَالَ رَسُولُ اللَّهِ","terjemah":"Rasulullah bersabda.","rujukan":["L19-S02","L19-S03","L19-S06"]},{"id":"R14","term":"Bahasa hikmah/tasawuf","ciri":"Ungkapan bisa bermakna kiasan atau abstrak.","harakat":"Pertahankan hubungan sebab-akibat dan acuan dhamir.","arti":"Arti harfiah boleh dijelaskan, lalu maksudnya diperjelas.","arab":"الصَّبْرُ مِفْتَاحُ الْفَرَجِ","terjemah":"Kesabaran adalah kunci kelapangan.","rujukan":["L20-S03","L20-S04","L20-S06","L20-S08"]},{"id":"R15","term":"Baca paragraf baru","ciri":"Tandai klausa, cari ‘amil, peran, kosa kata, lalu rangkai hasil.","harakat":"Beri harakat hanya pada bagian yang cukup terbukti.","arti":"Terjemahkan, lalu jelaskan alasan setiap keputusan.","arab":"قَرَأَ الطَّالِبُ الْكِتَابَ ثُمَّ كَتَبَ خُلَاصَتَهُ","terjemah":"Pelajar itu membaca buku, kemudian menulis ringkasannya.","rujukan":["L12-S10","L23-S10","L24-S01","L24-S10"]}],"conclusion":"Saat menerjemahkan, cari **inti kalimat** lebih dulu, satukan kelompok jar–majrur, idhafah, na‘at, dan klausa maushul; kemudian pilih arti huruf yang sesuai konteks. **Waqaf, wash al, taqdim–ta’khir, rujukan dhamir, dan kosakata bidang fikih/hadis/tasawuf** bisa mengubah penafsiran. Pastikan setiap arti mempunyai alasan dari teks, lalu baca ulang hasil Indonesia agar tetap alami. Untuk pembuktian akhir, kembali ke **L12, L21–L24**."}],"worked_example":{"gundul":"كتب الطالب الدرس في الفصل","berharakat":"كَتَبَ الطَّالِبُ الدَّرْسَ فِي الْفَصْلِ","terjemah":"Pelajar itu menulis pelajaran di kelas.","langkah":["كَتَبَ = fi‘il madhi aktif, mabni atas fathah; menulis/menulis pada waktu lampau.","الطَّالِبُ = fa‘il, isim mufrad, marfu‘ dengan dhammah; pelajar itu.","الدَّرْسَ = maf‘ul bih, isim mufrad, manshub dengan fathah; pelajaran.","فِي = huruf jar, membentuk keterangan tempat.","الْفَصْلِ = isim majrur karena فِي, kasrah; kelas.","Hasil akhir Indonesia disusun menjadi satu kalimat wajar tanpa menyebut harakatnya."],"rujukan":["L01-S03","L04-S03","L04-S05","L05-S02","L08-S09","L12-S09"]},"index_240":[{"id":"L01-S01","level":1,"sublevel":1,"title":"Kitab Gundul Itu Sebenarnya Apa?","conclusion":"Kitab gundul adalah teks Arab yang sebagian tanda bunyinya tidak dituliskan, bukan tulisan yang kehilangan makna. Huruf dan batas katanya masih bisa kita lihat, seperti pada العلم نور. Jadi, langkah pertama bukan memasang harakat sesuka hati, melainkan mengenali apa yang sudah jelas dan mencatat bagian yang masih perlu diperiksa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S02","level":1,"sublevel":2,"title":"Jangan Baca Dulu: Cari Jejaknya","conclusion":"Sebelum menyuarakan sebuah kalimat, lihat dulu petunjuknya: spasi memisahkan kata, ال bisa membantu mengenali isim, dan kata pendek seperti في dapat menunjukkan hubungan. Pada في المسجد كتاب, kita melihat tiga kata yang saling berkaitan. Jejak kecil itu belum menjawab semuanya, tetapi cukup untuk mencegah kita membaca dengan asal tebak.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S03","level":1,"sublevel":3,"title":"Tiga Pemain Utama: Isim, Fi‘il, Huruf","conclusion":"Kata Arab dalam nahwu terbagi menjadi tiga: isim untuk menyebut orang, benda, sifat, atau makna; fi‘il untuk menyatakan peristiwa yang berkaitan dengan waktu; dan huruf untuk menghubungkan makna dengan kata lain. Dalam كتب الطالب في البيت, كتب membawa tindakan, الطالب menyebut pelakunya, sedangkan في mengantar keterangan tempat. Mengenali peran setiap kata membuat susunan lebih masuk akal. Yang perlu dibedakan sejak awal: **isim** menamai sesuatu dan dapat menerima tanda tertentu seperti ال atau jar; **fi‘il** membawa kejadian dan waktu; **huruf** seperti فِي menghubungkan makna, bukan huruf alfabet.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S04","level":1,"sublevel":4,"title":"Cara Mencurigai Sebuah Kata sebagai Isim","conclusion":"Isim adalah kata yang menamai sesuatu atau menyebut suatu makna tanpa penanda waktu sebagaimana fi‘il. Kita menjumpainya saat menyebut orang, tempat, benda, atau sifat; misalnya زيد dan المسجد. Cara awal mengenalinya ialah melihat nama diri, ال, atau maknanya dalam kalimat. Tidak semua isim memakai ال, jadi satu tanda saja jangan dijadikan satu-satunya hakim. Penanda yang bisa kita cari pada isim antara lain **الـ**, **tanwin** pada bentuk yang menerimanya, atau kedudukannya sesudah huruf jar; nama diri pun tetap isim walau tak memakai الـ.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S05","level":1,"sublevel":5,"title":"Cara Mencurigai Sebuah Kata sebagai Fi‘il","conclusion":"Fi‘il adalah kata yang menyampaikan tindakan atau peristiwa dengan hubungan waktu. Dalam ذهب الرجل إلى السوق, ذهب membawa peristiwa pergi, sementara الرجل menyebut siapa yang melakukannya. Untuk mengenalinya, cari bagian yang menjawab pertanyaan “apa yang terjadi?”, lalu cocokkan bentuk dan konteks; jangan menganggap setiap kata yang artinya aktif otomatis fi‘il. Bentuk fi‘il kelak dibedakan menjadi **madhi** (kejadian lampau), **mudhari‘** (sedang/akan dalam konteks), dan **amar** (perintah); harakat akhirnya tidak boleh disamakan begitu saja dengan harakat isim.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S06","level":1,"sublevel":6,"title":"Huruf Kecil yang Mengubah Hubungan Kata","conclusion":"Huruf dalam nahwu bukan sekadar huruf alfabet, melainkan kata tugas seperti في, من, إلى, dan على. Kata-kata kecil ini memberi tahu di mana, dari mana, ke mana, atau di atas apa sesuatu berlangsung. Pada خرج الرجل من البيت, من menghubungkan peristiwa keluar dengan asal tempat. Salah membaca satu huruf bisa membuat arah cerita ikut berubah. Tanda paling terasa muncul sesudah **huruf jar**: isim yang mengikutinya berkedudukan **majrur**; pada isim mufrad biasa, tanda asalnya kasrah, tetapi ada bentuk khusus yang memakai tanda lain.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S07","level":1,"sublevel":7,"title":"Dari Kata Menjadi Kelompok Kata","conclusion":"Beberapa kata Arab bekerja sebagai satu kelompok makna. Dalam باب المسجد مفتوح, باب المسجد dibaca sebagai hubungan “pintu masjid”, bukan dua benda yang kebetulan bersebelahan. Supaya terjemahan tidak patah-patah, kita perlu mencari pasangan kata yang saling bergantung dulu, baru melihat fungsi kelompok itu dalam kalimat utuh.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S08","level":1,"sublevel":8,"title":"Jangan Langsung Terjemahkan: Cari Hubungannya","conclusion":"Menerjemahkan bukan memindahkan kata satu per satu lalu berharap kalimatnya beres. Pada قرأ الطالب الكتاب, kita cari dulu peristiwanya, siapa yang membaca, dan apa yang dibaca. Setelah hubungan itu ketemu, barulah susunan Indonesia dibuat alami. Cara ini penting karena urutan kata Arab dan Indonesia tidak selalu sama.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S09","level":1,"sublevel":9,"title":"Tebak → Buka Harakat → Periksa","conclusion":"Saat menjumpai teks gundul seperti العلم نافع, kita boleh membuat dugaan bacaan, tetapi dugaan itu harus bisa diuji. Periksa huruf dan susunannya, bandingkan dengan bentuk berharakat, lalu koreksi bagian yang keliru. Tujuan latihan bukan selalu benar pada tebakan pertama, melainkan punya alasan mengapa satu bacaan lebih tepat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L01-S10","level":1,"sublevel":10,"title":"Buka Kitab #01 — Membongkar Kalimat Gundul Pertama","conclusion":"Bekal awal membaca kitab sudah terkumpul: pisahkan kata, kenali isim–fi‘il–huruf, cari pelaku dan hubungan makna, lalu verifikasi harakat. Dalam ذهب الطالب إلى المسجد, peristiwa pergi, pelaku, dan tujuan saling menyambung. Kalau ada bunyi akhir yang belum pasti, kita tandai sebagai pertanyaan—bukan mengisinya asal supaya terlihat lengkap.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S01","level":2,"sublevel":1,"title":"Ciri-Ciri Isim yang Kelihatan","conclusion":"Isim punya beberapa jejak yang bisa kita periksa: ال, tanwin pada contoh berharakat, atau muncul setelah huruf jar. Misalnya dalam في الفصل كتاب جديد, kita bisa mengenali unsur yang berfungsi sebagai nama atau benda. Tanda-tanda itu dipakai bersama konteks; ketiadaan satu tanda bukan berarti sebuah kata pasti bukan isim. Untuk memastikan sebuah kata isim, periksa **الـ**, kemungkinan **tanwin**, serta apakah ia bisa menempati posisi sesudah huruf jar; ciri itu petunjuk, bukan syarat harus hadir sekaligus.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S02","level":2,"sublevel":2,"title":"Nakirah: Sesuatu yang Masih Umum","conclusion":"Nakirah ialah isim yang menyebut sesuatu secara umum atau belum ditentukan secara khusus, seperti طفل dalam ungkapan tentang seorang anak. Dalam teks, nakirah bisa muncul tanpa ال dan sering bertanwin pada bentuk berharakat yang sesuai. Fungsinya bukan sekadar aturan tulisan: pendengar belum diajak menunjuk satu orang atau benda tertentu. Pada banyak contoh isim mufrad biasa, nakirah muncul **tanpa الـ** dan menerima **tanwin**—seperti كِتَابٌ—tetapi isim nakirah tidak selalu harus bertanwin dalam setiap susunan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S03","level":2,"sublevel":3,"title":"Ma‘rifah: Ketika Maksudnya Sudah Jelas","conclusion":"Ma‘rifah menunjuk sesuatu yang sudah tertentu dalam pembicaraan, misalnya الكتاب, nama diri, atau isim isyarah seperti هذا. Kalau kita membaca هذا الكتاب مفيد, arah acuannya lebih jelas daripada menyebut sebuah buku secara umum. Untuk membedakannya, lihat bentuk kata serta konteks siapa atau apa yang sedang ditunjuk. Isim ma‘rifah dapat dikenali dari **الـ** pada kata tertentu, **nama diri**, **dhamir**, atau **isim isyarah**; **الْكِتَابُ** tertentu, sedangkan **كِتَابٌ** dalam contoh dasar masih umum.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S04","level":2,"sublevel":4,"title":"Mudzakkar dan Mu’annats","conclusion":"Mudzakkar dan mu’annats adalah kategori gramatikal yang memengaruhi kecocokan kata-kata Arab. Sebagian mu’annats mudah dikenali dari ة, misalnya مدرسة, tetapi ada pula yang tidak memakai tanda itu. Karena itu, saat membaca هذا قلم وهذه مدرسة, kita perhatikan bentuk penunjuk dan kata yang diikutinya, bukan menebak jenis hanya dari terjemahan Indonesia. Ciri mu’annats yang sering terlihat ialah **ة** pada akhir kata, tetapi jenis gramatikal tidak selalu ditentukan oleh huruf itu; cocokkan juga penunjuknya, seperti **هَذَا** dan **هَذِهِ**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S05","level":2,"sublevel":5,"title":"Mufrad: Satu","conclusion":"Mufrad berarti satu, baik yang dibicarakan orang maupun benda. Kata seperti سرير dapat menunjuk sebuah tempat tidur, berbeda dari bentuk yang menyatakan dua atau banyak. Menentukan mufrad lebih dulu membantu saat memilih kata tunjuk, sifat, dan bentuk kalimat yang cocok; jangan menyimpulkan jumlah hanya dari berapa kata yang tertulis. Mufrad menunjuk **satu** dan tidak memakai akhiran khas mutsanna atau jamak salim; saat menentukan harakat, lihat dulu fungsi kata dalam kalimat karena bentuk tunggal bisa marfu‘, manshub, atau majrur.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S06","level":2,"sublevel":6,"title":"Mutsanna: Dua","conclusion":"Mutsanna menyatakan dua orang atau dua benda. Ciri yang sering terlihat pada isim mu‘rab ialah akhiran ـانِ dalam keadaan rafa‘ dan ـيْنِ dalam nashab atau jar, sebagaimana pada contoh yang sesuai. Kita perlu membaca jumlah dan kedudukan sekaligus: bentuk akhirnya berubah karena fungsi kalimat, bukan karena bendanya tiba-tiba menjadi lebih dari dua. **Pola akhir mutsanna:** **ـانِ** saat **rafa‘**, sedangkan **ـيْنِ** saat **nashab** dan **jar**; perubahan ini menandai kedudukan gramatikal, bukan perubahan jumlah dua.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S07","level":2,"sublevel":7,"title":"Jama‘ Mudzakkar Salim","conclusion":"Jama‘ mudzakkar salim ialah bentuk jamak tertentu yang biasanya memakai ـونَ saat rafa‘ dan ـينَ saat nashab atau jar. Pada المعلمون, kita membaca kelompok para pengajar, bukan satu orang. Namun akhiran yang terlihat harus dipastikan dengan jenis kata dan konteks; jangan menyamakan setiap kata berakhiran mirip dengan pola ini. Perhatikan dua ujung yang khas: **ـونَ** untuk **rafa‘** dan **ـينَ** untuk **nashab/jar** pada jamak mudzakkar salim yang memenuhi syarat; ini bukan pola semua jamak laki-laki.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S08","level":2,"sublevel":8,"title":"Jama‘ Mu’annats Salim","conclusion":"Jama‘ mu’annats salim biasa dikenali dari tambahan ـات pada bentuk jamaknya, seperti الطالبات. Ini berbeda dari isim tunggal yang berakhir ة. Ketika menjumpainya, kita menilai jumlah serta bentuk kata, lalu mencocokkan fungsi kalimatnya; akhiran ـات saja tidak berarti semua katanya pasti menunjuk perempuan dalam setiap kasus. Dalam kaidah i‘rab, jamak mu’annats salim yang mu‘rab lazimnya **dhammah saat rafa‘** dan **kasrah saat nashab maupun jar**; jadi jangan otomatis memberi fathah ketika ia menjadi objek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S09","level":2,"sublevel":9,"title":"Jama‘ Taksir: Bentuk yang Berubah","conclusion":"Jama‘ taksir menyatakan banyak melalui perubahan bentuk kata, bukan selalu menambah akhiran tetap. Misalnya كتاب menjadi كتب. Karena polanya beragam, cara paling aman ialah mengenali pasangan mufrad–jamaknya dan melihat konteks. Kita tak bisa memaksakan rumus ـون atau ـات pada semua kata yang bermakna jamak. Jamak taksir tidak punya satu ekor tetap: **كِتَابٌ → كُتُبٌ** dan **رَجُلٌ → رِجَالٌ** sama-sama jamak, tetapi bentuknya berbeda; harakat akhirnya tetap ditentukan oleh fungsi i‘rab dan jenis isimnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L02-S10","level":2,"sublevel":10,"title":"Buka Kitab #02 — Tandai Semua Isimnya","conclusion":"Dalam satu petikan, sebuah isim bisa sekaligus nakirah atau ma‘rifah, mudzakkar atau mu’annats, dan mufrad, mutsanna, atau jamak. Ketiga pembagian ini menjawab pertanyaan berbeda: seberapa tertentu, kategori jenis, dan berapa jumlahnya. Saat membongkar kalimat, tentukan satu per satu memakai bukti bentuk serta konteks, bukan satu label untuk semuanya. Saat menandai isim, buat tiga pemeriksaan terpisah: **nakirah/ma‘rifah**, **mudzakkar/mu’annats**, dan **mufrad/mutsanna/jamak**; baru setelah fungsi kalimat diketahui kita dapat memilih tanda rafa‘, nashab, atau jar yang sesuai.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S01","level":3,"sublevel":1,"title":"Kalimat yang Tidak Dimulai Fi‘il","conclusion":"Jumlah ismiyah adalah kalimat yang dibangun dari pokok pembicaraan dan berita tentangnya, seperti العلم نور. Tidak setiap dua isim yang berdampingan otomatis menjadi kalimat lengkap; kita perlu memastikan ada informasi yang disampaikan. Kuncinya ialah bertanya: “Siapa atau apa yang sedang dibicarakan, lalu apa beritanya?”","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S02","level":3,"sublevel":2,"title":"Menemukan Mubtada’","conclusion":"Mubtada’ adalah unsur yang menjadi pokok pembicaraan dalam jumlah ismiyah. Dalam التلميذ مجتهد, التلميذ merupakan hal yang ingin kita bicarakan, sedangkan sisanya menyampaikan informasi. Isim dan mubtada’ bukan istilah yang sama: isim adalah jenis kata, mubtada’ adalah tugas kata itu di kalimat. Pada pola dasar, mubtada’ berstatus rafa‘. Pada **mubtada’ mufrad mu‘rab** dalam pola dasar, statusnya **marfu‘** dan umumnya tampak **dhammah**: **الطَّالِبُ**; bentuk mutsanna atau jamak tertentu punya tanda rafa‘ pengganti.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S03","level":3,"sublevel":3,"title":"Menemukan Khabar","conclusion":"Khabar adalah berita yang membuat pembicaraan tentang mubtada’ menjadi lengkap. Pada الطريق طويل, kata طويل memberi tahu keadaan jalan. Untuk mencarinya, jangan sekadar memilih kata kedua; lihat unsur mana yang menjawab “bagaimana atau apa tentang pokok tadi?”. Dalam contoh dasar, khabar mufrad berstatus rafa‘. Khabar satu kata pada pola dasar juga **marfu‘**; karena itu **مُجْتَهِدٌ** dapat berakhir **dhammah-tanwin**, sementara khabar berupa frasa jar atau zharaf tidak dipaksa mengikuti pola satu kata tersebut.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S04","level":3,"sublevel":4,"title":"Kenapa Keduanya Saling Membutuhkan?","conclusion":"Pasangan mubtada’ dan khabar membentuk pernyataan yang dapat dipahami, seperti الكتاب جديد. Berbeda dengan frasa sifat atau idhafah, hubungan ini menyampaikan sebuah berita. Jadi, kalau dua kata Arab tampak berdekatan, kita perlu menguji apakah keduanya sudah menjadi kalimat atau baru satu kelompok kata yang masih menunggu informasi.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S05","level":3,"sublevel":5,"title":"Mubtada’ Ma‘rifah","conclusion":"Mubtada’ sering berupa isim ma‘rifah, karena pembicara biasanya memulai dari sesuatu yang sudah dikenali, seperti الإمام atau nama diri. Namun aturan belajar awal ini jangan dianggap tidak punya pengecualian. Ketika menemukan awal jumlah ismiyah, kita cek apakah katanya jelas acuannya, lalu cari berita yang menyempurnakan maksudnya. Ma‘rifah bukan berarti pasti memakai **الـ**: nama orang, kata tunjuk, dan dhamir juga dapat menjadi mubtada’; yang memastikan kedudukannya tetap hubungan dengan khabar dalam kalimat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S06","level":3,"sublevel":6,"title":"Bentuk-Bentuk Khabar Sederhana","conclusion":"Khabar tidak selalu berupa satu sifat atau satu kata. Informasi tentang mubtada’ bisa hadir sebagai frasa jar–majrur atau keterangan tempat, misalnya pada المصحف على الرف. Yang penting bukan bentuk luarnya semata, melainkan apa yang diberitakan tentang pokok pembicaraan. Itulah sebabnya kadang khabar perlu dibaca sebagai satu kelompok. Kalau khabar berbentuk **jar–majrur** atau **zharaf**, bacalah sebagai satu kelompok keterangan; **على الرفّ** tidak diperlakukan seperti khabar isim mufrad yang cukup diberi dhammah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S07","level":3,"sublevel":7,"title":"Ketika Khabar Ada di Depan","conclusion":"Kadang berita muncul sebelum pokok pembicaraannya. Pada في المجلس ضيف, frasa tempat diletakkan di depan, kemudian baru disebut tamunya. Ini disebut khabar muqaddam dan mubtada’ mu’akhkhar dalam analisis yang sesuai. Jangan memaksa setiap jumlah ismiyah mengikuti urutan “isim dahulu, berita kemudian”; perhatikan fungsi, bukan hanya posisi. Tanda pengenal khabar muqaddam adalah **berita mendahului pokok**—sering berupa frasa tempat seperti **فِي الْمَجْلِسِ**—sementara mubtada’ mu’akhkhar datang setelahnya; jangan menetapkan i‘rab hanya dari urutan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S08","level":3,"sublevel":8,"title":"Membaca Harakat Akhirnya","conclusion":"Pada jumlah ismiyah dasar dengan isim mufrad mu‘rab, mubtada’ dan khabar mufrad biasanya marfu‘, dengan dhammah sebagai tanda asalnya. Namun bunyi akhir bukan hiasan; ia menunjukkan kedudukan kata. Untuk menentukan harakat pada الصدق محمود, cari hubungan mubtada’–khabar terlebih dahulu, baru pilih tanda akhirnya. Rumus awal yang perlu diingat: **mubtada’ marfu‘, khabar mufrad marfu‘**; pada isim mufrad biasa terbaca **ـُ (-u)** atau **ـٌ (-un)** bila menerima tanwin, bukan kasrah atau fathah asal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S09","level":3,"sublevel":9,"title":"Membongkar Jumlah Ismiyah Gundul","conclusion":"Dalam teks gundul, beberapa jumlah ismiyah bisa dihubungkan oleh و. Kita harus menemukan batas tiap pernyataan, lalu memetakan pokok dan beritanya masing-masing. Membaca النية صادقة والقلب ... akan lebih aman jika kita tidak menggabungkan dua berita menjadi satu tanpa alasan. Hubungan antarbagian menentukan terjemahannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L03-S10","level":3,"sublevel":10,"title":"Buka Kitab #03 — Satu Kalimat, Kita Harakati Sendiri","conclusion":"Saat membuka petikan jumlah ismiyah, mulailah dari pasangan yang saling melengkapi: apa pokoknya, apa beritanya, dan apakah urutannya biasa atau terbalik. Setelah itu tentukan tanda i‘rab yang memang bisa dibuktikan. Membaca kitab bukan lomba mengisi harakat paling cepat, melainkan menjelaskan mengapa susunannya masuk akal. Kalau pasangan mubtada’–khabar sama-sama isim mufrad mu‘rab, cek **dhammah rafa‘** pada keduanya; untuk khabar frasa, periksa hubungan jar atau tempat sebelum memutuskan akhir kata.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S01","level":4,"sublevel":1,"title":"Mengenali Fi‘il","conclusion":"Jumlah fi‘liyah biasanya berporos pada fi‘il, yaitu peristiwa yang dikisahkan. Dalam كتب خالد رسالة, kita melihat ada tindakan menulis, pelaku, dan sesuatu yang ditulis. Untuk memahaminya, temukan kejadian terlebih dulu, lalu tanyakan siapa yang berbuat dan apakah tindakannya menjangkau objek. Fi‘il adalah penanda **peristiwa**, bukan sekadar kata bermakna gerak; petunjuk bentuk madhi, mudhari‘, atau amar nantinya membantu membedakannya dari isim pelaku dan isim kegiatan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S02","level":4,"sublevel":2,"title":"Fi‘il Madhi","conclusion":"Fi‘il madhi menyatakan peristiwa yang dipandang sudah terjadi, seperti دخل dalam دخل المدرس الفصل. Bentuk ini berbeda dari isim yang menamai orang atau benda. Cara membacanya ialah memeriksa bentuk kerja dan konteks waktu, bukan hanya mengandalkan terjemahan satu kata yang mungkin terasa mirip. Pada contoh **madhi tsulatsi aktif** seperti **كَتَبَ**, huruf akhirnya bisa berbunyi fathah karena bentuknya **mabni**, bukan karena fi‘il itu menjadi maf‘ul bih yang manshub.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S03","level":4,"sublevel":3,"title":"Menemukan Pelaku: Fa‘il","conclusion":"Fa‘il adalah pelaku atau subjek gramatikal dari fi‘il aktif. Dalam قرأ التلميذ النص, kita dapat mencari siapa yang melakukan kegiatan membaca, kemudian membedakannya dari benda yang dibaca. Fa‘il bukan nama lain untuk semua isim sesudah fi‘il; yang menentukan adalah hubungan peristiwa dan tugas katanya. **Fa‘il** adalah pelaku gramatikal dari fi‘il aktif, biasanya berstatus **marfu‘**; untuk isim mufrad biasa, kita sering melihat **ـُ** atau **ـٌ** pada akhirnya, bukan fathah objek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S04","level":4,"sublevel":4,"title":"Kenapa Fa‘il Dibaca Rafa‘?","conclusion":"Fa‘il pada pola dasar berstatus marfu‘. Jika berbentuk isim mufrad biasa, tanda asal rafa‘ yang sering tampak ialah dhammah, seperti pada الضيف dalam contoh yang sesuai. Jangan memasang dhammah hanya karena kata berada setelah fi‘il; pastikan dulu bahwa dia memang fa‘il, bukan unsur lain. Pisahkan **status** dari **tanda**: fa‘il itu **marfu‘**, sementara **dhammah** hanya tanda asal rafa‘ pada isim mufrad biasa; mutsanna dapat memakai alif dan jamak mudzakkar salim memakai wawu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S05","level":4,"sublevel":5,"title":"Menemukan Maf‘ul Bih","conclusion":"Maf‘ul bih adalah objek langsung yang dikenai tindakan fi‘il muta‘addi. Pada حمل الولد الحقيبة, yang membawa adalah الولد dan yang dibawa adalah الحقيبة. Pertanyaan “apa atau siapa yang dikenai tindakan?” membantu kita menemukan objek, tetapi jawabannya tetap harus sesuai susunan gramatikal kalimat. **Maf‘ul bih** menerima tindakan fi‘il transitif dan pada pola dasar berstatus **manshub**; isim mufrad biasa sering bertanda **fathah** atau **fathah-tanwin**, bukan dhammah seperti fa‘il.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S06","level":4,"sublevel":6,"title":"Kenapa Maf‘ul Dibaca Nashab?","conclusion":"Maf‘ul bih dasar berstatus manshub, dan isim mufrad biasa sering ditandai fathah. Dalam شرح المعلم الدرس, setelah kita memastikan siapa yang menerangkan dan apa yang diterangkan, barulah tanda nashab pada objek memiliki alasan. Jangan menukar pelaku dan objek hanya karena letaknya berdekatan. Pada **شَرَحَ الْمُعَلِّمُ الدَّرْسَ**, bandingkan **ـُ** pada fa‘il dengan **ـَ** pada maf‘ul bih; fi‘il madhi **شَرَحَ** tidak disebut manshub hanya karena berbunyi fathah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S07","level":4,"sublevel":7,"title":"Fi‘il Lazim","conclusion":"Fi‘il lazim dalam penggunaan tertentu sudah membentuk peristiwa lengkap tanpa objek langsung, misalnya نام الطفل. Kita boleh menambahkan keterangan tempat atau waktu, tetapi itu bukan otomatis maf‘ul bih. Bedanya bukan panjang kalimat, melainkan apakah verba tersebut dalam konstruksi itu benar-benar mengambil objek. Fi‘il **lazim** dapat membentuk kalimat tanpa maf‘ul bih langsung, misalnya **جَلَسَ**; sesudahnya masih mungkin ada keterangan jar atau zharaf, jadi jangan memaksakan setiap isim menjadi objek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S08","level":4,"sublevel":8,"title":"Fi‘il Muta‘addi","conclusion":"Fi‘il muta‘addi dapat menjangkau maf‘ul bih, seperti pada أرسل الرجل الرسالة. Di sini tindakan mengirim mempunyai sesuatu yang dikirim. Saat menganalisisnya, lihat struktur penggunaan fi‘il dalam kalimat, karena satu akar kata bisa menghadirkan konstruksi yang berbeda menurut konteks. Fi‘il **muta‘addi** dapat membawa maf‘ul bih langsung; pada contoh aktif dasar, pelakunya **rafa‘** dan objeknya **nashab**, sehingga ujung kata membantu membedakan peran keduanya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S09","level":4,"sublevel":9,"title":"Jangan Sampai Pelaku dan Objek Ketuker","conclusion":"Pelaku dan objek bisa tertukar kalau kita hanya menebak dari arti yang terasa wajar. Dalam فهم الطالب السؤال, pelajar memahami pertanyaan, bukan sebaliknya; fungsi fa‘il dan maf‘ul bih memberi bukti. Cari fi‘ilnya, tentukan siapa melakukan, lalu apa yang terkena tindakan sebelum menyimpulkan harakat akhir. Ketika urutan kata berubah, lihat **fungsi dan tanda i‘rab**, bukan cuma posisi: fa‘il tetap marfu‘ dan maf‘ul bih tetap manshub pada susunan biasa, walau yang dibicarakan tampak bisa saling bertukar tempat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L04-S10","level":4,"sublevel":10,"title":"Buka Kitab #04 — Siapa Melakukan Apa kepada Siapa?","conclusion":"Di akhir latihan jumlah fi‘liyah, gunakan tiga pertanyaan berurutan: apa yang terjadi, siapa yang melakukan, dan apa yang dikenai tindakan bila ada. Perhatikan juga frasa jar atau kata penghubung yang ikut memberi konteks. Dengan urutan ini, kita bisa membaca dua peristiwa dalam satu petikan tanpa mengacak pelaku dan objek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S01","level":5,"sublevel":1,"title":"Huruf Jar","conclusion":"Huruf jar seperti من, إلى, في, dan على membentuk hubungan dengan isim setelahnya. Hasilnya disebut jar–majrur, yang sering memberi keterangan asal, tujuan, tempat, atau hubungan lain. Dalam خرج الطالب من المدرسة, frasa من المدرسة bukan objek langsung; ia menjelaskan dari mana peristiwa keluar berlangsung. Huruf jar yang sering terlihat ialah **مِنْ، إِلَى، فِي، عَلَى، بِـ، لِـ**; kata isim setelahnya menjadi **majrur**, biasanya berkasrah pada isim mufrad yang menerima tanda asal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S02","level":5,"sublevel":2,"title":"Isim Setelah Huruf Jar","conclusion":"Isim setelah huruf jar berstatus majrur. Pada isim mufrad munsharif biasa, kasrah adalah tanda asal yang sering kita dengar di akhirnya. Karena itu, ketika membaca على السبورة, kita periksa hubungan huruf jar dan isim sesudahnya dahulu; barulah bunyi akhir dipilih dengan alasan, bukan karena hafal satu contoh saja. **Jar** adalah kedudukan, **kasrah** hanya salah satu tandanya: **فِي الْبَيْتِ** berkasrah, sedangkan mutsanna dan jamak mudzakkar salim memakai **ـيْنِ/ـينَ** ketika majrur.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S03","level":5,"sublevel":3,"title":"Makna مِنْ","conclusion":"مِنْ sering menunjukkan asal atau titik awal perpindahan, seperti pada خرج الرجل من السوق. Kata ini menjawab “dari mana?”, berbeda dari إلى yang menunjukkan arah tujuan. Namun arti huruf dapat dipengaruhi konteks; pilih makna asal ketika konstruksi kalimat memang menyatakannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S04","level":5,"sublevel":4,"title":"Makna إِلَى","conclusion":"إِلَى menunjukkan arah atau tujuan pada banyak kalimat gerak. Dalam ذهب الولد إلى المكتب, unsur setelah إلى menjadi tujuan pergi, bukan tempat asal. Kita bisa memahami arah cerita dengan membandingkan من dan إلى: satu sering menjawab “dari mana”, yang lain “ke mana”.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S05","level":5,"sublevel":5,"title":"Makna فِي","conclusion":"فِي membantu menunjukkan lokasi atau keadaan berada di dalam suatu lingkup, seperti جلس القارئ في المسجد. Dalam analisis dasar, isim setelahnya majrur. Frasa itu menerangkan tempat, bukan nama pelaku. Terjemahkan sesuai konteks kalimat, karena في tidak selalu harus dipaksa menjadi “di dalam” secara harfiah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S06","level":5,"sublevel":6,"title":"Makna عَلَى","conclusion":"عَلَى sering menyatakan hubungan berada di atas permukaan, seperti buku yang diletakkan على المكتب. Dalam kalimat semacam ini, frasa jar menjawab lokasi penempatan, bukan benda yang dikenai tindakan. Pembedaan itu membuat terjemahan tidak menukar objek dengan keterangan tempat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S07","level":5,"sublevel":7,"title":"Makna بِـ dan لِـ","conclusion":"بِـ dan لِـ dapat menempel langsung di depan isim tetapi tetap berfungsi sebagai huruf jar. بِـ kerap menunjukkan alat, cara, atau hubungan tertentu; لِـ bisa menunjukkan peruntukan atau keterkaitan. Perhatikan bentuk yang menempel, kata setelahnya, dan tindakan dalam kalimat sebelum memilih padanan Indonesia yang paling masuk akal. **بِـ** dan **لِـ** sering menempel tanpa spasi pada isim, tetapi keduanya tetap huruf jar; setelahnya berlaku hukum **majrur**, meski huruf jar terlihat seperti bagian kata.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S08","level":5,"sublevel":8,"title":"Satu Huruf, Makna Bisa Berubah","conclusion":"Satu huruf jar tidak selalu punya satu terjemahan untuk semua keadaan. بِـ, misalnya, dapat berbeda maknanya menurut fi‘il dan konteksnya, meskipun hubungan jar pada isim tetap berlaku. Membaca dengan teliti berarti membedakan aturan gramatikal yang relatif tetap dari arti Indonesia yang bisa bergeser.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S09","level":5,"sublevel":9,"title":"Mendeteksi Jar di Teks Gundul","conclusion":"Teks gundul tetap memperlihatkan banyak huruf jar, walau kasrah akhirnya tidak terlihat. Ketika menemukan نظر القارئ إلى الورق, tandai إلى dan kata yang dihubungkannya sebelum menebak bunyi akhir. Hubungan itu menjadi petunjuk kuat untuk membaca dan menerjemahkan keseluruhan peristiwa. Saat petikan gundul menyembunyikan kasrah, cari dulu huruf jar yang terlihat; status majrur bisa ditetapkan dari hubungan **huruf jar + isim**, lalu tandanya disesuaikan dengan jenis isim.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L05-S10","level":5,"sublevel":10,"title":"Buka Kitab #05 — Berburu Huruf Jar","conclusion":"Dalam satu paragraf, kita mungkin menemukan beberapa frasa jar sekaligus: ada yang menyebut asal, ada yang menyebut arah atau tempat. Pisahkan setiap huruf dari isim yang diikutinya, pastikan hubungan maknanya, lalu susun terjemahan yang wajar. Jangan mengubah semua frasa jar menjadi maf‘ul bih hanya karena sama-sama berada setelah fi‘il.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S01","level":6,"sublevel":1,"title":"Apa Itu Mudhaf–Mudhaf Ilaih?","conclusion":"Idhafah adalah hubungan dua isim atau lebih yang dibaca sebagai satu kelompok, seperti كتاب الطالب. Isim pertama disebut mudhaf, sedangkan yang kedua mudhaf ilaih; hubungan ini bisa menyatakan kepemilikan atau keterkaitan. Untuk mengenalinya, cari kata mana yang menjadi pokok dan kata mana yang menerangkan hubungan itu. Dalam **idhafah**, **mudhaf** adalah isim pertama yang tidak menerima tanwin pada susunan biasa, sedangkan **mudhaf ilaih** berstatus **majrur**; kelompok keduanya menjawab hubungan “apa milik/terkait siapa”.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S02","level":6,"sublevel":2,"title":"Cara Menemukan Pasangan Idhafah","conclusion":"Pasangan idhafah tidak selalu berdiri sendirian. Dalam هذا باب المدرسة, باب المدرسة menjadi satu kelompok yang terletak di tengah susunan lebih besar. Karena itu, kita perlu menentukan batas pasangan isim terlebih dahulu, baru menilai fungsi kelompok tersebut terhadap kata-kata lain. Pola pasangan idhafah biasanya tampak dari dua isim yang bertaut tanpa perantara kata “milik”; cari **mudhaf** di depan dan **mudhaf ilaih** sesudahnya, lalu periksa apakah yang kedua terkena hukum jar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S03","level":6,"sublevel":3,"title":"Mudhaf Tidak Menerima ال","conclusion":"Pada idhafah biasa, mudhaf tidak menerima ال dan tanwin, walau mudhaf ilaih dapat memiliki ال. Lihat كتاب الإمام: kata pertama terikat pada kata kedua dan tidak ditanwini. Ini petunjuk bentuk yang membantu, tetapi kita tetap harus memastikan ada hubungan idhafah, bukan asal menyandingkan dua isim. Untuk idhafah hakiki yang dipelajari, **mudhaf** tidak memakai **الـ** maupun **tanwin**, tetapi harakat akhirnya tetap bergantung pada fungsinya: bisa rafa‘, nashab, atau jar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S04","level":6,"sublevel":4,"title":"Mudhaf Ilaih Selalu Majrur","conclusion":"Mudhaf ilaih berstatus majrur. Jika berupa isim mufrad munsharif biasa, kasrah menjadi tanda asalnya, misalnya dalam باب المسجد. Status mudhaf ilaih tidak sama dengan status mudhaf: kata pertama masih mengikuti fungsi kelompok dalam kalimat, sementara kata kedua dijarkan karena idhafah. **Mudhaf ilaih selalu majrur** dalam konstruksi idhafah; pada isim mufrad munsharif biasanya **kasrah**, pada mutsanna atau jamak mudzakkar salim dapat berupa **ya**, sesuai bentuk katanya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S05","level":6,"sublevel":5,"title":"Idhafah dan Makna Kepemilikan","conclusion":"Idhafah sering kita terjemahkan dengan hubungan milik, seperti كتاب الولد yang dapat bermakna “buku anak itu”. Kita tidak selalu perlu menyisipkan kata “milik” secara kaku dalam bahasa Indonesia. Yang penting, hubungan dua isimnya terjaga dan sesuai konteks pembicaraan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S06","level":6,"sublevel":6,"title":"Idhafah yang Tidak Harfiah","conclusion":"Tidak semua idhafah berarti kepemilikan secara harfiah. باب العلم, misalnya, berbicara tentang sebuah bab atau pintu pembahasan ilmu, bukan ilmu yang mempunyai barang. Idhafah bisa menyatakan bagian, waktu, bahan, atau keterkaitan lain; pilih arti yang ditopang konteks, bukan satu rumus terjemahan untuk semuanya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S07","level":6,"sublevel":7,"title":"Idhafah Bertingkat","conclusion":"Idhafah bisa bertingkat, misalnya مفتاح باب المدرسة. Dalam rantai seperti ini, isim tengah menerangkan yang pertama sekaligus menjadi mudhaf bagi kata setelahnya. Supaya tidak salah terjemah, baca keterkaitan dari rangkaian terdekat, lalu susun kembali menjadi kelompok makna yang utuh. Dalam rantai seperti **مِفْتَاحُ بَابِ الْمَدْرَسَةِ**, kata tengah **بَابِ** bisa sekaligus menjadi mudhaf ilaih dari unsur pertama dan mudhaf bagi unsur ketiga; perhatikan kasrahnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S08","level":6,"sublevel":8,"title":"Jangan Tertukar dengan Na‘at","conclusion":"Idhafah dan na‘at sama-sama menghadirkan dua isim berdekatan, tetapi pekerjaannya berbeda. باب البيت menghubungkan “pintu” dengan “rumah”, sedangkan pasangan na‘at menyatakan sifat yang mengikuti kata diterangkannya. Periksa ال, tanwin, kecocokan bentuk, dan relasi makna sebelum memilih salah satu analisis. Pembedanya: **idhafah** menautkan dua isim dengan **mudhaf ilaih majrur**, sementara **na‘at** mengikuti man‘ut dalam i‘rab, ma‘rifah–nakirah, jenis, dan jumlah pada pola dasarnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S09","level":6,"sublevel":9,"title":"Membongkar Idhafah Gundul","conclusion":"Saat harakat hilang, rangkaian idhafah bisa terlihat seperti deretan kata biasa. Kita tetap dapat memperhatikan kedekatan dua isim, susunan ال, dan maknanya. Setelah hubungan mudhaf–mudhaf ilaih ditemukan, barulah harakat akhir ditentukan sesuai peran tiap bagian—bukan dibaca seragam.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L06-S10","level":6,"sublevel":10,"title":"Buka Kitab #06 — Memburu Rantai Idhafah","conclusion":"Untuk membongkar idhafah panjang, cari kata inti lalu ikuti keterangan yang menempel padanya satu per satu. Rantai semacam مفتاح باب المدرس bukan tiga kalimat terpisah. Pahami dulu hubungan antarisim, cek siapa yang majrur, kemudian gabungkan maknanya dalam satu terjemahan yang wajar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S01","level":7,"sublevel":1,"title":"Mengenal Na‘at","conclusion":"Na‘at adalah sifat yang menerangkan man‘ut, yaitu isim yang dijelaskan. Dalam طالب مجتهد, kata kedua menggambarkan keadaan pelajar, bukan otomatis menjadi berita sebuah kalimat. Agar tidak tertukar, kita perlu melihat apakah sifat itu melekat pada isim atau berdiri sebagai khabar. Na‘at adalah **sifat yang menerangkan isim (man‘ut)**; dalam bentuk sifat hakiki yang dipelajari, ia menyesuaikan **i‘rab, ma‘rifah–nakirah, mudzakkar–mu’annats, dan mufrad–mutsanna–jamak**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S02","level":7,"sublevel":2,"title":"Man‘ut: Kata yang Diterangkan","conclusion":"Man‘ut adalah kata yang diterangkan, dan na‘at mengikuti keadaan gramatikalnya. Dalam البستان الجميل واسع, البستان merupakan man‘ut bagi الجميل, sedangkan واسع membawa berita. Temukan dulu kata yang menjadi pusat frasa, lalu pastikan bagian mana yang benar-benar sifatnya. Man‘ut ialah **isim yang diterangkan**; ciri menemukan pasangan sifat adalah kesesuaian bentuk dan makna, seperti **الطَّالِبُ الْمُجْتَهِدُ**, bukan sekadar dua kata yang berdampingan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S03","level":7,"sublevel":3,"title":"Kesamaan Harakat","conclusion":"Pada na‘at hakiki yang dipelajari di tahap ini, i‘rab na‘at mengikuti man‘ut: ketika man‘ut marfu‘, manshub, atau majrur, sifatnya ikut sesuai. Itulah sebabnya tanda akhir kedua kata perlu dibaca sebagai pasangan, bukan ditentukan secara terpisah tanpa melihat fungsinya. Untuk na‘at hakiki biasa, **marfu‘ bertemu marfu‘**, **manshub bertemu manshub**, dan **majrur bertemu majrur**; pada isim mufrad mu‘rab tanda asalnya berturut-turut **dhammah, fathah, kasrah**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S04","level":7,"sublevel":4,"title":"Kesamaan Ma‘rifah–Nakirah","conclusion":"Na‘at juga mengikuti man‘ut dalam ma‘rifah dan nakirah. Bentuk طالب مجتهد sama-sama tidak memakai ال, sedangkan الطالب المجتهد sama-sama ber-ال. Kecocokan ini membantu membedakan frasa sifat dari jumlah ismiyah; jangan menyebut kata kedua sebagai khabar sebelum menilai pola keduanya. Pasangan yang benar memperhatikan ketentuan: **الطَّالِبُ الْمُجْتَهِدُ** sama-sama ma‘rifah, sedangkan **طَالِبٌ مُجْتَهِدٌ** sama-sama nakirah; beda status ini bisa mengubah pembacaan sifat menjadi khabar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S05","level":7,"sublevel":5,"title":"Kesamaan Gender","conclusion":"Pada contoh na‘at hakiki mufrad, sifat menyesuaikan mudzakkar atau mu’annats dari man‘ut, seperti طالِب مُجْتَهِد atau طالِبَة مُجْتَهِدَة. Kecocokan jenis gramatikal harus diperiksa dari kata Arabnya, bukan sekadar dari perkiraan kita tentang jenis orang atau benda dalam terjemahan. Sifat hakiki lazimnya mengikuti jenis man‘ut: **طَالِبٌ مُجْتَهِدٌ** untuk mudzakkar dan **طَالِبَةٌ مُجْتَهِدَةٌ** untuk mu’annats; tanda **ة** membantu, tetapi tidak mencakup semua kasus.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S06","level":7,"sublevel":6,"title":"Kesamaan Jumlah","conclusion":"Jumlah atau bilangan gramatikal juga penting: untuk orang, pasangan sifat dapat berubah sesuai mufrad, mutsanna, atau jamak. Ketika membaca الطالبان المجتهدان, dua unsur itu harus cocok dalam bentuk yang dipakai. Namun aturan jamak untuk yang bukan manusia punya pembahasan tersendiri, jadi jangan menggeneralisasi satu pola ke semua kata. Pada contoh sifat hakiki biasa, **mufrad** diikuti sifat mufrad, **mutsanna** diikuti sifat mutsanna, dan **jamak** mengikuti aturan kesesuaian yang sesuai; jamak bukan manusia punya ketentuan tersendiri.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S07","level":7,"sublevel":7,"title":"Na‘at vs Khabar","conclusion":"Na‘at menjelaskan isim dalam satu frasa, sedangkan khabar memberi informasi yang melengkapi jumlah ismiyah. Pada الطالب المجتهد حاضر, المجتهد melekat pada الطالب, sementara حاضر menyampaikan berita. Salah memilih keduanya bisa membuat kita memotong kalimat di tempat yang keliru. Na‘at dan khabar jangan disamakan hanya karena sama-sama menerangkan: **الطَّالِبُ الْمُجْتَهِدُ** dapat menjadi frasa sifat, sedangkan **الطَّالِبُ مُجْتَهِدٌ** menyampaikan berita lengkap.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S08","level":7,"sublevel":8,"title":"Na‘at vs Idhafah","conclusion":"Pasangan sifat dan idhafah bisa tampak mirip saat gundul, tetapi hubungan maknanya berbeda. Na‘at menyatakan ciri dari satu isim, sementara idhafah menghubungkan dua isim. Karena itu, periksa kecocokan ma‘rifah–nakirah serta tanda bentuknya sebelum memutuskan apakah yang dibaca adalah “siswa rajin” atau “buku siswa”. Na‘at menyesuaikan man‘ut; idhafah justru terdiri dari **mudhaf + mudhaf ilaih yang majrur** dan mudhaf tidak bertanwin pada susunan biasa—dua hubungan yang perlu dikenali sebelum memberi harakat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S09","level":7,"sublevel":9,"title":"Deteksi Susunan dalam Teks","conclusion":"Sebuah kalimat dapat memuat na‘at, khabar, dan idhafah sekaligus. Supaya tidak tertipu oleh kata-kata yang berdampingan, cari dulu pasangan lokalnya: siapa diterangkan sifat, siapa berhubungan idhafah, dan mana berita kalimat. Sesudah peta itu jelas, harakat dan terjemahan akan jauh lebih mudah dipertanggungjawabkan. Saat mencari sifat di kitab gundul, kumpulkan empat bukti kesesuaian—**i‘rab, ketentuan ma‘rifah, jenis, jumlah**—lalu uji apakah pasangan itu lebih tepat dibaca sebagai **na‘at** atau **khabar**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L07-S10","level":7,"sublevel":10,"title":"Buka Kitab #07 — Ini Sifat atau Bukan?","conclusion":"Di akhir pembahasan na‘at, pegangan kita adalah empat kecocokan pada pola yang dipelajari: i‘rab, ma‘rifah–nakirah, jenis, dan jumlah. Namun kemampuan pentingnya bukan sekadar menghafal empat daftar, melainkan membuktikan bahwa satu kata benar-benar menjadi sifat bagi isim tertentu dalam petikan utuh.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S01","level":8,"sublevel":1,"title":"Apa Sebenarnya I‘rab?","conclusion":"I‘rab menjelaskan perubahan status gramatikal yang tercermin pada akhir kata mu‘rab karena kedudukannya dalam susunan. Tidak semua kata berubah bentuk akhir; ada pula yang mabni. Jadi, saat akhir satu isim terdengar berbeda, cari dulu fungsi dan pengaruh dalam kalimat, bukan menamai semua bunyi akhir sebagai satu hukum. **I‘rab** menyatakan perubahan status akhir kata karena fungsinya; **dhammah, fathah, kasrah, sukun** ialah tanda asal untuk kategori yang sesuai, bukan empat bunyi yang bisa ditempel sembarang.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S02","level":8,"sublevel":2,"title":"Rafa‘","conclusion":"Rafa‘ adalah salah satu status i‘rab. Pada contoh dasar, mubtada’ dan fa‘il sering marfu‘, dan isim mufrad munsharif biasa bertanda dhammah. Ketika membaca sebuah kalimat, tentukan dulu siapa pokok pembicaraan atau pelakunya; tanda rafa‘ merupakan hasil analisis itu, bukan tebakan dari letak kata. Tanda asal **rafa‘** ialah **dhammah** pada isim mufrad mu‘rab dan mudhari‘ shahih akhir yang tidak terkena pengubah, sedangkan mutsanna memakai **alif** dan jamak mudzakkar salim memakai **wawu**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S03","level":8,"sublevel":3,"title":"Nashab","conclusion":"Nashab dapat muncul pada objek langsung seperti maf‘ul bih. Untuk isim mufrad biasa, tanda asalnya fathah, tetapi tidak semua isim manshub selalu berakhir fathah. Kenali terlebih dahulu tugas kata dalam kalimat, kemudian lihat bentuk isimnya agar tanda yang dipilih tidak salah. Tanda dasar **nashab** ialah **fathah** pada isim mufrad biasa dan mudhari‘ tertentu; pada mutsanna/jamak mudzakkar salim bisa **ya**, sedangkan jamak mu’annats salim memakai **kasrah**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S04","level":8,"sublevel":4,"title":"Jar","conclusion":"Jar terjadi antara lain sesudah huruf jar atau pada mudhaf ilaih. Pada isim mufrad munsharif biasa, tanda asalnya kasrah. Saat kita melihat bentuk seperti في المسجد atau باب المسجد, cari penyebab jar yang berbeda itu; bunyi akhirnya mungkin mirip, tetapi sumber hubungan gramatikalnya tidak sama. Tanda asal **jar** ialah **kasrah** pada isim yang memenuhi syarat; mutsanna dan jamak mudzakkar salim memakai **ya**, dan ghairu munsharif dalam kondisi tertentu memakai **fathah**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S05","level":8,"sublevel":5,"title":"Jazm","conclusion":"Jazm berkaitan dengan fi‘il mudhari‘, bukan status jar pada isim. Dalam contoh dengan لَمْ, mudhari‘ shahih akhir dapat dijazmkan sehingga tanda asalnya sukun. Untuk membacanya, periksa partikel yang mendahului fi‘il dan bentuk kerjanya; jangan menukar jazm dan jar hanya karena sama-sama membahas akhir kata. **Jazm berlaku pada fi‘il mudhari‘**, bukan isim; pada mudhari‘ shahih akhir tanda dasarnya **sukun**, sedangkan fi‘il mu‘tal atau af‘al khamsah punya tanda pengganti.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S06","level":8,"sublevel":6,"title":"Dhammah Bukan Selalu “Rafa‘ Biasa”","conclusion":"Dhammah bukan satu-satunya tanda rafa‘. Pada bentuk yang dipelajari, mutsanna dapat memakai alif dan jamak mudzakkar salim memakai wawu sebagai tanda rafa‘. Jadi, sebelum mengharakati kata marfu‘, kita harus tahu jenis bentuk isimnya. Statusnya sama-sama rafa‘, tetapi tandanya bisa berbeda. Ingat tiga contoh rafa‘ berbeda: **الطَّالِبُ** dengan **dhammah**, **الطَّالِبَانِ** dengan **alif**, dan **الْمُعَلِّمُونَ** dengan **wawu**; semuanya bisa sama-sama marfu‘.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S07","level":8,"sublevel":7,"title":"Fathah dan Penggantinya","conclusion":"Nashab punya tanda pengganti sesuai kelompok isim. Selain fathah sebagai tanda asal, mutsanna dan jamak mudzakkar salim memakai ya’, sedangkan jamak mu’annats salim dapat memakai kasrah. Kuncinya ialah memisahkan dua pertanyaan: “Apa status katanya?” dan “Dengan tanda apa status itu tampak?” Kata **manshub** belum tentu berakhir fathah: mutsanna dan jamak mudzakkar salim bisa memakai **ya**, sedangkan jamak mu’annats salim memakai **kasrah** sebagai tanda pengganti.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S08","level":8,"sublevel":8,"title":"Kasrah dan Penggantinya","conclusion":"Jar juga tidak selalu ditandai kasrah. Mutsanna dan jamak mudzakkar salim pada pola yang dipelajari menggunakan ya’ saat jar. Ketika menemukan isim majrur, jangan langsung menambahkan kasrah tanpa melihat apakah bentuk katanya tunggal, dua, atau jamak tertentu. Kata **majrur** belum tentu berkasrah: pada mutsanna dan jamak mudzakkar salim tandanya **ya**, sedangkan sebagian isim ghairu munsharif memakai **fathah** saat tidak ber-ال dan tidak menjadi mudhaf.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S09","level":8,"sublevel":9,"title":"Cara Menentukan Harakat dari Posisi","conclusion":"Urutan kerja i‘rab yang aman ialah mengenali jenis kata, menemukan fungsinya, menentukan status rafa‘–nashab–jar atau jazm, baru memilih tanda yang cocok dengan bentuknya. Langkah ini mencegah kita memberi harakat hanya berdasarkan rasa. Alasan bacaan harus bisa ditunjukkan dari struktur kalimat. Urutannya harus **jenis kata → fungsi → status i‘rab → tanda**; fi‘il madhi yang mabni fathah tidak otomatis manshub, dan isim mabni tidak berubah bunyi akhir hanya karena berganti fungsi.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L08-S10","level":8,"sublevel":10,"title":"Buka Kitab #08 — Harakati Kalimat Tanpa Menebak","conclusion":"Membaca kitab gundul pada tahap ini berarti berani memberi harakat hanya pada bagian yang bukti nahwunya cukup. Cari amil atau hubungan yang relevan, periksa tugas setiap kata, lalu cocokkan status dan tanda akhirnya. Kalau masih ada dua kemungkinan, catat keduanya sebelum memilih satu secara tergesa-gesa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S01","level":9,"sublevel":1,"title":"Akar Kata","conclusion":"Akar kata adalah huruf-huruf dasar yang mengikat satu keluarga makna. Dari satu akar, bahasa Arab dapat membentuk kata dengan tugas dan arti yang berbeda. Saat menebak makna bentuk turunan, cari huruf asli yang tetap terlihat, tetapi jangan menganggap semua anggota keluarga pasti bisa diterjemahkan dengan kata Indonesia yang sama. Akar kata adalah **huruf asal** pembawa keluarga makna, biasanya tiga pada contoh tsulatsi; huruf yang kelihatan panjang tidak semuanya huruf akar, karena bentuk tashrif bisa menambah unsur.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S02","level":9,"sublevel":2,"title":"Huruf Asli dan Tambahan","conclusion":"Huruf asli menjadi rangka pembentukan kata, sedangkan huruf tambahan masuk dalam pola atau wazan tertentu. Pada bentuk seperti كاتب dan مكتوب, kita belajar memisahkan akar dari unsur pembentuk makna baru. Caranya bukan mencoret sembarang huruf yang terasa panjang, melainkan membandingkan dengan wazan dan bentuk yang sudah dikenal. Bandingkan huruf asli dengan tambahan melalui pasangan bentuk kata dan **wazan**; **ا، ت، س، م** yang terlihat tidak otomatis tambahan jika belum diuji terhadap akar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S03","level":9,"sublevel":3,"title":"Wazan","conclusion":"Wazan adalah timbangan bentuk kata, misalnya فاعل atau مفعول, yang membantu membaca pola pembentukan. Huruf ف–ع–ل dalam timbangan mewakili posisi akar, bukan berarti setiap kata turunan berakar pada huruf itu. Dengan wazan kita bisa memahami perbedaan pelaku dan yang dikenai tindakan tanpa kehilangan akar aslinya. **Wazan** ialah timbangan bentuk kata seperti **فَعَلَ**; posisi **ف، ع، ل** mewakili huruf asal dan harakat pola membantu mengenali bagaimana bentuk diturunkan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S04","level":9,"sublevel":4,"title":"فَعَلَ sebagai Timbangan","conclusion":"Fi‘il madhi triliteral dapat memiliki pola vokal yang berbeda, seperti فَعَلَ dan فَعِلَ. Sama-sama tiga huruf bukan berarti otomatis sama harakatnya. Untuk menentukan bacaan yang tepat, kita membutuhkan bentuk yang sudah diketahui atau rujukan kamus, bukan sekadar memilih pola yang paling sering terdengar. Pola **فَعَلَ** menjadi ukuran untuk madhi tsulatsi aktif seperti **كَتَبَ**; huruf **ف–ع–ل** pada timbangan bukan arti kata, melainkan tempat mencocokkan akar dan harakat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S05","level":9,"sublevel":5,"title":"Menemukan Akar dari Kata","conclusion":"Menemukan akar kata berarti menanggalkan unsur tambahan dengan hati-hati lalu menempatkan huruf asli pada pola yang cocok. Proses ini membantu menghubungkan kata turunan dengan keluarga maknanya. Namun sebuah bentuk gundul bisa ambigu; kalau bukti sharaf belum cukup, beberapa kandidat akar perlu dibandingkan lebih dulu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S06","level":9,"sublevel":6,"title":"Makna Dasar Akar","conclusion":"Akar memberi petunjuk bidang makna, bukan terjemahan final untuk semua turunannya. Satu keluarga kata bisa berbicara tentang tindakan, pelaku, hasil, atau benda terkait. Karena itu, setelah menemukan akar, kita tetap memeriksa wazan dan fungsi katanya dalam kalimat sebelum memilih arti Indonesia.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S07","level":9,"sublevel":7,"title":"Isim Jamid","conclusion":"Isim jamid adalah isim yang pada analisis tertentu tidak diperlakukan sebagai bentuk turunan dari kata lain. Ini tidak sama dengan mengatakan bahwa kata itu tidak punya akar sama sekali. Kita mengenalinya dari pembentukan dan pemakaiannya; jangan memaksakan setiap isim ke wazan musytaq hanya karena terlihat mirip. **Isim jamid** tidak diperlakukan sebagai turunan bentuk seperti isim fa‘il dalam analisis yang sedang dipelajari; jangan mengarang wazan turunan hanya karena dua kata kelihatan mirip.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S08","level":9,"sublevel":8,"title":"Isim Musytaq","conclusion":"Isim musytaq merupakan bentuk turunan yang menyimpan hubungan dengan asal kata. Isim fa‘il menunjuk pelaku tindakan, sedangkan isim maf‘ul menunjuk yang dikenai tindakan dalam contoh yang sesuai. Memahami arah makna itu membuat kita tidak menukar “yang menulis” dengan “yang ditulis”, walau akar katanya masih sekeluarga. **Isim musytaq** adalah bentuk turunan yang memberi petunjuk fungsi atau sifat; periksa hubungan **akar + pola**, misalnya perbedaan pelaku dan yang dikenai tindakan, bukan hanya terjemahan bebas.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S09","level":9,"sublevel":9,"title":"Kamus Arab: Cari dari Mana?","conclusion":"Mencari kata Arab dalam kamus bergantung pada sistem kamusnya. Ada kamus yang menata entri menurut akar, ada yang menerima bentuk kata sebagaimana tertulis. Sebelum mencari, periksa apakah bentuk itu turunan, kenali akar jika perlu, lalu uji pilihan arti terhadap konteks kalimat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L09-S10","level":9,"sublevel":10,"title":"Buka Kitab #09 — Berburu Akar Kata","conclusion":"Ketika membaca petikan gundul, akar, wazan, dan fungsi kata bekerja bersama. Akar memberi keluarga makna, wazan memberi petunjuk bentuk, dan susunan kalimat menentukan perannya. Ketiganya perlu diuji silang supaya kita tidak merasa sudah paham hanya karena berhasil mengenali tiga huruf yang berulang.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S01","level":10,"sublevel":1,"title":"Madhi","conclusion":"Fi‘il madhi biasa menyatakan peristiwa lampau atau yang dipandang telah selesai. Bentuknya perlu dikenali melalui pola kata dan konteks, bukan hanya karena terjemahannya memakai “telah”. Saat membaca teks gundul, pilih vokalisasi madhi yang memang didukung bentuk dan kosakata yang diketahui. Madhi contoh dasar **كَتَبَ** menunjukkan kejadian yang selesai; pada bentuk aktif tsulatsi tanpa sambungan, akhir fathah berasal dari **bina’ fi‘il madhi**, bukan tanda nashab isim.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S02","level":10,"sublevel":2,"title":"Mudhari‘","conclusion":"Fi‘il mudhari‘ digunakan untuk tindakan yang berkaitan dengan waktu kini atau mendatang, bergantung konteks. Salah satu petunjuknya ialah huruf mudhara‘ah di awal bentuk yang sesuai. Tetapi awalan yang mirip belum cukup; kita tetap perlu memastikan akar, pola, dan fungsi dalam kalimat. Mudhari‘ umumnya dikenali dari salah satu awalan **أ، ن، ي، ت** pada bentuk yang tepat; akhir mudhari‘ shahih tanpa nashib/jazim biasanya **dhammah**, berubah sesuai ‘amil yang masuk.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S03","level":10,"sublevel":3,"title":"Amar","conclusion":"Fi‘il amar menyampaikan perintah, misalnya kepada satu orang lawan bicara dalam contoh dasar. Bentuknya tidak sama dengan madhi yang mengisahkan peristiwa selesai. Untuk memahami amar, lihat siapa yang diajak bertindak dan bagaimana fi‘il dibentuk; jangan semua kalimat bernada kuat langsung disebut amar gramatikal. Amar menyampaikan perintah, misalnya **اُكْتُبْ**; pada bentuk dasar yang dibahas, akhirnya **sukun** karena **mabni**, bukan karena isim atau fi‘il itu manshub.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S04","level":10,"sublevel":4,"title":"Tashrif Dasar","conclusion":"Tashrif membantu menghubungkan beberapa bentuk sebuah fi‘il, misalnya madhi, mudhari‘, dan amar. Hubungan ini memberi kita peta perubahan bentuk tanpa harus menebak harakat dari tulisan gundul. Hafalan pola baru berguna bila disertai contoh yang benar dan pengetahuan akar katanya. Saat men-tashrif, periksa **perubahan awalan, akhiran, dan harakat** karena pelaku serta waktu dapat berubah; jangan memaksakan satu bunyi akhir fi‘il untuk seluruh bentuk turunannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S05","level":10,"sublevel":5,"title":"Dhamir pada Fi‘il","conclusion":"Dhamir berkaitan dengan siapa yang melakukan tindakan serta berapa jumlahnya. Bentuk fi‘il dapat berubah untuk orang pertama, kedua, atau ketiga; tunggal dan bentuk jumlah lain juga dapat berbeda. Saat menemukan perubahan fi‘il, kita baca petunjuk persona pada bentuknya sebelum menentukan subjek dalam terjemahan. Awalan atau akhiran fi‘il dapat memberi petunjuk dhamir pelaku, seperti perbedaan **كَتَبْتُ، كَتَبَ، يَكْتُبُ**; tentukan bentuk dan orangnya dari pola, bukan nama orang yang kita bayangkan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S06","level":10,"sublevel":6,"title":"Pelaku yang Tersembunyi","conclusion":"Pelaku fi‘il tidak selalu tampil sebagai isim terpisah. Pada bentuk tertentu, dhamir fa‘il sudah dipahami dari fi‘ilnya, sehingga tidak perlu dicari-cari kata baru. Akan tetapi, jika tulisan gundul memungkinkan lebih dari satu bacaan, kita wajib memakai konteks dan mengakui yang belum pasti. Fa‘il kadang sudah terkandung dalam bentuk fi‘il melalui **dhamir mustatir**; sebuah mudhari‘ dengan pelaku tersirat tidak harus diikuti isim fa‘il yang disebut terang-terangan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S07","level":10,"sublevel":7,"title":"Ma‘lum","conclusion":"Ma‘lum berarti bentuk aktif yang pada contoh dasarnya dapat dihubungkan dengan pelaku tindakan. Kita menanyakan “siapa melakukan?” lalu membedakan fa‘il dari objek. Perhatikan vokalisasi dan susunan: tidak cukup memutuskan sebuah kata aktif hanya karena arti Indonesianya terdengar seperti perbuatan. Bentuk **ma‘lum** menyebut peristiwa dengan pelaku gramatikal, sedangkan **majhul** menyembunyikan pelaku; untuk triliteral shahih aktif **كَتَبَ**, padanan pasif dasarnya **كُتِبَ**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S08","level":10,"sublevel":8,"title":"Majhul","conclusion":"Majhul ialah bentuk pasif yang tidak menampilkan pelaku aktif dengan cara yang sama. Dalam susunan dasarnya, unsur yang menggantikan kedudukan fa‘il disebut na‘ib fa‘il. Membedakan ma‘lum dan majhul membutuhkan bukti bentuk fi‘il serta konstruksi kalimat; pada teks gundul, kesimpulan bisa menunggu verifikasi harakat. Pola pasif madhi triliteral shahih yang dipelajari ialah **فُعِلَ** (awal dhammah, sebelum akhir kasrah), dan pasif mudhari‘ **يُفْعَلُ** (awalan dhammah, sebelum akhir fathah); na‘ib fa‘il berstatus marfu‘.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S09","level":10,"sublevel":9,"title":"Membaca Bentuk Fi‘il Gundul","conclusion":"Bentuk fi‘il tanpa harakat kadang membuka lebih dari satu kemungkinan bacaan. Periksa huruf asal, petunjuk persona, konteks, serta hubungan dengan isim di sekitarnya. Jika satu pembacaan belum terbukti, jangan memaksa kepastian; membaca secara ilmiah berarti tahu bagian mana yang masih perlu dikonfirmasi. Saat teks gundul menulis **كتب**, bacaan **كَتَبَ** dan **كُتِبَ** dapat berbeda tanpa perubahan huruf; penentunya susunan pelaku, konteks, serta pola harakat yang masuk akal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L10-S10","level":10,"sublevel":10,"title":"Buka Kitab #10 — Bongkar Semua Fi‘ilnya","conclusion":"Saat membongkar beberapa fi‘il dalam satu petikan, identifikasi masing-masing bentuknya: madhi, mudhari‘, atau amar; siapa persona yang terlibat; dan apakah suaranya aktif atau pasif. Hubungkan semua itu dengan kejadian dalam kalimat, supaya terjemahan tidak kehilangan urutan peristiwa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S01","level":11,"sublevel":1,"title":"Mashdar","conclusion":"Mashdar menamai suatu tindakan atau peristiwa sebagai konsep, bukan menyatakan waktu sebagaimana fi‘il. Kita bisa membicarakan “membaca” sebagai kegiatan tanpa sedang mengatakan siapa membaca kapan. Karena itu, bedakan mashdar dari bentuk kata kerja dan dari isim pelaku yang melakukan kegiatan tersebut. Mashdar menamai **peristiwa sebagai konsep** tanpa menetapkan waktunya, berbeda dari fi‘il; pola mashdar tidak satu macam, jadi bentuknya perlu dikenali dari keluarga akar dan contoh yang sah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S02","level":11,"sublevel":2,"title":"Isim Fa‘il","conclusion":"Isim fa‘il menyebut pelaku tindakan melalui bentuk turunan tertentu, seperti pola فاعل pada contoh triliteral yang sesuai. Ia adalah isim, bukan fi‘il yang membawa waktu. Dalam terjemahan, perhatikan siapa atau apa yang melakukan tindakan; jangan terjebak karena akar yang sama juga muncul pada bentuk lain. Pada fi‘il tsulatsi shahih yang sesuai, isim fa‘il sering berpola **فَاعِلٌ**, misalnya **كَاتِبٌ** dari كتب; ia menunjukkan **pelaku**, tetapi bentuk turunan dari akar non-tsulatsi punya kaidah lain.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S03","level":11,"sublevel":3,"title":"Isim Maf‘ul","conclusion":"Isim maf‘ul menunjuk sesuatu atau seseorang yang dikenai tindakan pada pola yang sesuai, misalnya bentuk مفعول dalam latihan dasar. Arah maknanya berlawanan dengan isim fa‘il: yang melakukan versus yang dikenai. Menentukan keduanya perlu melihat wazan, akar, dan konteks kalimat. Pada contoh tsulatsi shahih biasa, isim maf‘ul sering berpola **مَفْعُولٌ**, seperti **مَكْتُوبٌ**; fokusnya pada **yang menerima perbuatan**, bukan orang yang melakukannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S04","level":11,"sublevel":4,"title":"Shighat Mubalaghah","conclusion":"Shighat mubalaghah dapat menunjukkan makna intensitas atau kebiasaan kuat pada sifat pelaku dalam bentuk tertentu. Namun makna setiap kata tetap ditentukan pemakaian dan konteks, bukan satu tafsir berlebihan dari wazan. Kenali polanya, lalu tanyakan apakah intensitas itu memang masuk akal dalam kalimat yang sedang dibaca. **Shighat mubalaghah** memperkuat atau memperbanyak makna sifat/pelaku dan mempunyai beberapa pola, seperti **فَعَّالٌ**; jangan menganggap semua kata berawalan atau berakhiran serupa pasti bentuk mubalaghah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S05","level":11,"sublevel":5,"title":"Isim Tafdhil","conclusion":"Isim tafdhil dipakai untuk menunjukkan kelebihan atau perbandingan sifat dalam konstruksi tertentu. Jika ada pembanding, kita perlu melihat hubungannya; jika tidak ada, jangan menambah orang atau benda pembanding yang tidak disebut. Bentuk katanya membantu, tetapi susunan kalimat menentukan apakah maknanya komparatif atau dibaca lebih umum. **Isim tafdhil** pada pola dasar tertentu sering terlihat sebagai **أَفْعَلُ**, misalnya **أَكْبَرُ**; fungsinya membandingkan atau menyatakan tingkat lebih, bukan fi‘il madhi.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S06","level":11,"sublevel":6,"title":"Isim Zaman","conclusion":"Isim zaman menyebut waktu berlangsungnya suatu peristiwa, berbeda dari fi‘il yang menyatakan tindakan. Beberapa pola bentuknya dapat mirip dengan isim makan; konteks menentukan apakah yang dimaksud waktu atau tempat. Jangan memutuskan arti hanya dari cetakan katanya tanpa membaca kalimat. **Isim zaman** menunjukkan **kapan** peristiwa berlangsung dan pada contoh tsulatsi tertentu dapat berpola **مَفْعَلٌ/مَفْعِلٌ**; tentukan maknanya dari akar dan konteks.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S07","level":11,"sublevel":7,"title":"Isim Makan","conclusion":"Isim makan menyebut tempat berlangsungnya peristiwa dalam bentuk yang dikenal. Ia dapat berdekatan pola dengan isim zaman, jadi kita perlu bertanya: apakah kalimat ini membicarakan “di mana” atau “kapan”? Jawaban dari konteks itulah yang menolong saat bentuk luar terlihat serupa. **Isim makan** menunjukkan **tempat** terjadinya pekerjaan; pola **مَفْعَلٌ/مَفْعِلٌ** dapat mirip isim zaman, jadi bedakan berdasarkan maksud kalimat, bukan wazan saja.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S08","level":11,"sublevel":8,"title":"Isim Alat","conclusion":"Isim alat menamai benda yang dipakai untuk melakukan tindakan. Kita mengenalinya melalui makna fungsi alat dan, pada kata yang sesuai, petunjuk wazan. Tidak semua nama benda otomatis termasuk isim alat turunan; periksa hubungan antara bentuk, akar, dan kegunaannya dalam kalimat. **Isim alat** menamai **alat** untuk melakukan kegiatan; beberapa pola yang dikenal antara lain **مِفْعَالٌ، مِفْعَلٌ، مِفْعَلَةٌ**, tetapi setiap kosakata tetap perlu dicek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S09","level":11,"sublevel":9,"title":"Menebak Makna dari Bentuk","conclusion":"Bentuk kata memberi dugaan pertama tentang pelaku, objek tindakan, tempat, waktu, atau alat. Tetapi dugaan bukan keputusan akhir. Sesudah melihat wazan, bandingkan akar dan posisi kata, lalu uji apakah makna yang kita pilih cocok dengan keseluruhan kalimat. Untuk menebak turunan, cari **huruf akar**, cocokkan **wazan**, lalu uji fungsinya: **فَاعِل** biasanya pelaku, **مَفْعُول** yang dikenai, **أَفْعَل** tafdhil dalam konteks yang tepat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L11-S10","level":11,"sublevel":10,"title":"Buka Kitab #11 — Satu Akar, Banyak Kata","conclusion":"Satu akar bisa melahirkan mashdar, isim fa‘il, isim maf‘ul, dan bentuk turunan lain yang bekerja berbeda. Saat membaca petikan, jangan berhenti pada “akar katanya sama”. Tentukan fungsi setiap bentuk, siapa pelakunya atau apa hasilnya, lalu bangun terjemahan dari hubungan itu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S01","level":12,"sublevel":1,"title":"Jangan Panik Melihat Satu Paragraf","conclusion":"Saat berhadapan dengan paragraf gundul, kita tidak harus mengenali semua kata sekaligus. Cari dulu dua atau tiga jangkar makna—misalnya fi‘il yang jelas, nama pokok, atau huruf penghubung. Dari titik-titik itu kita bisa membaca arah teks tanpa memaksa harakat pada bagian yang belum cukup buktinya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S02","level":12,"sublevel":2,"title":"Potong Menjadi Unit Makna","conclusion":"Unit makna ialah potongan yang tetap mempertahankan hubungan penting, misalnya fi‘il dengan fa‘il, mudhaf dengan mudhaf ilaih, atau huruf jar dengan isimnya. Memotong paragraf di sembarang spasi bisa merusak maksud. Jadi, bagi bacaan berdasarkan pasangan yang saling membutuhkan, baru gabungkan lagi menjadi kalimat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S03","level":12,"sublevel":3,"title":"Tandai Huruf","conclusion":"Huruf jar dan penghubung sering menjadi papan penunjuk saat teks tanpa harakat terlihat padat. Kita tandai unsur seperti في, من, إلى, atau و, lalu lihat kata atau klausa yang dihubungkannya. Dengan begitu, keterangan tempat, asal, dan perpindahan gagasan tidak tercampur dengan pokok kalimat. Huruf jar seperti **فِي، مِنْ، إِلَى، عَلَى** memberi petunjuk bahwa isim setelahnya **majrur**; penanda seperti **أَنْ، لَمْ** bekerja pada fi‘il mudhari‘, bukan semua kata.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S04","level":12,"sublevel":4,"title":"Tandai Fi‘il","conclusion":"Fi‘il adalah salah satu pintu masuk tercepat untuk memahami paragraf: temukan peristiwanya, lalu periksa siapa yang terkait. Namun pada tulisan gundul, satu rangkaian huruf mungkin punya lebih dari satu vokalisasi. Pastikan petunjuk bentuk dan konteks sebelum mengubah tebakan menjadi kepastian. Dalam paragraf, awalan mudhari‘ **أ/ن/ي/ت** dapat menjadi petunjuk fi‘il, tetapi teks gundul harus tetap diuji dengan susunan dan keluarga bentuknya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S05","level":12,"sublevel":5,"title":"Tandai Isim","conclusion":"Isim dalam paragraf dapat diketahui dari ال, posisi setelah huruf jar, bentuk nama diri, atau tugasnya dalam susunan. Tujuannya bukan sekadar menghitung isim, melainkan mencari siapa, apa, dan bagian mana yang sedang dibicarakan. Tanda yang terlihat harus dibaca bersama hubungan antarkata. Ketika menandai isim, cari **الـ**, kemungkinan **tanwin** pada teks berharakat, kedudukan setelah huruf jar, serta hubungan sebagai mudhaf ilaih atau na‘at.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S06","level":12,"sublevel":6,"title":"Cari Pasangan Susunan","conclusion":"Dalam satu paragraf, kita akan menjumpai idhafah, na‘at–man‘ut, serta pasangan inti kalimat. Cari hubungan kecil dulu agar tidak keliru menyambungkan kata yang jauh. Setelah kelompoknya jelas, kita baru bisa menentukan informasi mana yang menjadi pokok dan mana yang sekadar menerangkan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S07","level":12,"sublevel":7,"title":"Tentukan Posisi","conclusion":"Satu isim bisa berfungsi sebagai mubtada’, khabar, fa‘il, maf‘ul bih, atau bagian majrur. Jenis katanya sama, tetapi tugasnya berbeda-beda. Karena itu, sesudah menandai isim, lanjutkan dengan pertanyaan: “Dalam kalimat ini dia sedang bekerja sebagai apa?” Jawabannya menentukan i‘rab dan terjemahan. Sebelum memberi harakat, pisahkan **fa‘il marfu‘**, **maf‘ul bih manshub**, **isim sesudah jar majrur**, dan **mudhari‘ yang mungkin terkena nashib/jazim**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S08","level":12,"sublevel":8,"title":"Beri Harakat Akhir","conclusion":"Harakat akhir pada isim mufrad biasa ditentukan dari fungsi yang dapat dibuktikan, bukan dari kebiasaan melihat dhammah atau fathah. Jika kata menjadi fa‘il, mubtada’, objek, atau isim majrur, kita periksa statusnya lalu pilih tanda yang tepat. Bagian yang masih ambigu sebaiknya ditunda daripada diisi asal. Pemeriksaan ujung kata perlu empat status: **rafa‘, nashab, jar, jazm**; kemudian cocokkan apakah tandanya dhammah, fathah, kasrah, sukun atau penggantinya sesuai bentuk.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S09","level":12,"sublevel":9,"title":"Susun Terjemahan Alami","conclusion":"Terjemahan alami lahir setelah struktur Arabnya terbaca, bukan saat tiap kata dipindahkan dalam urutan yang sama. Cari peristiwa, pelaku, objek, dan keterangan; kemudian susun menjadi kalimat Indonesia yang wajar tanpa kehilangan pembatas atau hubungan penting. Kesetiaan pada makna berbeda dari kaku mengikuti urutan kata.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L12-S10","level":12,"sublevel":10,"title":"Buka Kitab #12 — Satu Paragraf Utuh","conclusion":"Membuka satu paragraf utuh membutuhkan kebiasaan yang saling menyambung: cari jangkar makna, potong unit, tandai jenis kata, tentukan hubungan, baru beri harakat dan terjemahkan. Setiap keputusan perlu alasan. Kalau ada bagian yang belum pasti, catat masalahnya sambil tetap menjaga garis besar isi bacaan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S01","level":13,"sublevel":1,"title":"Maqshur","conclusion":"Isim maqshur berakhir dengan alif lazimah, sehingga tanda i‘rabnya tidak tampak seperti pada isim biasa. Walau akhir katanya terdengar tetap, posisinya bisa rafa‘, nashab, atau jar menurut fungsi kalimat. Karena itu, kita menentukan statusnya dari susunan terlebih dahulu, lalu memahami bahwa tanda i‘rabnya diperkirakan, bukan tertulis jelas. **Isim maqshur** berakhir dengan **alif lazim**, seperti **الْفَتَى**; tanda rafa‘, nashab, dan jar pada bentuk mu‘rab ini **diperkirakan (muqaddarah)**, bukan terlihat di atas alif.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S02","level":13,"sublevel":2,"title":"Manqush","conclusion":"Isim manqush berakhir dengan ya’ lazimah yang didahului kasrah, seperti pada bentuk yang dipelajari. Dalam keadaan tertentu, ya’ pada nakirah dapat hilang secara tulisan pada rafa‘ dan jar, sedangkan bentuk ma‘rifah memiliki pola penulisan lain. Untuk membacanya, lihat apakah isim itu nakirah atau ma‘rifah serta apa kedudukannya dalam kalimat. **Isim manqush** berakhir **ya lazim yang didahului kasrah**, seperti **الْقَاضِي**; dhammah dan kasrah biasanya **diperkirakan**, sedangkan fathah nashab dapat **tampak** pada bentuk yang tepat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S03","level":13,"sublevel":3,"title":"Mamdud","conclusion":"Isim mamdud berakhir dengan hamzah setelah alif tambahan, berbeda dari maqshur dan manqush. Pada bentuk yang dapat dii‘rabkan, tanda akhir tertentu bisa tampak pada hamzah. Jangan menganggap semua kata yang diakhiri alif atau hamzah memiliki aturan sama; cek bentuk isim serta posisinya sebelum memberi tanda. **Isim mamdud** memiliki akhir **hamzah sesudah alif tambahan**, misalnya **سَمَاءٌ**; perhatikan jenis hamzah dan bentuk katanya sebelum menetapkan tanda i‘rab, jangan mengira semua akhir alif-hamzah sama hukumnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S04","level":13,"sublevel":4,"title":"Ghairu Munsharif","conclusion":"Ghairu munsharif pada contoh yang dipelajari dapat berjar dengan fathah sebagai pengganti kasrah jika tidak memakai ال dan tidak menjadi mudhaf. Namun ketika masuk kondisi yang membolehkan kasrah, tandanya berubah. Jadi, untuk membaca jamak berpola tertentu, kita periksa dulu jenis isimnya, lalu ada tidaknya ال atau hubungan idhafah. **Ghairu munsharif** umumnya tidak bertanwin dan dalam kondisi tertentu **jar-nya bertanda fathah**, bukan kasrah; saat ber-**الـ** atau menjadi **mudhaf**, kaidah jar kembali berbeda sesuai ketentuannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S05","level":13,"sublevel":5,"title":"Isim Mabni","conclusion":"Isim mabni adalah isim yang bentuk akhirnya tetap, meskipun ia bisa menempati posisi yang secara gramatikal rafa‘, nashab, atau jar. Dhamir dan sebagian kata penunjuk menjadi contoh penting. Kita harus membedakan “akhir katanya berubah” dengan “kedudukannya berubah”; pada yang mabni, i‘rab dipahami melalui posisi, bukan pergantian vokal akhir. **Isim mabni** menjaga bentuk akhir yang tetap ketika fungsi berubah; analisisnya memakai istilah **fi mahalli rafa‘/nashab/jar**, bukan menuntut harakat akhir berubah seperti isim mu‘rab.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S06","level":13,"sublevel":6,"title":"Dhamir","conclusion":"Dhamir ialah kata ganti yang merujuk orang atau sesuatu yang sudah dikenali konteksnya. Ada dhamir terpisah dan ada yang menempel pada fi‘il, isim, atau huruf. Untuk memahami petikan, tanyakan siapa rujukannya dan apa tugasnya: pelaku, objek, atau pemilik. Jangan menebak rujukan jika ada dua kandidat yang sama-sama mungkin. Dhamir seperti **هُوَ، هُ، هِمْ** adalah bentuk-bentuk kata ganti dengan tugas berbeda; banyak yang **mabni**, sehingga cari kedudukannya dari hubungan kalimat, bukan mengubah harakat secara paksa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S07","level":13,"sublevel":7,"title":"Isim Isyarah","conclusion":"Isim isyarah dipakai untuk menunjuk sesuatu, seperti هذا dan هذه pada contoh dasar. Bentuknya menyesuaikan kategori yang ditunjuk, dan pilihan dekat atau jauh bisa mengubah nuansa makna. Saat membaca, cari benda atau orang yang ditunjuk sekaligus fungsi kata tunjuk itu dalam kalimat; jangan menerjemahkannya sendirian tanpa acuannya. Isim isyarah seperti **هَذَا** dan **هَذِهِ** lazimnya **mabni**; beberapa bentuk untuk mutsanna berbeda perilakunya, jadi cek jenis penunjuk, jumlah, serta posisinya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S08","level":13,"sublevel":8,"title":"Isim Maushul","conclusion":"Isim maushul seperti الذي atau التي menghubungkan suatu isim dengan kalimat penjelas yang disebut shilah. Shilah diperlukan agar maksud maushul lengkap dan sering memuat hubungan kembali kepada acuannya. Dalam petikan panjang, baca maushul bersama shilah lebih dahulu sebelum menentukan berita utama, supaya penjelasan tidak tertukar dengan inti kalimat. Isim maushul seperti **الَّذِي، الَّتِي** memperkenalkan **shilah** penjelas dan umumnya mabni dalam bentuk yang dipelajari; jangan memisahkan kata penghubung dari klausa yang menerangkan acuannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S09","level":13,"sublevel":9,"title":"I‘rab yang Tidak Kelihatan","conclusion":"Tidak semua i‘rab tampak sebagai harakat yang bisa kita lihat. Ada tanda yang tampak, ada yang diperkirakan pada bentuk khusus, dan ada kata mabni yang hanya memiliki posisi i‘rab. Saat menemukan akhir kata yang tidak berubah, jangan otomatis menyebutnya tanpa fungsi; cari dulu peran dan bentuk katanya. Ketika akhir kata tidak memperlihatkan harakat i‘rab, bedakan **muqaddarah** pada maqshur/manqush tertentu dari **mahal i‘rab** pada kata mabni; fungsi gramatikalnya tetap harus ditemukan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L13-S10","level":13,"sublevel":10,"title":"Buka Kitab #13 — Jangan Ketipu Bentuk Isim","conclusion":"Dalam kitab, isim maqshur, manqush, mamdud, ghairu munsharif, dan mabni bisa muncul berdampingan. Bentuk lahirnya tidak cukup untuk memutuskan fungsi. Baca susunan kalimat, temukan hubungannya, lalu pilih apakah tanda i‘rab tampak, diperkirakan, atau hanya dinyatakan pada posisinya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S01","level":14,"sublevel":1,"title":"Konsep ‘Amil","conclusion":"‘Amil ialah unsur atau sebab gramatikal yang memengaruhi i‘rab bagian lain dalam susunan. Kadang pengaruhnya datang dari huruf, fi‘il, atau konstruksi tertentu. Saat melihat satu harakat akhir, jangan berhenti pada bunyinya: cari apa yang membuat kata itu berstatus demikian, baru terjemahkan hubungan yang dibentuknya. ‘Amil adalah pemicu perubahan **status i‘rab**: huruf jar memajurkan isim, **إِنَّ** menashabkan isimnya, dan **لَمْ** menjazmkan mudhari‘ dalam konstruksi yang tepat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S02","level":14,"sublevel":2,"title":"إِنَّ dan Saudara-Saudaranya","conclusion":"إِنَّ dan saudara-saudaranya masuk pada jumlah ismiyah lalu memengaruhi kedudukan unsur-unsurnya: isimnya manshub dan khabarnya marfu‘ dalam pola dasar. Selain perubahan i‘rab, partikel itu memberi nuansa makna tertentu. Ketika membaca, temukan dulu kata yang dipengaruhi dan berita yang masih berkaitan dengannya. Setelah **إِنَّ**, pada pola dasar **isim إِنَّ manshub** dan **khabarnya marfu‘**; kata tunggal biasa bisa terbaca **إِنَّ الطَّالِبَ مُجْتَهِدٌ** (fathah lalu dhammah).","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S03","level":14,"sublevel":3,"title":"كَانَ dan Saudara-Saudaranya","conclusion":"كَانَ dan saudara-saudaranya mengubah susunan jumlah ismiyah: isimnya tetap marfu‘, sedangkan khabarnya menjadi manshub dalam pola dasar. Kata kerjanya juga dapat membawa nuansa waktu atau keadaan. Untuk menganalisisnya, jangan menukar kedua unsur hanya karena setelah كان ada dua isim berdekatan. Pada **كَانَ** dan saudara-saudaranya, **isimnya marfu‘** sedangkan **khabarnya manshub**, kebalikan status dua unsur setelah **إِنَّ**; misalnya **كَانَ الْجَوُّ جَمِيلًا**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S04","level":14,"sublevel":4,"title":"لا النافية للجنس","conclusion":"لا النافية للجنس dipakai untuk meniadakan suatu jenis secara umum pada konstruksi tertentu. Ini berbeda dari لا الناهية yang melarang perbuatan dan لا النافية biasa yang menafikan. Kita membedakannya melalui kata yang mengikutinya, struktur kalimat, dan maksud penafiannya, bukan hanya melihat tulisan لا. Dalam bentuk dasar **لَا النَّافِيَةِ لِلْجِنْسِ**, isim **لا** yang mufrad nakirah dan bukan mudhaf/syibhul-mudhaf biasanya **mabni atas fathah di tempat nashab**, seperti **لَا كِتَابَ**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S05","level":14,"sublevel":5,"title":"Huruf Nashab Mudhari‘","conclusion":"Partikel seperti أَنْ, لَنْ, dan كَيْ dapat menashabkan fi‘il mudhari‘ pada susunan yang sesuai. Makna yang ditambahkan bisa berupa hubungan peristiwa, penafian masa depan, atau tujuan. Sebelum membaca akhirnya, pastikan benar ada mudhari‘ yang dipengaruhi partikel tersebut, bukan isim biasa. Fi‘il mudhari‘ shahih akhir setelah nashib seperti **أَنْ، لَنْ، كَيْ** dapat menjadi **manshub dengan fathah**, misalnya **لَنْ يَكْتُبَ**; bentuk tertentu memiliki tanda pengganti.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S06","level":14,"sublevel":6,"title":"Huruf Jazm","conclusion":"Huruf jazm seperti لَمْ dan لَمَّا, serta perangkat larangan dan lam perintah dalam pola yang dipelajari, memengaruhi akhir mudhari‘. Tanda jazm bergantung pada bentuk fi‘ilnya. Jadi, saat menjumpai لم يكتب, kita cari fi‘il mudhari‘ dan pengaruh partikel, lalu tentukan tanda yang benar. Fi‘il mudhari‘ shahih akhir setelah **لَمْ** menjadi **majzum dengan sukun**, contohnya **لَمْ يَكْتُبْ**; pada mu‘tal akhir ada penghilangan huruf ‘illat, dan pada af‘al khamsah penghilangan nun.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S07","level":14,"sublevel":7,"title":"Perangkat Syarat","conclusion":"Perangkat syarat mengikat dua bagian: peristiwa yang menjadi syarat dan jawaban atau hasilnya. Pada pola jazim, pengaruhnya dapat terlihat pada kedua fi‘il mudhari‘ yang terkait. Untuk menerjemahkan, identifikasi lebih dulu apa syaratnya dan apa konsekuensinya, baru tentukan batas pengaruh gramatikal. Dalam syarat jazim, fi‘il syarat dan jawab syarat bisa **majzum** sesuai ketentuan, tetapi tanda yang tampak bergantung pada bentuk fi‘il, bukan hanya ada tidaknya perangkat syarat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S08","level":14,"sublevel":8,"title":"Fi‘il Thalab","conclusion":"Fi‘il thalab menyatakan tuntutan, seperti perintah atau larangan, tetapi bentuk gramatikalnya tidak selalu sama. Fi‘il amar sendiri bisa mabni, sedangkan mudhari‘ yang menjadi jawab permintaan dapat majzum dalam syarat tertentu. Pembedaan ini penting agar kita tidak menyebut semua kata setelah perintah memiliki hukum akhir yang sama. **Amar** biasanya dibangun sebagai fi‘il **mabni**, sedangkan mudhari‘ yang menjadi jawab thalab dalam konstruksi tertentu dapat **majzum**; jangan menyamakan dua hukum akhir itu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S09","level":14,"sublevel":9,"title":"Berburu ‘Amil Sebelum Menentukan Harakat","conclusion":"Saat memilih harakat, cari ‘amil sebelum menamai hasil i‘rab. Perhatikan apakah yang bekerja huruf nashab, huruf jazm, كان, إن, atau konstruksi lain. Setelah unsur yang dipengaruhi ditemukan, tentukan status dan tanda sesuai kelas katanya; urutan ini mencegah kita menjadikan harakat sebagai tebakan. Saat melihat akhir **ـُ، ـَ، ـِ، ـْ**, jangan mulai dari bunyinya; tentukan **‘amil**, status (rafa‘/nashab/jar/jazm), dan jenis bentuk kata agar harakatnya dapat dipertanggungjawabkan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L14-S10","level":14,"sublevel":10,"title":"Buka Kitab #14 — Cari Dalangnya","conclusion":"Dalam dua klausa atau lebih, satu ‘amil tidak boleh sembarang dianggap memengaruhi seluruh paragraf. Tentukan batas pengaruhnya dan kata mana yang benar-benar terkait. Analisis yang baik menjelaskan penyebab perubahan i‘rab di tiap bagian sambil tetap menjaga makna utuh bacaan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S01","level":15,"sublevel":1,"title":"Na‘at Lanjutan","conclusion":"Na‘at lanjutan mengajak kita melihat bagaimana sifat mengikuti man‘ut ketika fungsi, jenis, atau jumlahnya berubah. Dalam contoh yang sesuai, kecocokan itu dibuktikan dari pasangan katanya, bukan dari terjemahan semata. Sebelum memberi harakat sifat, pastikan dulu isim mana yang sedang diterangkannya. Na‘at lanjutan tetap perlu diuji terhadap **man‘ut**: kesesuaian i‘rab, ma‘rifah, jenis, dan jumlah berlaku untuk na‘at hakiki biasa; sifat sababiyah punya ketentuan tersendiri.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S02","level":15,"sublevel":2,"title":"‘Athaf","conclusion":"‘Athaf menghubungkan unsur melalui huruf penghubung seperti و atau bentuk lain yang dipelajari. Ma‘thuf mengikuti kedudukan unsur yang diikuti dalam hubungan i‘rab yang sesuai. Saat membaca, tentukan apa yang benar-benar disambungkan—kata dengan kata atau klausa dengan klausa—agar terjemahannya tidak mengubah hubungan makna. Pada **‘athaf** yang mengikuti i‘rab, ma‘thuf mengikuti **rafa‘/nashab/jar** unsur acuannya; tentukan dulu kata mana yang di-‘athaf-kan sebelum memilih tanda akhir.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S03","level":15,"sublevel":3,"title":"Taukid","conclusion":"Taukid memberi penegasan terhadap unsur sebelumnya. Pada taukid maknawi, kata penegas seperti نفس atau كل dalam konstruksi yang tepat mengikuti status gramatikal bagian yang ditegaskannya. Kunci membacanya adalah mencari siapa atau apa yang ditegaskan, lalu memastikan bentuk penegasnya sesuai. **Taukid** yang mengikuti unsur sebelumnya memakai status i‘rab pengikutnya pada konstruksi yang sesuai; periksa kata penegas seperti **نَفْس** atau **كُلّ** beserta dhamir yang menyertainya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S04","level":15,"sublevel":4,"title":"Badal","conclusion":"Badal adalah unsur pengganti atau penjelas yang mengikuti unsur sebelumnya dalam konstruksi tertentu. Badal sebagian menunjuk bagian dari sesuatu, sedangkan badal isytimal menyebut hal yang berkaitan dengannya tanpa menjadi bagian fisik. Untuk membedakannya, lihat makna hubungan dan penanda seperti dhamir, bukan hanya urutan dua isim. **Badal** dapat mengikuti i‘rab unsur sebelumnya; bedakan badal keseluruhan, sebagian, dan isytimal melalui hubungan makna, bukan hanya kesamaan bunyi akhir.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S05","level":15,"sublevel":5,"title":"Hal","conclusion":"Hal menerangkan keadaan seseorang atau sesuatu ketika peristiwa berlangsung. Ia berbeda dari na‘at yang menjadi sifat isim dalam frasa biasa. Pada contoh dasar, hal sering manshub dan menjawab “dalam keadaan bagaimana?”. Cari dulu pemilik keadaan serta fi‘ilnya supaya keterangan itu tidak tertukar dengan objek atau sifat tetap. **Hal** dalam pola dasar sering berupa isim **nakirah manshub**, misalnya datang **مُسْرِعًا**; bedakan dari **na‘at** yang mengikuti man‘ut dan bisa marfu‘/manshub/majrur.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S06","level":15,"sublevel":6,"title":"Tamyiz","conclusion":"Tamyiz menjelaskan sesuatu yang masih samar dalam bilangan, ukuran, perbandingan, atau ungkapan tertentu. Kita membutuhkannya ketika angka atau kadar belum menjawab “apa yang dihitung atau diukur?”. Periksa konstruksinya, sebab bentuk dan i‘rab tamyiz tidak bisa ditetapkan hanya dengan melihat satu kata tanpa konteks. Untuk **tamyiz bilangan 11–99** pada contoh dasar, bentuknya sering **mufrad manshub** seperti **عِشْرُونَ كِتَابًا**; aturan bilangan 3–10 berbeda dan tidak boleh disamakan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S07","level":15,"sublevel":7,"title":"Zharaf","conclusion":"Zharaf memberi keterangan waktu atau tempat terjadinya peristiwa. Zharaf zaman menjawab “kapan?”, sedangkan zharaf makan menjawab “di mana?”. Sebagian zharaf juga menjadi mudhaf dan diikuti mudhaf ilaih. Kita perlu membaca keseluruhan kelompoknya agar keterangan tempat tidak keliru dianggap objek langsung. **Zharaf** keterangan waktu/tempat lazimnya **manshub** pada konstruksi yang dibahas, tetapi bisa menjadi mudhaf sehingga isim sesudahnya **majrur**; selalu periksa fungsi keseluruhan frasa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S08","level":15,"sublevel":8,"title":"Maf‘ul Muthlaq","conclusion":"Maf‘ul muthlaq adalah mashdar yang berkaitan dengan fi‘ilnya dan dipakai, antara lain, untuk menegaskan, menyebut jenis, atau jumlah tindakan. Kuncinya mencari hubungan antara peristiwa dan mashdarnya. Jangan mencap setiap mashdar yang muncul setelah fi‘il sebagai maf‘ul muthlaq sebelum memeriksa fungsi kalimat. **Maf‘ul muthlaq** lazimnya mashdar **manshub** yang seakar atau berhubungan dengan fi‘il, misalnya untuk menguatkan atau menjelaskan cara tindakan; bentuknya harus dibuktikan dari hubungan peristiwa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S09","level":15,"sublevel":9,"title":"Maf‘ul Li Ajlih dan Maf‘ul Ma‘ah","conclusion":"Maf‘ul li ajlih menjelaskan alasan atau tujuan suatu tindakan dalam konstruksi yang tepat, sedangkan maf‘ul ma‘ah menunjukkan penyertaan melalui waw ma‘iyyah. Pertanyaan yang diajukan berbeda: “mengapa dilakukan?” dan “bersama apa berlangsung?”. Perhatikan makna serta syarat bentuknya agar tidak semua waw dianggap ‘athaf. **Maf‘ul li ajlih** menerangkan **alasan/tujuan**, sedangkan **maf‘ul ma‘ah** menyatakan **penyertaan setelah waw ma‘iyyah**; pada pola dasar yang memenuhi syarat, keduanya berstatus **manshub**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L15-S10","level":15,"sublevel":10,"title":"Buka Kitab #15 — Siapa Mengikuti Siapa?","conclusion":"Saat membuka paragraf yang lebih padat, na‘at, ‘athaf, taukid, badal, hal, tamyiz, zharaf, dan berbagai maf‘ul bisa muncul berdekatan. Kerjakan satu hubungan per satu hubungan: siapa yang mengikuti, siapa yang menerangkan keadaan, mana alasan, mana waktu. Setelah peta fungsi selesai, barulah harakat dan terjemahan masuk dengan alasan yang dapat diuji.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S01","level":16,"sublevel":1,"title":"Mujarrad","conclusion":"Fi‘il mujarrad memakai huruf-huruf asli tanpa tambahan pembentuk wazan pada bentuk yang sedang dianalisis. Untuk fi‘il tsulatsi mujarrad, akar dasarnya terdiri dari tiga huruf. Jangan menilai hanya dari panjang tulisan: kita perlu membedakan huruf akar dari huruf yang datang karena perubahan tashrif. Pada **tsulatsi mujarrad**, pola asal fi‘il memakai **tiga huruf akar** tanpa tambahan pembentuk wazan; bentuk madhi seperti **كَتَبَ** dapat dibandingkan dengan timbangan **فَعَلَ**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S02","level":16,"sublevel":2,"title":"Mazid","conclusion":"Fi‘il mazid dibentuk dengan tambahan unsur dalam pola tertentu di atas huruf aslinya. Tambahan itu bisa memengaruhi makna atau hubungan tindakan, tetapi tidak semuanya dapat ditebak seragam. Cara mengenalinya ialah membandingkan bentuk dengan akar dan wazan yang sudah diketahui, bukan sekadar menghitung jumlah karakter. **Mazid** mempunyai huruf tambahan pada pola pembentukan, misalnya pola **أَفْعَلَ** atau **فَعَّلَ**; tambahan bentuk dapat memengaruhi makna, tetapi tidak selalu menghasilkan satu arti tetap.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S03","level":16,"sublevel":3,"title":"Makna Tambahan Wazan","conclusion":"Tambahan wazan dapat memberi arah makna seperti membuat, meminta, saling melakukan, atau nuansa lain pada kata tertentu. Namun satu pola tidak selalu mempunyai satu arti Indonesia yang kaku. Selalu bandingkan fi‘il dasar dan turunannya dalam kalimat; konteks menjadi penentu apakah dugaan dari wazan memang tepat. Perubahan pola **فَعَلَ → فَعَّلَ/أَفْعَلَ/اِسْتَفْعَلَ** dapat menyertai pergeseran makna; pastikan akar dan kamusnya sebelum mengartikan semua pola sebagai kaidah mutlak.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S04","level":16,"sublevel":4,"title":"Shahih","conclusion":"Fi‘il shahih adalah fi‘il yang huruf asalnya tidak mengandung huruf ‘illat. Dalam pembagian yang dipelajari ada shahih salim, mahmuz yang memuat hamzah asli, dan mudha‘‘af yang memiliki penggandaan huruf asli. Memastikan huruf asal penting agar kita tidak keliru menganggap tanda tambahan sebagai bagian akar. Jenis **shahih** ditentukan dari **akar tanpa huruf ‘illat**; kenali pula **salim**, **mahmuz** yang mengandung hamzah asli, dan **mudha‘‘af** yang mempunyai penggandaan huruf asal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S05","level":16,"sublevel":5,"title":"Mu‘tal","conclusion":"Fi‘il mu‘tal mengandung huruf ‘illat—waw atau ya’ pada akar, dengan perubahan bentuk yang dapat melibatkan alif dalam penulisannya. Jenisnya dibedakan menurut letak huruf tersebut. Saat membaca teks gundul, bentuk permukaan belum tentu memperlihatkan akarnya secara utuh; pasangan tashrif membantu menyingkapnya. Jenis **mu‘tal** dilacak dari huruf **و/ي** pada akar yang dapat tampil berubah; kategorinya **mitsal** (awal), **ajwaf** (tengah), dan **naqish** (akhir).","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S06","level":16,"sublevel":6,"title":"Mitsal","conclusion":"Mitsal adalah fi‘il mu‘tal yang huruf ‘illatnya berada di awal akar. Pada beberapa contoh mitsal wawi, waw dapat hilang dalam bentuk mudhari‘ tertentu. Karena itu, jika bentuk sekarang terlihat lebih pendek, bandingkan dengan madhi dan akar yang diketahui sebelum menyimpulkan bahwa huruf pertamanya memang tidak ada. Mitsal berarti huruf ‘illat di **awal akar**; pada sebagian **mitsal wawi** bentuk mudhari‘ dapat menghilangkan waw, seperti hubungan **وَعَدَ → يَعِدُ**.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S07","level":16,"sublevel":7,"title":"Ajwaf","conclusion":"Ajwaf memiliki huruf ‘illat di tengah akar. Ketika ditashrif, bagian tengahnya dapat berubah bentuk, seperti terlihat saat membandingkan madhi dan mudhari‘ yang bersumber dari akar sama. Kita perlu mengenali perubahan itu agar tidak mengira dua bentuknya berasal dari kata yang sama sekali berbeda. Ajwaf mempunyai huruf ‘illat di **tengah akar**; misalnya keluarga **قَالَ → يَقُولُ**, yang memperlihatkan perubahan wujud huruf tengah menurut tashrif.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S08","level":16,"sublevel":8,"title":"Naqish","conclusion":"Naqish adalah fi‘il mu‘tal dengan huruf ‘illat di akhir akar. Akhir katanya bisa berubah atau tidak tampak secara sama pada madhi dan mudhari‘ tertentu. Untuk membaca dengan benar, periksa pasangan bentuk dan posisi huruf terakhir, bukan hanya menilai bunyi yang terlihat dalam satu petikan. Naqish memiliki huruf ‘illat pada **akhir akar**; perubahan akhir pada bentuk seperti **دَعَا → يَدْعُو** perlu diperiksa sebelum menetapkan harakat dan huruf yang “hilang”.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S09","level":16,"sublevel":9,"title":"Membongkar Fi‘il Mu‘tal dalam Kitab","conclusion":"Fi‘il mu‘tal dalam kitab bisa memperlihatkan perubahan awal, tengah, atau akhir yang membuat akar tersembunyi. Cari hubungan antara bentuk madhi, mudhari‘, dan konteksnya, lalu tentukan apakah kata itu mitsal, ajwaf, atau naqish. Jangan menambahkan huruf atau harakat yang tidak didukung bukti. Saat menemukan fi‘il mu‘tal gundul, tentukan letak ‘illatnya: **awal = mitsal, tengah = ajwaf, akhir = naqish**; bandingkan bentuk madhi–mudhari‘ untuk memilih bacaan yang masuk akal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L16-S10","level":16,"sublevel":10,"title":"Buka Kitab #16 — Jangan Terkecoh Bentuk Fi‘il","conclusion":"Membaca fi‘il yang tampak rumit menjadi lebih mudah jika kita menanyakan tiga hal: mana huruf asli, adakah tambahan wazan, dan apakah akarnya shahih atau mu‘tal. Baru setelah itu kita menentukan bentuk serta maknanya. Cara ini lebih aman daripada mengandalkan kemiripan rupa satu kata dengan kata lain.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S01","level":17,"sublevel":1,"title":"Pecah Kalimat Panjang","conclusion":"Kalimat Arab yang panjang sering menyimpan beberapa peristiwa dalam satu rangkaian. Pisahkan klausa tanpa memutus fi‘il dari pelaku, objek, atau frasa jar yang masih bergantung padanya. Setelah setiap bagian utuh, barulah kita sambungkan kembali urutan peristiwanya agar makna tidak terpotong.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S02","level":17,"sublevel":2,"title":"Jumlah di Dalam Jumlah","conclusion":"Sebuah jumlah bisa berada di dalam jumlah lain dan menjalankan fungsi tertentu, misalnya menjadi khabar bagi mubtada’ utama. Karena itu, cari kerangka besar dulu sebelum menyelami kalimat kecil di dalamnya. Kalau kita menukar berita utama dengan penjelasan sisipan, terjemahan akan kehilangan pokok pembicaraannya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S03","level":17,"sublevel":3,"title":"Isim Maushul dan Shilah","conclusion":"Isim maushul memperkenalkan penjelasan berupa shilah yang menyempurnakan acuannya. Bacalah maushul dan shilah sebagai satu kesatuan sebelum mencari fungsi berikutnya dalam kalimat utama. Dengan begitu, keterangan “yang...” tidak terseret menjadi khabar atau peristiwa terpisah secara keliru. Isim maushul seperti **الَّذِي** biasanya diikuti **shilah** yang menerangkan acuannya; banyak bentuknya **mabni**, jadi peran i‘rabnya dibaca dari posisi keseluruhan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S04","level":17,"sublevel":4,"title":"Dhamir dan Rujukannya","conclusion":"Dhamir adalah kata ganti yang perlu dihubungkan kepada rujukannya, atau marji‘. Dalam klausa panjang, rujukan itu bisa berada beberapa kata sebelumnya. Gunakan kecocokan bentuk, urutan informasi, dan kewajaran makna; kalau ada lebih dari satu kandidat yang masuk akal, jangan mengaku pasti sebelum konteks cukup.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S05","level":17,"sublevel":5,"title":"Syarat–Jawab","conclusion":"Struktur syarat–jawab menyatakan hubungan “jika ... maka ...” atau bentuk lain yang setara. Tentukan di mana syarat berakhir dan jawaban dimulai; pada perangkat tertentu, tanda jazm ikut menjadi bukti. Terjemahan baru tepat jika hasilnya tetap bergantung pada syarat, bukan dibaca sebagai kejadian yang lepas. Dalam susunan syarat, bedakan **alat syarat**, **fi‘il syarat**, dan **jawabnya**; bila alat syaratnya jazim dan fi‘ilnya mudhari‘, tanda jazm perlu diperiksa pada kedua bagian sesuai ketentuan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S06","level":17,"sublevel":6,"title":"Sebab–Akibat","conclusion":"Sebab dan akibat perlu dibedakan berdasarkan fungsi klausa, bukan karena selalu muncul pada urutan yang sama. Partikel seperti لأن atau fa dalam konteks tertentu membantu melihat apakah satu bagian menjelaskan alasan atau hasil. Saat meringkas, jangan sampai kita menyatakan akibat sebagai penyebabnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S07","level":17,"sublevel":7,"title":"‘Athaf Antarklausa","conclusion":"‘Athaf dapat menghubungkan bukan cuma kata, tetapi juga dua klausa lengkap. Huruf penghubung bisa mengisyaratkan penggabungan, urutan, atau kedekatan peristiwa sesuai bentuk dan konteks. Untuk membacanya, pastikan bagian mana yang disambung dan apakah waktunya memang berurutan atau hanya ditempatkan berdampingan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S08","level":17,"sublevel":8,"title":"Jumlah I‘tiradhiyyah","conclusion":"Jumlah i‘tiradhiyyah adalah kalimat sisipan yang menyela susunan utama untuk memberi keterangan tambahan. Cara mengenalinya ialah mencoba mengangkat sisipan itu sementara: jika kerangka utama tetap bisa dibaca, batas sisipannya menjadi lebih jelas. Jangan jadikan sisipan sebagai inti pernyataan hanya karena kalimatnya panjang.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S09","level":17,"sublevel":9,"title":"Menentukan Batas Makna","conclusion":"Batas makna pada paragraf panjang tidak selalu sama dengan titik atau spasi. Cari penanda maushul, waktu, sebab, syarat, dan penghubung antarklausa, lalu kelompokkan informasi yang saling bergantung. Tiga unit yang tepat akan lebih membantu daripada sepuluh potongan asal pendek.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L17-S10","level":17,"sublevel":10,"title":"Buka Kitab #17 — Bedah Kalimat Panjang","conclusion":"Untuk membuka kalimat panjang, temukan peristiwa utama lebih dulu, kemudian pasangkan klausa penjelas, shilah, dhamir, syarat, serta hubungan sebab-akibatnya. Jangan menerjemahkan setiap penggalan sebagai kalimat baru tanpa menyambungkannya. Peta struktur membuat bacaan panjang terasa sebagai satu cerita yang utuh.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S01","level":18,"sublevel":1,"title":"Kosakata Khas Fikih","conclusion":"Istilah fikih seperti syarat, rukun, sah, dan batal berfungsi sebagai kategori dalam pembahasan hukum, bukan keputusan yang boleh kita tebak dari satu kata. Saat membaca petikan, kenali apakah penulis sedang mendefinisikan istilah, membagi perkara, atau menerapkan hukum pada kasus tertentu. Memahami struktur bahasa tidak otomatis berarti kita sudah menetapkan fatwa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S02","level":18,"sublevel":2,"title":"Definisi","conclusion":"Definisi mempertemukan istilah dengan penjelasan batas maknanya. Di kitab, bentuk kalimat definisi sering singkat, tetapi satu frasa pembatas dapat mengubah cakupannya. Saat menerjemahkan, tandai apa yang sedang didefinisikan, ciri yang dimasukkan, dan bagian yang justru dikecualikan agar makna istilah tidak melebar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S03","level":18,"sublevel":3,"title":"Syarat","conclusion":"Syarat adalah ketentuan yang menjadi prasyarat bagi sesuatu dalam uraian fikih, tetapi berbeda dari rukun yang menjadi bagian pembentuknya. Dalam teks, cari kata yang menunjukkan keharusan kondisi sebelum atau di luar tindakan pokok. Jangan menukar daftar syarat dengan daftar rukun hanya karena keduanya sama-sama penting.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S04","level":18,"sublevel":4,"title":"Rukun","conclusion":"Rukun merupakan bagian pokok dalam suatu susunan ibadah atau tindakan menurut pembahasan yang sedang dikutip. Untuk mengenalinya di kitab, perhatikan bagaimana penulis menyebut unsur penyusun, bukan keadaan pendukung di luarnya. Pembedaan rukun dan syarat harus tetap mengikuti redaksi teks, bukan disimpulkan dari hafalan terpisah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S05","level":18,"sublevel":5,"title":"Hukum","conclusion":"Saat kitab membahas hukum, satu paragraf bisa berisi putusan, alasan, dalil, dan pembatas penerapan. Pisahkan fungsi masing-masing kalimat agar kita tidak mengutip satu putusan seolah berlaku untuk semua keadaan. Membaca akurat berarti tahu apa yang ditegaskan teks dan apa yang belum dibahasnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S06","level":18,"sublevel":6,"title":"Pengecualian","conclusion":"Pengecualian membatasi pernyataan sebelumnya. Kata seperti إلا dalam konstruksi yang sesuai dapat mengubah cakupan sebuah kaidah dari umum menjadi khusus. Jadi, jangan berhenti menerjemahkan sebelum menemukan bagian yang dikecualikan; satu pengecualian yang terlewat bisa membalik kesimpulan pembaca.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S07","level":18,"sublevel":7,"title":"Pembagian","conclusion":"Pembagian atau klasifikasi membantu penulis merinci satu perkara menjadi beberapa jenis. Saat membaca daftar, temukan istilah induknya, lalu hubungkan tiap bagian kepada induk yang sama. Jangan mengira tiap butir adalah hukum baru yang berdiri sendiri bila sebenarnya hanya cabang dari satu pembahasan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S08","level":18,"sublevel":8,"title":"Struktur “Jika… maka…”","conclusion":"Struktur “jika ... maka ...” menghubungkan suatu keadaan dengan hasil atau ketentuan yang mengikutinya. Tugas kita menemukan klausa kondisi dan jawaban secara tepat. Kalau syaratnya terpotong, terjemahan dapat terdengar seperti keputusan mutlak padahal teks menyatakannya bersyarat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S09","level":18,"sublevel":9,"title":"Membaca Paragraf Fikih","conclusion":"Sebuah paragraf fikih bisa bergerak dari definisi menuju syarat, rukun, hukum, lalu pengecualian. Untuk memahami alurnya, beri fungsi pada setiap kalimat sebelum menarik kesimpulan umum. Langkah ini menjaga kita dari mencampurkan penjelasan istilah dengan putusan atas kasus tertentu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L18-S10","level":18,"sublevel":10,"title":"Buka Kitab #18 — Satu Halaman Fikih","conclusion":"Saat membaca satu halaman fikih, jangan hanya mengumpulkan istilah Arab dan padanannya. Temukan susunan argumennya: apa perkara yang dibahas, bagaimana didefinisikan, syarat apa yang ditetapkan, dan bagian mana yang dibatasi atau dikecualikan. Kesimpulan yang baik tetap setia pada cakupan teks, bukan melebarkannya menjadi fatwa baru.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S01","level":19,"sublevel":1,"title":"Matan dan Syarah","conclusion":"Matan ialah teks pokok yang dikutip atau dijelaskan, sedangkan syarah adalah uraian pensyarah tentang teks tersebut. Keduanya perlu dibaca dengan batas yang jelas. Jika penjelasan pensyarah disatukan begitu saja dengan redaksi matan, kita bisa salah menyandarkan suatu ungkapan kepada sumber aslinya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S02","level":19,"sublevel":2,"title":"Struktur Hadis","conclusion":"Dalam teks hadis, pengantar penukilan, sanad, dan matan memiliki fungsi berbeda. Sanad berkaitan dengan jalur periwayatan, sedangkan matan adalah isi yang diriwayatkan. Mengenali strukturnya membantu kita tahu siapa sedang berbicara dan kapan kutipan dimulai, tetapi belum cukup untuk menilai sahih atau tidaknya hadis.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S03","level":19,"sublevel":3,"title":"Fi‘il Riwayat","conclusion":"Fi‘il seperti قال, روى, dan حدث dalam teks riwayat memberi tahu tindakan menyampaikan atau menuturkan. Maknanya harus dibaca bersama subjek dan pelengkap yang mengikutinya. Ketika beberapa pengantar berderet, tandai urutan penutur agar suara periwayat tidak tertukar dengan isi sabda yang dikutip.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S04","level":19,"sublevel":4,"title":"Dhamir dalam Riwayat","conclusion":"Dhamir dalam kalimat riwayat dapat merujuk kepada perawi, guru, atau tokoh yang disebut sebelumnya. Kita tidak boleh langsung mengambil nama terdekat jika bentuk dan alur kalimat menunjukkan hal lain. Carilah kesesuaian persona dan konteks sebelum mengisi “dia” atau “beliau” dalam terjemahan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S05","level":19,"sublevel":5,"title":"Kalimat Sabda","conclusion":"Kalimat sabda atau kutipan perlu dipisahkan dari pengantar penukilannya. Di dalam kutipan, bisa ada berita, perintah, maupun larangan yang mengubah cara menerjemahkan. Tanda batas ujaran lebih penting daripada menambah tanda petik sesuka hati; pastikan kalimat yang dikutip benar-benar berasal dari posisi yang ditunjukkan teks.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S06","level":19,"sublevel":6,"title":"Penjelasan Pensyarah","conclusion":"Pensyarah bisa menjelaskan istilah, memperluas konteks, atau membatasi pemahaman matan. Uraian itu berharga, tetapi tetap perlu dibedakan dari redaksi pokok. Saat meringkas, jelaskan mana yang merupakan kutipan dan mana yang menjadi penafsiran atau penjelasan agar sumber maknanya tidak bergeser.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S07","level":19,"sublevel":7,"title":"Makna Kontekstual","conclusion":"Satu kata dalam hadis atau syarah dapat memiliki beberapa arti yang sah di kamus. Pilihan makna perlu melihat susunan gramatikal, tema, dan keterangan di sekitarnya. Jangan memaksakan arti populer jika hubungan kalimat menuntut makna yang lebih khusus, dan jangan menambah kepastian saat konteksnya belum jelas.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S08","level":19,"sublevel":8,"title":"Kalimat Panjang Syarah","conclusion":"Kalimat syarah sering panjang karena satu pernyataan disusul alasan, contoh, dan pengecualian. Pecah menjadi klausa yang masih utuh, lalu cari hubungan tiap klausa dengan pernyataan sebelumnya. Cara ini membantu kita menerjemahkan tanpa kehilangan arah argumentasi pensyarah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S09","level":19,"sublevel":9,"title":"Membaca Matan + Penjelasan","conclusion":"Membaca matan bersama syarah berarti menjaga dua lapis suara: redaksi pokok dan penjelasannya. Temukan kutipan, pahami makna dasarnya, lalu lihat bagaimana pensyarah menjelaskan atau membatasinya. Terjemahan yang baik menjaga urutan itu supaya pembaca tidak mengira semua kalimat berasal dari narasumber yang sama.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L19-S10","level":19,"sublevel":10,"title":"Buka Kitab #19 — Hadis dan Syarahnya","conclusion":"Pada latihan hadis dan syarah, yang kita uji adalah ketelitian membaca struktur: siapa meriwayatkan, di mana matan dimulai, dan bagaimana penjelasan mengikutinya. Hindari menyisipkan penilaian derajat hadis atau makna hukum yang tidak disediakan sumber. Biarkan perbedaan antara kutipan dan komentar tetap terang dalam terjemahan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S01","level":20,"sublevel":1,"title":"Bahasa Nasihat","conclusion":"Bahasa nasihat dapat berbentuk seruan, anjuran, atau pernyataan yang mengajak pembaca berpikir. Untuk memahaminya, periksa bentuk kalimat serta siapa yang diajak bicara, bukan sekadar mengandalkan kesan emosional. Dalam teks hikmah, pilihan bentuk bisa mengubah nuansa antara mengabarkan dan memerintahkan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S02","level":20,"sublevel":2,"title":"Amar dan Larangan","conclusion":"Amar menyatakan perintah, sedangkan لا الناهية melarang tindakan; keduanya berbeda dari لا النافية yang menyatakan penafian. Lam perintah juga memiliki konstruksi tersendiri. Ketika membaca teks tanpa harakat, cari fi‘il yang mengikuti dan hubungan maknanya agar kita tidak menerjemahkan berita menjadi larangan. Perintah **اُكْتُبْ** ialah fi‘il amar yang mabni pada contoh dasar, sedangkan **لَا تَكْتُبْ** memuat mudhari‘ **majzum** karena **لا الناهية**; jangan menyamakan keduanya dengan penafian **لا** biasa.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S03","level":20,"sublevel":3,"title":"Kalimat Hikmah","conclusion":"Kalimat hikmah sering pendek, tetapi hubungan subjek dan berita di dalamnya tetap penting. Sebuah jumlah ismiyah dapat menyampaikan penegasan yang padat tanpa menyebut tindakan. Jangan tergoda menambah atribusi kepada tokoh tertentu hanya karena susunan kalimat terdengar seperti nasihat yang terkenal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S04","level":20,"sublevel":4,"title":"Makna Abstrak","conclusion":"Kata abstrak seperti kesabaran, kejujuran, atau niat dapat hadir sebagai mashdar atau isim makna. Kita membacanya sebagai gagasan, bukan benda yang bisa disentuh. Untuk menerjemahkan, lihat bagaimana kata itu berhubungan dengan perbuatan dan sifat lain dalam kalimat, sehingga pesan batinnya tidak hilang. **Mashdar** sebagai isim dapat menunjuk makna abstrak seperti kesabaran atau kejujuran tanpa membawa waktu fi‘il; bentuk akhir dan fungsinya tetap ditentukan oleh susunan kalimat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S05","level":20,"sublevel":5,"title":"Sebab-Akibat Batin","conclusion":"Sebab dan akibat dalam nasihat sering berbicara tentang kondisi hati, pilihan, atau perubahan sikap. Hubungan ini bisa ditandai oleh partikel atau susunan klausa tertentu. Bedakan apa yang menjadi alasan dan apa yang merupakan hasilnya; jangan membalik hubungan hanya demi membuat kalimat Indonesia terdengar indah.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S06","level":20,"sublevel":6,"title":"Perumpamaan","conclusion":"Perumpamaan menghubungkan dua hal melalui titik keserupaan tertentu. Tugas pembaca bukan mengartikan setiap citra secara harfiah, tetapi menemukan apa yang dibandingkan dan sisi mana yang memang sama. Jika kiasan dipahami terlalu luas, pesan asli bisa berubah menjadi klaim yang tak pernah dikatakan penulis.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S07","level":20,"sublevel":7,"title":"Dhamir yang Jauh Rujukannya","conclusion":"Dhamir dalam paragraf tasawuf kadang merujuk ke kata yang jauh sebelumnya. Periksa kecocokan bentuk, urutan gagasan, dan kemungkinan rujukannya. Kalau ada dua acuan yang masih masuk akal, lebih baik menyatakan kemungkinan itu daripada membuat satu tafsir terdengar pasti tanpa bukti.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S08","level":20,"sublevel":8,"title":"Makna Harfiah vs Kontekstual","conclusion":"Terjemahan harfiah berguna sebagai pijakan, tetapi maksud kalimat sering membutuhkan konteks. Pada ungkapan nasihat atau kiasan, periksa struktur Arabnya lalu susun bahasa Indonesia yang menyampaikan pesan tanpa memalsukan kata atau hubungan aslinya. Kebebasan menerjemahkan bukan izin menambah isi baru.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S09","level":20,"sublevel":9,"title":"Membaca Paragraf Tasawuf","conclusion":"Paragraf nasihat biasanya punya gagasan pokok, penjelas, dan kadang pembatas atau pengecualian. Temukan inti yang ingin disampaikan, lalu lihat kalimat mana yang mendukungnya. Dengan cara ini, kita bisa menangkap pesan ruhani tanpa mengabaikan ketelitian gramatikal dan batas makna teks.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L20-S10","level":20,"sublevel":10,"title":"Buka Kitab #20 — Membaca Hikmah dan Syarah","conclusion":"Saat membuka hikmah dan syarah, cari pernyataan intinya, pisahkan penjelasan dari kutipan, lalu uji hubungan sebab, kiasan, dan rujukan dhamir. Setelah struktur jelas, baru kita pilih terjemahan yang enak dibaca. Pesan yang menyentuh tetap harus berangkat dari teks, bukan dari tafsir yang kita sisipkan sendiri.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S01","level":21,"sublevel":1,"title":"Satu Tulisan, Beberapa Kemungkinan","conclusion":"Satu tulisan Arab gundul dapat menerima lebih dari satu vokalisasi, terutama ketika bentuk dan konteks belum lengkap. Dua bacaan yang berbeda bisa menghasilkan fungsi atau arti berbeda. Kuncinya bukan menebak yang paling akrab di telinga, melainkan mengumpulkan bukti yang mendukung setiap kemungkinan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S02","level":21,"sublevel":2,"title":"Kata Bermakna Ganda","conclusion":"Sebuah kata bisa mempunyai lebih dari satu makna dalam kamus. Untuk menentukan arti yang cocok, lihat kata tetangga, konstruksi, dan tema kalimat. Makna yang benar di satu halaman belum tentu tepat di halaman lain; polisemi menuntut kita membaca konteks sebelum memilih padanan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S03","level":21,"sublevel":3,"title":"Dhamir Ambigu","conclusion":"Dhamir ambigu muncul ketika rujukan kata ganti belum dapat dipastikan dari bentuk dan alur. Susun kandidat rujukan, periksa kesesuaian jumlah atau gender gramatikal, lalu bandingkan dengan makna kalimat. Jika keduanya masih kuat, tuliskan ambiguitasnya—jangan berpura-pura teks sudah memberi keputusan tunggal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S04","level":21,"sublevel":4,"title":"Na‘at vs Khabar","conclusion":"Na‘at dan khabar bisa tampak mirip dalam teks gundul. Pasangan ma‘rifah–nakirah dan hubungan yang dibentuknya sering membantu: apakah kata kedua masih melekat sebagai sifat, atau sudah menyampaikan berita? Pilihan ini menentukan apakah kita sedang membaca satu frasa atau sebuah kalimat lengkap. Periksa **ma‘rifah–nakirah** dan fungsi kalimat untuk membedakan: **الطَّالِبُ الْمُجْتَهِدُ** dapat menjadi frasa na‘at, sedangkan **الطَّالِبُ مُجْتَهِدٌ** adalah mubtada’–khabar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S05","level":21,"sublevel":5,"title":"Hal vs Sifat","conclusion":"Hal menerangkan keadaan ketika peristiwa berlangsung, sedangkan na‘at menjadi sifat yang mengikuti man‘ut. Ketika harakat hilang, perbedaan keduanya kadang bergantung pada fungsi kalimat serta status kata. Tanyakan apakah keterangan itu menjelaskan “bagaimana saat terjadi” atau “yang seperti apa” dalam frasa nominal. **Hal** sering menerangkan keadaan pada saat peristiwa dan **manshub** dalam pola biasa; **na‘at** menempel sebagai sifat isim serta mengikuti i‘rab man‘ut dalam susunan yang tepat.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S06","level":21,"sublevel":6,"title":"Idhafah Bertingkat","conclusion":"Idhafah bertingkat menghubungkan beberapa isim dalam rantai yang saling bergantung. Kita perlu menentukan pasangan terdekat dan fungsi masing-masing, terutama ketika satu isim menjadi mudhaf ilaih sekaligus mudhaf bagi kata berikutnya. Terjemahan harus mengikuti hubungan itu, bukan sekadar mengurutkan kata satu per satu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S07","level":21,"sublevel":7,"title":"Ma‘lum vs Majhul","conclusion":"Bentuk ma‘lum dan majhul dapat sulit dibedakan tanpa harakat karena sebagian perbedaannya terletak pada vokal. Untuk memutuskan aktif atau pasif, periksa model bacaan, unsur pelaku atau na‘ib fa‘il, dan konteks. Jangan menetapkan siapa melakukan tindakan jika petikan belum memberi bukti yang cukup. Untuk madhi triliteral shahih, bentuk aktif seperti **كَتَبَ** berbeda dari pasif **كُتِبَ** dalam harakat; setelah pasif, periksa **na‘ib fa‘il yang marfu‘**, bukan mencari fa‘il aktif yang tidak disebut.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S08","level":21,"sublevel":8,"title":"Menentukan Bacaan dari Konteks","conclusion":"Konteks bisa menolong memilih satu dari beberapa bacaan, tetapi konteks harus benar-benar terkait dengan struktur dan makna, bukan sekadar tebakan cerita. Kumpulkan petunjuk sebelum dan sesudah kata yang ambigu. Semakin banyak bukti saling mendukung, semakin kuat alasan memilih sebuah vokalisasi.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S09","level":21,"sublevel":9,"title":"Kalau Dua Bacaan Sama-Sama Mungkin?","conclusion":"Dua bacaan yang sama-sama mungkin bukan berarti kita gagal membaca. Justru di situlah ketelitian dibutuhkan: sebutkan pilihan yang tersedia, buktinya, dan apa yang masih kurang untuk memutuskan. Jangan menambahkan kepastian palsu hanya agar jawaban tampak rapi.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L21-S10","level":21,"sublevel":10,"title":"Buka Kitab #21 — Detective Mode","conclusion":"Mode detektif membaca kitab berarti mencari bukti, bukan berburu jawaban cepat. Uji vokal, fungsi na‘at–khabar, rujukan dhamir, idhafah, serta ma‘lum–majhul satu per satu. Ketika analisis belum tunggal, jelaskan kemungkinan yang masih sah agar terjemahan tetap jujur terhadap teks.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S01","level":22,"sublevel":1,"title":"Jangan Terjemahkan Kata per Kata","conclusion":"Terjemahan kata per kata berguna untuk mengenali unsur, tetapi belum tentu menjadi kalimat Indonesia yang benar. Bahasa Arab punya cara menyusun pelaku, objek, dan keterangan yang berbeda. Sebelum menerjemahkan, cari hubungan inti, lalu bangun kalimat Indonesia yang wajar tanpa membuang informasi penting.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S02","level":22,"sublevel":2,"title":"Makna Huruf Sesuai Konteks","conclusion":"Huruf jar dapat berubah padanan menurut fi‘il, isim, dan konteks yang mengikutinya. Satu huruf mungkin bermakna tempat dalam satu kalimat, tetapi menunjukkan alat atau hubungan lain di tempat berbeda. Pilih terjemahan berdasarkan konstruksi utuh, bukan daftar arti tunggal yang dihafal lepas.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S03","level":22,"sublevel":3,"title":"Waqaf Mengubah Pemahaman","conclusion":"Waqaf adalah berhenti saat membaca, dan tempat berhenti bisa memengaruhi pemahaman hubungan kata. Jeda yang memutus unsur yang masih bergantung dapat membuat makna terasa berbeda. Sebelum berhenti, lihat apakah frasa idhafah, sifat, atau klausa penjelas sudah lengkap; jangan meletakkan jeda hanya karena napas habis.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S04","level":22,"sublevel":4,"title":"Washal dan Hubungan Makna","conclusion":"Washal berarti menyambung bacaan, sehingga hubungan antarkata dan antarklausa perlu dijaga saat pengucapan diteruskan. Sebagian makna baru terasa jelas ketika dua bagian dibaca utuh. Untuk menentukan apakah perlu disambung, amati bagian yang masih saling membutuhkan secara struktur dan maksud.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S05","level":22,"sublevel":5,"title":"تقدير: Unsur yang Dipahami Walau Tak Tertulis","conclusion":"Taqdir adalah memperkirakan unsur yang tidak tertulis tetapi dipahami dari konstruksi atau konteks yang jelas. Kita hanya boleh melakukannya bila ada alasan gramatikal atau makna yang kuat. Jangan menambah subjek, predikat, atau kata penghubung sesuka hati hanya supaya terjemahan Indonesia terdengar lebih panjang.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S06","level":22,"sublevel":6,"title":"Taqdim–Ta’khir","conclusion":"Taqdim–ta’khir adalah pendahuluan atau pengakhiran unsur dari urutan yang lazim, seperti khabar yang muncul sebelum mubtada’. Urutan teks mungkin berubah, tetapi tugas kata tetap bisa dikenali dari susunannya. Dengan memahami ini, kita tidak perlu memaksakan terjemahan mengikuti posisi kata Arab secara kaku.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S07","level":22,"sublevel":7,"title":"Makna Literal vs Maksud Kalimat","conclusion":"Makna literal merupakan arti yang dekat dengan bunyi dan kata asal, sedangkan maksud kalimat bisa lebih luas atau kiasan sesuai konteks. Saat menjumpai ungkapan tidak biasa, periksa apakah pembacaan harfiah masuk akal dan didukung struktur. Jangan buru-buru menganggap semua kalimat bergambar sebagai kiasan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S08","level":22,"sublevel":8,"title":"Memilih Terjemahan yang Wajar","conclusion":"Terjemahan yang wajar enak dibaca dalam bahasa Indonesia, tetapi harus tetap memelihara siapa melakukan, apa yang terjadi, dan batas makna yang dinyatakan sumber. Kita boleh menata ulang urutan katanya tanpa mengganti isi. Uji hasilnya dengan bertanya apakah setiap unsur penting Arab masih punya tempat dalam terjemahan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S09","level":22,"sublevel":9,"title":"Membuktikan Terjemahan dari Struktur","conclusion":"Untuk membuktikan terjemahan, tunjukkan dasar nahwunya: fi‘il, fa‘il, maf‘ul, hubungan jar, serta tanda i‘rab yang relevan. Kalau hasil Indonesia terdengar bagus tetapi susunan Arabnya tidak mendukung, terjemahan itu perlu diperiksa ulang. Keindahan bahasa tidak boleh menggantikan bukti gramatikal.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L22-S10","level":22,"sublevel":10,"title":"Buka Kitab #22 — Terjemahkan, Lalu Pertanggungjawabkan","conclusion":"Dalam tantangan dua klausa, kita tidak hanya diminta membuat terjemahan yang indah. Pisahkan hubungan setiap bagian, temukan pelaku dan pembatas, tentukan titik sambung atau jeda, lalu pertanggungjawabkan keputusan maknanya. Terjemahan yang kuat dapat dijelaskan kembali dari teks Arabnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S01","level":23,"sublevel":1,"title":"Preview Sebelum Membaca","conclusion":"Preview sebelum membaca berarti melihat arah halaman sebelum menyelami setiap kata: apa tema umum, bentuk uraian, dan unsur yang paling menonjol. Kita tidak sedang menebak isi final. Peta awal itu membantu memilih perhatian agar paragraf gundul tidak terasa seperti deretan huruf tanpa pegangan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S02","level":23,"sublevel":2,"title":"Tandai Struktur Besar","conclusion":"Satu halaman biasanya mempunyai struktur besar: pembuka, penjelas, contoh, pembatas, lalu mungkin kesimpulan. Menandai fungsi bagian-bagian itu membantu kita mengikuti alur penulis. Jangan menyamakan semua kalimat sebagai ide pokok; sebagian hanya memberi alasan, syarat, atau rincian.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S03","level":23,"sublevel":3,"title":"Baca Tanpa Kamus Dahulu","conclusion":"Membaca tanpa kamus dahulu bukan berarti mengabaikan makna kata yang sulit. Kita berusaha menangkap garis besar dengan bantuan struktur, kata yang sudah dikenal, dan konteks. Setelah tahu arah halaman, barulah kamus dipakai untuk bagian yang benar-benar menghambat pemahaman.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S04","level":23,"sublevel":4,"title":"Tandai Kata Sulit","conclusion":"Tidak semua kata asing membutuhkan waktu pencarian yang sama. Tandai yang belum dikenal, lalu pisahkan mana yang menentukan inti pesan dan mana yang hanya rincian. Prioritaskan kata yang mengubah siapa, apa, atau hubungan antarklausa agar kerja membaca tetap efisien.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S05","level":23,"sublevel":5,"title":"Gunakan Kamus Secukupnya","conclusion":"Kamus membantu jika kita sudah tahu apa yang ingin dicari. Pada kamus berbasis akar, bentuk turunan perlu dikembalikan ke akar; pada sistem lain kita bisa mencari bentuk tertulis. Setelah menemukan beberapa arti, uji terhadap wazan dan susunan kalimat, jangan langsung mengambil arti pertama.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S06","level":23,"sublevel":6,"title":"Harakati Bagian Penting","conclusion":"Harakat penuh tidak selalu perlu dipasang pada seluruh halaman sejak awal. Pilih bagian yang paling menentukan hubungan makna—misalnya fa‘il, objek, atau unsur setelah huruf jar—lalu beri tanda berdasarkan fungsi. Jika bagian lain masih ambigu, biarkan sementara tanpa membuat bacaan palsu.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S07","level":23,"sublevel":7,"title":"Temukan Ide Pokok","conclusion":"Ide pokok ialah gagasan yang mengikat satu paragraf, sedangkan contoh dan alasan hanya mendukungnya. Kita bisa menemukannya dengan melihat apa yang terus dijelaskan atau dibatasi. Jangan memilih kalimat paling panjang sebagai inti hanya karena tampak paling lengkap.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S08","level":23,"sublevel":8,"title":"Terjemahkan Paragraf","conclusion":"Menerjemahkan paragraf berarti menjaga hubungan antarkalimat, bukan membuat daftar arti yang berdiri sendiri. Kita periksa peristiwa, rujukan dhamir, sebab, syarat, serta contoh yang menyertainya. Setelah semuanya terhubung, barulah susunan bahasa Indonesia dirapikan tanpa menghilangkan nuansa penting.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S09","level":23,"sublevel":9,"title":"Ringkas Isi Halaman","conclusion":"Ringkasan satu halaman mengambil inti pembahasan dan batasnya, bukan mengulang setiap kalimat dengan kata yang lebih pendek. Cari gagasan utama, alasan, dan pengecualian penting. Jika sebuah syarat dihapus, ringkasan mungkin menjadi terlalu luas; karena itu, singkat harus tetap setia pada makna.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L23-S10","level":23,"sublevel":10,"title":"Buka Kitab #23 — Satu Halaman Tanpa Pegangan","conclusion":"Saat membaca satu halaman baru dengan bantuan minimal, urutannya bisa sederhana: lihat peta umum, kenali struktur, cari jangkar makna, pakai kamus seperlunya, lalu harakati dan terjemahkan bagian penting. Setelah itu buat ringkasan singkat yang masih bisa dibuktikan dari teks. Kemandirian tumbuh dari kebiasaan memeriksa alasan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S01","level":24,"sublevel":1,"title":"Cold Reading: Teks Baru","conclusion":"Cold reading berarti menghadapi petikan yang belum pernah dibahas tanpa bergantung pada hafalan contoh tertentu. Kita mulai dari bukti yang terlihat: batas kata, jenis unsur, dan hubungan antarklausa. Kalau ada yang belum pasti, nyatakan sebagai kemungkinan sampai struktur dan konteks mendukung satu bacaan.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S02","level":24,"sublevel":2,"title":"Tentukan Jenis Kata","conclusion":"Langkah dasar memahami teks baru ialah menentukan mana isim, fi‘il, dan huruf. Jenis kata ini membantu menjawab apa yang disebut, peristiwa apa yang berlangsung, dan bagaimana unsur-unsurnya dihubungkan. Jangan hanya menghafal nama kategori; tunjukkan jejak bentuk atau tugasnya di kalimat. Pemeriksaan tercepat adalah **isim = nama/makna**, **fi‘il = peristiwa + waktu**, **huruf = penghubung**; konfirmasikan dengan bentuk dan tugasnya, lalu tentukan posisi i‘rabnya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S03","level":24,"sublevel":3,"title":"Temukan Susunan","conclusion":"Setelah jenis kata dikenali, petakan susunan: jumlah ismiyah, jumlah fi‘liyah, idhafah, na‘at, dan klausa penjelas. Susunan menentukan pasangan kata yang saling bergantung. Jika struktur besar salah dipotong, analisis i‘rab dan terjemahan berikutnya mudah ikut meleset.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S04","level":24,"sublevel":4,"title":"Temukan ‘Amil","conclusion":"‘Amil membantu menjelaskan mengapa sebuah unsur berstatus rafa‘, nashab, jar, atau jazm dalam konstruksi tertentu. Cari unsur yang memengaruhi sebelum memutuskan harakat. Tidak semua pengaruh menjangkau seluruh kalimat; tentukan batas kerjanya dengan teliti. ‘Amil menjawab **mengapa** kedudukan kata berubah: setelah huruf jar isim **majrur**, setelah **لَمْ** mudhari‘ **majzum**, dan setelah **إِنَّ** isimnya **manshub** dalam pola dasar.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S05","level":24,"sublevel":5,"title":"Tentukan I‘rab","conclusion":"Menentukan i‘rab berarti memilih status gramatikal berdasarkan fungsi kata, kemudian mencari tanda yang sesuai dengan bentuknya. Pada isim mufrad biasa tanda asalnya berbeda dari mutsanna atau bentuk khusus. Bedakan status dan tanda: keduanya saling berkaitan tetapi bukan pertanyaan yang sama. I‘rab jangan ditebak dari akhir yang terdengar: tentukan **fungsi kata → status → tanda**; rafa‘ bisa dhammah/alif/wawu, nashab bisa fathah/ya/kasrah menurut bentuknya.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S06","level":24,"sublevel":6,"title":"Beri Harakat","conclusion":"Memberi harakat pada teks gundul adalah tahap akhir dari proses memahami bentuk dan susunan. Kita hanya menambahkan tanda yang punya alasan dari nahwu, sharaf, atau konteks yang cukup. Jangan mengisi setiap vokal demi penampilan rapi jika masih ada dua bacaan yang sama-sama mungkin. Saat memberi harakat pada halaman baru, **jenis kata dan pola bentuk** diperiksa lebih dulu, baru **‘amil dan fungsi** menentukan akhir; untuk kata mabni, jangan memaksakan perubahan seperti kata mu‘rab.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S07","level":24,"sublevel":7,"title":"Terjemahkan","conclusion":"Terjemahan petikan baru harus menjaga inti peristiwa, pelaku, objek, sebab, syarat, dan pembatas yang memang ada. Susun ulang bahasa Indonesia agar alami, tetapi jangan menambah isi di luar teks. Hasil terbaik bukan yang paling berbunga-bunga, melainkan yang maknanya bisa ditelusuri kembali.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S08","level":24,"sublevel":8,"title":"Jelaskan Alasan Bacaan","conclusion":"Alasan bacaan adalah bagian dari jawaban, bukan catatan tambahan. Ketika memilih harakat atau arti, jelaskan jenis katanya, fungsi dalam susunan, dan bukti bentuk yang mendukungnya. Jika ada pilihan lain yang tampak mungkin, tunjukkan mengapa pilihan kita lebih kuat atau mengapa kesimpulan masih terbuka.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S09","level":24,"sublevel":9,"title":"Baca Halaman Baru dengan Bantuan Minimal","conclusion":"Membaca dengan bantuan minimal bukan berarti membaca tanpa pemeriksaan. Temukan struktur utama, gunakan pengetahuan akar dan i‘rab, lalu pakai rujukan hanya saat benar-benar diperlukan. Ukuran kemajuan kita adalah kemampuan menjelaskan pilihan bacaan, bukan jumlah kata yang berhasil ditebak.","source":"NAHWOO editorial 24-level approved draft"},{"id":"L24-S10","level":24,"sublevel":10,"title":"Final Boss — Buka Kitab yang Belum Pernah Kita Pelajari","conclusion":"Pada tantangan akhir, semua bekal dipakai sekaligus: mengurai teks baru, mengenali jenis kata, mencari ‘amil, menentukan i‘rab, memeriksa fi‘il, lalu menyusun terjemahan. Setelah selesai, nilai bukan cuma hasilnya, tetapi juga alasan setiap langkah dan keberanian mengakui bagian yang belum pasti. Itulah cara membaca kitab dengan bertanggung jawab.","source":"NAHWOO editorial 24-level approved draft"}]};
